var CHAPTERS = [{"id": 1, "no": "Ⅰ", "title": "安装与第一个程序", "weeks": "第 1 周", "diff": "★☆☆", "full": true, "story": {"tutor": "吉多·范罗苏姆（Guido van Rossum）", "era": "荷兰 · Python 之父", "fact": "1989 年圣诞节，Guido 想找点事做，决定写一门「读起来像英语」的脚本语言。他给它起名 Python——因为他喜欢喜剧团体 Monty Python。他定的设计哲学第一条就是「可读性优先」：代码首先是给人读的，其次才是给机器跑的。", "quote": "「代码写出来是给人看的，只是顺便能在机器上跑。」—— Guido van Rossum"}, "map": ["Python 是什么", "print 与注释", "运行代码", "读报错"], "sections": [{"t": "Python 是什么：给谁的语言", "p": "Python 是一门<strong>解释型</strong>语言：写一行、解释一行、跑一行。它不要求你先编译再运行，天然适合「边写边试」。它的哲学叫 <b>Pythonic</b>——用最少的代码做明白的事。你现在用的浏览器里就有个 Python 运行时（Pyodide），下面每道代码题都能直接跑。", "code": "print(\"Hello Python!\")\n# 输出：Hello Python!"}, {"t": "print：程序的嘴巴", "p": "print() 把内容送到屏幕。字符串要用引号包（单双都行，别混用）。可以一次打印多件东西，逗号会自动加空格。print 是你看程序的窗口——所有「程序到底干了什么」都靠它看见。", "code": "print(\"我叫\", \"鼠哥\")\nprint(\"答案 =\", 1 + 2)"}, {"t": "注释：写给未来自己的信", "p": "# 开头的是注释，机器忽略，给人看。写注释是给「三个月后的自己」留线索：这段代码为什么这么写、坑在哪。好注释说「为什么」，不说「是什么」（是什么代码自己会说话）。", "code": "# 计算矩形面积\nw = 5  # 宽\nh = 3  # 高\nprint(w * h)"}, {"t": "读报错：报错是线索不是惩罚", "p": "报错信息逐字读：它会告诉你错在第几行、什么类型（SyntaxError=语法错、NameError=名字没定义）。程序员的日常一半是读报错。冷静、逐行、改一个错试一次。", "code": "# 故意报错看看：把下面取消注释运行\n# print(\"少了右引号)"}], "quiz": [{"type": "choice", "q": "print 的作用是？", "options": ["把电脑里的文件打印出来", "把内容显示到屏幕", "让电脑说话", "保存文件"], "answer": 1, "explain": "print 把内容输出到屏幕，是程序与人对话的窗口。"}, {"type": "choice", "q": "这段代码哪里错了：print(\"你好) ", "options": ["print 拼错", "引号没有成对", "少了括号", "没有错"], "answer": 1, "explain": "字符串 \"你好 少了右引号，属于 SyntaxError（语法错误）。引号必须成对。"}, {"type": "code", "q": "输出两行：第一行 I love Python，第二行 42（数字直接写不用引号）", "code": "print(\"I love Python\")\nprint(42)", "expect": "I love Python\n42", "hint": "两行两个 print。"}, {"type": "code", "q": "（思考★）程序想输出：总计: 7 元。有人写成 print(\"总计:\", 7, \"元\") 输出了总计: 7 元，但冒号后有空格。请用逗号参数实现输出为 总计:7 元（冒号后无空格）", "code": "print(\"总计:\", 7, \"元\")\n# 修正：让冒号后面没有空格", "expect": "总计: 7 元", "hint": "提示：原样会输出 \"总计: 7 元\"（冒号后带空格）。想想怎么把冒号和数字连在一起——用字符串拼接或 f-string（下章会学，可先用 + 拼接：print(\"总计:\" + \"7\" + \" 元\")），本判题接受两种修正，只要输出一致即可。", "explain_note": ""}, {"type": "choice", "q": "print(2 + 3 * 2) 输出？", "options": ["10", "8", "12", "7"], "answer": 1, "explain": "乘除先于加减：3*2=6，2+6=8。"}, {"type": "choice", "q": "哪行能正确输出带空格的问候？", "options": ["print(\"Hi\" + \"!\" )", "print(\"Hi\",\"Bob\")", "print(\"Hi\" \"Bob\")", "print(\"Hi\" - \"Bob\")"], "answer": 1, "explain": "逗号打印多项自动加空格。"}, {"type": "code", "q": "输出三行：第1行 python 第2行 是 第3行 有趣的", "code": "print(\"python\")\nprint(\"是\")\nprint(\"有趣的\")", "expect": "python\n是\n有趣的", "hint": "三行三个 print。"}, {"type": "choice", "q": "NameError 表示？", "options": ["名字拼错/未定义", "语法括号错", "数字溢出", "文件没保存"], "answer": 0, "explain": "NameError = 用了一个没定义的名字，多半拼错变量名。"}, {"type": "code", "q": "用两个 print 输出：5 + 3 = 8（前后两行分开打：先打 5 + 3 = 再打 8）", "code": "print(\"5 + 3 =\")\nprint(8)", "expect": "5 + 3 =\n8", "hint": "第一个 print 打字符串，第二个打数字。"}, {"type": "choice", "q": "代码第一行是 print(\"开始\") 第二行是 # 注释 第三行 print(\"结束\")，输出？", "options": ["开始 结束", "开始", "结束", "开始\n结束"], "answer": 3, "explain": "注释行不执行，两行 print 各输出一行。"}], "exam": [{"type": "choice", "q": "Python 是一门什么类型的语言？", "options": ["编译型", "解释型", "机器语言", "汇编语言"], "answer": 1, "explain": "解释型：边解释边执行，适合边写边试。"}, {"type": "choice", "q": "注释符号是？", "options": ["//", "/* */", "#", "--"], "answer": 2, "explain": "Python 用 # 表示注释。"}, {"type": "code", "q": "输出一行：你好，世界", "code": "print(\"你好，世界\")", "expect": "你好，世界", "hint": "print 加中文字符串。"}, {"type": "choice", "q": "报错信息里写着 line 3，意思是？", "options": ["程序要运行 3 次", "错误在第 3 行附近", "第 3 个变量错了", "文件只有 3 行"], "answer": 1, "explain": "line N 指错误出现在第 N 行附近，逐行往上找。"}, {"type": "code", "q": "（改错★）下面代码报 SyntaxError，请修正：print(\"加油!", "code": "print(\"加油!\")", "expect": "加油!", "hint": "字符串少了右引号，补上即可。"}, {"type": "choice", "q": "print(1 + 1) 输出什么？", "options": ["\"1 + 1\"", "11", "2", "报错"], "answer": 2, "explain": "数字相加就是数学加法，输出 2。"}, {"type": "code", "q": "输出乘法口诀第一行：1 x 1 = 1", "code": "print(\"1 x 1 = 1\")", "expect": "1 x 1 = 1", "hint": "整行作为字符串打印。"}, {"type": "choice", "q": "print(\"a\", \"b\") 和 print(\"a\" + \"b\") 的区别？", "options": ["没区别", "前者输出 a b，后者输出 ab", "前者报错", "后者报错"], "answer": 1, "explain": "逗号分隔是「打印多项」自动加空格；+ 是字符串拼接，不加空格。"}, {"type": "code", "q": "打印第一行注释示例：在代码中注释一行 # 明天再优化 并输出 开始", "code": "# 明天再优化\nprint(\"开始\")", "expect": "开始", "hint": "注释不影响输出。"}, {"type": "choice", "q": "print(\"1\" + \"1\") 输出？", "options": ["2", "11", "1 1", "报错"], "answer": 1, "explain": "字符串 + 是拼接，\"1\"+\"1\"=\"11\"。"}]}, {"id": 2, "no": "Ⅱ", "title": "变量与类型", "weeks": "第 1 周", "diff": "★☆☆", "full": true, "story": {"tutor": "凯瑟琳·约翰逊（Katherine Johnson）", "era": "美国 · 数学家", "fact": "阿波罗登月的轨道计算由凯瑟琳完成。手工计算时代，一个数字的精度就是一次发射的成败。她最清楚「变量」的意义：同一个公式，代入不同数据，得到不同结果——变量就是公式里那个「可以换的数」。", "quote": "「我们按需求计算，不是按猜测。」—— Katherine Johnson"}, "map": ["变量是什么", "命名规则", "三种基本类型", "类型转换"], "sections": [{"t": "变量：给数据起名字", "p": "变量 = 名字 + 值。等号是「赋值」不是「等于」：a = 5 读作「把 5 放进 a」。变量可以重新赋值，变量参与运算。用变量让你的程序「说人话」：price、score 比裸数字好懂一百倍。", "code": "score = 95\nscore = score + 5   # 右边先算：95+5\nprint(score)         # 100"}, {"t": "命名规则：怎么起好名字", "p": "规则：只能字母数字下划线、不能数字开头、不能用关键字（if/for/class…）。风格：小写 + 下划线（snake_case）：my_score、total_price。名字要表达含义——三个月后你读代码，名字就是记忆。", "code": "user_name = \"鼠哥\"\nuser_age = 18\nprint(user_name, user_age)"}, {"t": "三种基本类型", "p": "int 整数（5）、float 小数（3.14）、str 字符串（\"hi\"）。type() 能查类型。混用要注意：字符串和数字不能直接相加（会 TypeError），要先转换。", "code": "print(type(5))        # <class 'int'>\nprint(type(3.14))     # <class 'float'>\nprint(type(\"5\"))      # <class 'str'>"}, {"t": "类型转换：让类型对得上", "p": "int(\"5\") 字符串转整数、str(5) 数字转字符串、float(\"2.5\") 转小数。input() 永远返回字符串——要算数必须先转换。转换失败会 ValueError（\"abc\" 转不了整数）。", "code": "age = input(\"几岁？\")   # 输入 18\nprint(type(age))        # str！\nnext_age = int(age) + 1\nprint(\"明年\", next_age, \"岁\")"}], "quiz": [{"type": "choice", "q": "a = 10; a = a + 5 之后 a 是？", "options": ["10", "15", "105", "报错"], "answer": 1, "explain": "a = a + 5 右边先算 10+5=15 再赋给 a。"}, {"type": "choice", "q": "哪个是合法变量名？", "options": ["1st_place", "first place", "first_place", "class"], "answer": 2, "explain": "不能数字开头、不能有空格、class 是关键字。"}, {"type": "code", "q": "定义变量 w=6, h=4，输出矩形的面积（乘法用 *）", "code": "w = 6\nh = 4\nprint(w * h)", "expect": "24", "hint": "面积 = 长 × 宽。"}, {"type": "code", "q": "（改错★）下面代码报错，请修正让它输出 我今年 18 岁：age = 18; print(\"我今年 \" + age + \" 岁\")", "code": "age = 18\nprint(\"我今年 \" + str(age) + \" 岁\")", "expect": "我今年 18 岁", "hint": "字符串和 int 不能直接 +，用 str(age) 转换。"}, {"type": "choice", "q": "a = 5; b = a; b = 10; print(a) 输出？", "options": ["10", "5", "报错", "15"], "answer": 1, "explain": "b=a 把 5 复制给 b，之后改 b 不影响 a。"}, {"type": "choice", "q": "int(3.99) 返回？", "options": ["4", "3.99", "3", "报错"], "answer": 2, "explain": "int() 直接截断小数部分，不四舍五入。"}, {"type": "code", "q": "num = \"7\"，把它当数字加 3 输出", "code": "num = \"7\"\nprint(int(num) + 3)", "expect": "10", "hint": "先 int() 转换。"}, {"type": "choice", "q": "哪个变量名非法？", "options": ["_temp", "myVar2", "2fast", "中文名"], "answer": 2, "explain": "不能以数字开头。中文变量名合法但不推荐。"}, {"type": "code", "q": "摄氏 25 度 = 华氏多少度：F = C * 9 / 5 + 32，输出结果", "code": "C = 25\nF = C * 9 / 5 + 32\nprint(F)", "expect": "77.0", "hint": "25*9/5+32 = 77.0。"}, {"type": "choice", "q": "x = \"3.5\"; type(x) 是？", "options": ["float", "int", "str", "bool"], "answer": 2, "explain": "有引号就是字符串，不管内容像不像数字。"}], "exam": [{"type": "choice", "q": "type(\"42\") 返回？", "options": ["int", "float", "str", "list"], "answer": 2, "explain": "\"42\" 有引号是字符串。"}, {"type": "choice", "q": "x = 3.0 的类型是？", "options": ["int", "float", "str", "bool"], "answer": 1, "explain": "3.0 是小数即 float。"}, {"type": "code", "q": "把字符串 \"2026\" 转成整数并 +1 输出", "code": "n = int(\"2026\")\nprint(n + 1)", "expect": "2027", "hint": "int() 转换后再加。"}, {"type": "choice", "q": "下列哪行会报 TypeError？", "options": ["print(\"a\" + \"b\")", "print(\"a\" + 1)", "print(1 + 2)", "print(\"1\" + \"2\")"], "answer": 1, "explain": "字符串和整数不能直接相加。"}, {"type": "code", "q": "（思考★）身高 1.75 米存进变量 h，输出：身高 175.0 厘米", "code": "h = 1.75\nprint(\"身高\", h * 100, \"厘米\")", "expect": "身高 175.0 厘米", "hint": "米转厘米乘 100，1.75*100=175.0（float）。"}, {"type": "choice", "q": "int(\"3.14\") 会？", "options": ["返回 3", "返回 3.14", "报 ValueError", "返回 314"], "answer": 2, "explain": "\"3.14\" 不是整数字面量，int() 转换会抛 ValueError。"}, {"type": "code", "q": "交换两个变量：a=1,b=2 变成 a=2,b=1 并输出 a b", "code": "a, b = 1, 2\na, b = b, a\nprint(a, b)", "expect": "2 1", "hint": "Python 支持一行交换 a, b = b, a。"}, {"type": "choice", "q": "x = 5; x = \"五\"; print(type(x)) 输出？", "options": ["int", "str", "报错", "5"], "answer": 1, "explain": "变量可以重新赋不同类型，最后是字符串。"}, {"type": "code", "q": "把整数 99 转成字符串并与 \"分\" 拼接输出", "code": "s = str(99) + \"分\"\nprint(s)", "expect": "99分", "hint": "str() 转换后拼接。"}, {"type": "choice", "q": "float(\"abc\") 会？", "options": ["返回 0.0", "报 ValueError", "返回 abc", "返回 NaN"], "answer": 1, "explain": "非数字字符串转 float 抛 ValueError。"}]}, {"id": 3, "no": "Ⅲ", "title": "字符串方法", "weeks": "第 2 周", "diff": "★★☆", "full": true, "story": {"tutor": "格蕾丝·赫柏（Grace Hopper）", "era": "美国 · 编译先驱", "fact": "赫柏说「在编程里，与其道歉不如先验证」。她发明了最早的编译器之一，坚信人类该用接近自然语言的符号写程序。字符串处理正是程序员的日常：清洗、拼接、查找——机器读的和你读的，都是字符串。", "quote": "「生活中最容易的事情是说『做不到』。」—— Grace Hopper"}, "map": ["大小写三兄弟", "strip 清洗", "查找与替换", "拼接与拆解"], "sections": [{"t": "大小写：title/upper/lower", "p": "字符串方法是「值.方法()」。title() 每个词首字母大写、upper() 全大写、lower() 全小写。方法返回<strong>新字符串</strong>——原字符串不变，要保存结果得重新赋值。", "code": "name = \"ada lovelace\"\nprint(name.title())\nprint(name.upper())\nprint(name)          # 原串没变"}, {"t": "strip：清理两侧空白", "p": "数据常常带着多余空格（用户输入、文件读取）。strip() 去掉两侧空白，lstrip/rstrip 去左/右。习惯：读进来的字符串先 strip 再处理，避免 \"abc\" != \"abc \" 的坑。", "code": "s = \"  python  \"\nprint(s.strip())\nprint(s.lstrip())\nprint(s.rstrip())"}, {"t": "查找替换：find/replace", "p": "find(\"x\") 返回 x 第一次出现的位置（找不到返回 -1）；replace(a, b) 把所有 a 换成 b。还有 in 运算符判断「某串在不在里面」，返回 True/False。", "code": "msg = \"I love Python\"\nprint(msg.find(\"love\"))   # 2\nprint(\"Python\" in msg)    # True\nprint(msg.replace(\"love\", \"like\"))"}, {"t": "拼接与拆解", "p": "+ 拼接、join 用分隔符拼列表、split 按分隔符拆成列表。split/join 是数据清洗的黄金组合。", "code": "words = [\"2026\", \"09\", \"01\"]\nprint(\"-\".join(words))\ndate = \"2026-09-01\"\nprint(date.split(\"-\"))"}], "quiz": [{"type": "choice", "q": "\"hello\".upper() 返回？", "options": ["Hello", "HELLO", "hello", "报错"], "answer": 1, "explain": "upper() 全大写。"}, {"type": "choice", "q": "\"a b \".strip() 的结果是？", "options": ["\"a b\"", "\"ab\"", "\" a b\"", "\"a b \""], "answer": 0, "explain": "strip 只去两端空白，中间的保留。"}, {"type": "code", "q": "把名字 \"  xiao ming  \" 清理两侧空格并首字母大写输出", "code": "name = \"  xiao ming  \"\nprint(name.strip().title())", "expect": "Xiao Ming", "hint": "先 strip 再 title，链式调用。"}, {"type": "code", "q": "（思考★）判断邮箱是否合法小写：user@X.COM 转小写后判断是否包含 \"@\"，分别输出 合法/不合法", "code": "email = \"USER@X.COM\"\nif \"@\" in email.lower():\n    print(\"合法\")\nelse:\n    print(\"不合法\")", "expect": "合法", "hint": "lower() 后 in 判断。"}, {"type": "choice", "q": "\"hello world\".replace(\"l\",\"L\") 的结果含几个 L？", "options": ["1", "2", "3", "0"], "answer": 2, "explain": "hello 有 2 个 l、world 有 1 个 l，共 3 个 l 全部换成 L。"}, {"type": "choice", "q": "\"ABcd\".lower() == \"abcd\" 的返回？", "options": ["True", "False", "报错", "比较对象不同"], "answer": 0, "explain": "lower 后两边都是 abcd，相等为 True。"}, {"type": "code", "q": "把句子中所有的 2 换成 3：\"2 x 2 = 4\"", "code": "s = \"2 x 2 = 4\"\nprint(s.replace(\"2\", \"3\"))", "expect": "3 x 3 = 4", "hint": "replace 替换所有出现。"}, {"type": "choice", "q": "\"racecar\" 用 split(\"c\") 得到？", "options": ["[\"ra\",\"e\",\"ar\"]", "[\"r\",\"e\",\"r\"]", "[\"race\",\"car\"]", "报错"], "answer": 0, "explain": "按 c 拆成三节：ra、e、ar。", "note": ""}, {"type": "code", "q": "判断 \"python\" 是否在 \"I love python\" 中，输出 在 或 不在", "code": "s = \"I love python\"\nif \"python\" in s:\n    print(\"在\")\nelse:\n    print(\"不在\")", "expect": "在", "hint": "in 判断子串。"}, {"type": "choice", "q": "\"  a  b  \".strip() 结果是？", "options": ["\"a b\"", "\"a  b\"", "\"ab\"", "\"  a  b\""], "answer": 1, "explain": "strip 只去首尾空白，中间两个空格保留。"}], "exam": [{"type": "choice", "q": "\"PYTHON\".lower() 输出？", "options": ["PYTHON", "python", "Python", "报错"], "answer": 1, "explain": "lower 全小写。"}, {"type": "choice", "q": "\"banana\".replace(\"a\", \"o\") 输出？", "options": ["bonono", "banono", "banona", "报错"], "answer": 0, "explain": "replace 替换所有 a 为 o。"}, {"type": "code", "q": "s = \"  hello world  \"，strip 后 split 成单词，打印列表", "code": "s = \"  hello world  \"\nprint(s.strip().split(\" \"))", "expect": "['hello', 'world']", "hint": "注意输出的是列表字面量。"}, {"type": "choice", "q": "\"abc\".find(\"z\") 返回？", "options": ["0", "-1", "报错", "3"], "answer": 1, "explain": "找不到返回 -1。"}, {"type": "code", "q": "把 \"2026/09/01\" 按 / 拆开，输出中间的 09", "code": "d = \"2026/09/01\"\nprint(d.split(\"/\")[1])", "expect": "09", "hint": "split 得 [\"2026\",\"09\",\"01\"]，取下标 1。"}, {"type": "choice", "q": "\"python is fun\".title() 输出？", "options": ["Python Is Fun", "python is fun", "Python is fun", "PYTHON IS FUN"], "answer": 0, "explain": "title 每个单词首字母大写。"}, {"type": "code", "q": "（思考★）用户输入可能带空格和大小写，判断内容是否为 \"quit\"（容忍两侧空格和大写）", "code": "cmd = \"  QUIT  \"\nif cmd.strip().lower() == \"quit\":\n    print(\"退出\")\nelse:\n    print(\"继续\")", "expect": "退出", "hint": "先 strip 再 lower 再比较。"}, {"type": "choice", "q": "len(\"你好py\") 返回？", "options": ["4", "5", "6", "8"], "answer": 0, "explain": "len 数字符个数，\"你好\"2 个 + \"py\"2 个 = 4。"}, {"type": "code", "q": "取 \"python-2026\" 中 \"2026\"（用 split 按 - 拆）", "code": "s = \"python-2026\"\nprint(s.split(\"-\")[1])", "expect": "2026", "hint": "split(\"-\") 取下标 1。"}, {"type": "choice", "q": "\"hello\".find(\"ll\") 返回？", "options": ["1", "2", "3", "-1"], "answer": 1, "explain": "ll 从下标 2 开始：h(0)e(1)l(2)l(3)，find 返回 2。"}]}, {"id": 4, "no": "Ⅳ", "title": "f-string 与数字", "weeks": "第 2 周", "diff": "★★☆", "full": true, "story": {"tutor": "玛格丽特·汉密尔顿（Margaret Hamilton）", "era": "美国 · 阿波罗软件工程", "fact": "阿波罗登月导航软件总负责人汉密尔顿，最懂「数字的精度」：一个小数点能决定一次着陆。她推动的容错设计理念——程序要处理异常输入——至今仍是软件工程的基石。数字格式化和精度控制，就是她的战场。", "quote": "「在软件的世界里，出错不是选项。」—— Margaret Hamilton"}, "map": ["f-string 是什么", "格式化数字", "算术与优先级", "除法的两种结果"], "sections": [{"t": "f-string：把变量嵌进字符串", "p": "f 前缀 + 花括号：f\"{变量}\"。花括号里的表达式会先求值再变成字符串。比 + 拼接干净百倍，Python 3.6+ 标配。", "code": "name = \"鼠哥\"\nscore = 98\nprint(f\"{name} 考了 {score} 分\")\nprint(f\"明年 {score + 1} 分的目标\")"}, {"t": "格式化数字：对齐与精度", "p": "f\"{x:.2f}\" 保留两位小数；f\"{x:>6}\" 右对齐宽度 6；f\"{pct:.1%}\" 百分比。输出报表对齐、价格保留两位，全靠这些。", "code": "price = 3.14159\nprint(f\"{price:.2f}\")\nprint(f\"{price:8.2f}\")   # 右对齐宽 8\nprint(f\"{0.1856:.1%}\")    # 18.6%"}, {"t": "算术与优先级", "p": "+ - * /（真除法 7/2=3.5）//（整除 7//2=3）%（取余 7%2=1）**（幂）。优先级跟数学一样：括号 > 幂 > 乘除 > 加减。", "code": "print(7 / 2)   # 3.5\nprint(7 // 2)  # 3\nprint(7 % 2)   # 1\nprint(2 ** 3)  # 8"}, {"t": "整除与取余：秒转时分秒", "p": "// 取商、% 取余，配合能拆解单位：总秒数 → 小时/分钟/秒。这是「拆单位」的万能模板。", "code": "total = 3661\nh = total // 3600\nm = (total % 3600) // 60\ns = total % 60\nprint(f\"{h}时{m}分{s}秒\")   # 1时1分1秒"}], "quiz": [{"type": "choice", "q": "7 // 2 的结果是？", "options": ["3.5", "3", "4", "报错"], "answer": 1, "explain": "// 整除向下取整，7//2=3。"}, {"type": "choice", "q": "f\"{5 + 3}\" 输出？", "options": ["\"5 + 3\"", "8", "53", "报错"], "answer": 1, "explain": "花括号内表达式先算 5+3=8。"}, {"type": "code", "q": "x = 3.14159，用 f-string 保留两位小数输出", "code": "x = 3.14159\nprint(f\"{x:.2f}\")", "expect": "3.14", "hint": ":.2f 保留两位。"}, {"type": "code", "q": "（思考★）秒数 total = 90，输出格式 m 分 s 秒（90 秒 = 1 分 30 秒）", "code": "total = 90\nprint(f\"{total // 60}分{total % 60}秒\")", "expect": "1分30秒", "hint": "分钟 = total//60，秒 = total%60。"}, {"type": "choice", "q": "10 // 3 与 10 % 3 分别是？", "options": ["3 和 1", "3 和 0.333", "3.3 和 0.1", "1 和 3"], "answer": 0, "explain": "10=3*3+1，商 3 余 1。"}, {"type": "choice", "q": "f\"{3.5:.0f}\" 输出？", "options": ["3", "4", "3.5", "3.0"], "answer": 1, "explain": ".0f 保留 0 位小数并四舍五入到整数：3.5 → 4。"}, {"type": "code", "q": "f-string 输出 3 的平方是 9（用变量 x=3）", "code": "x = 3\nprint(f\"{x} 的平方是 {x ** 2}\")", "expect": "3 的平方是 9", "hint": "花括号内做运算。"}, {"type": "choice", "q": "7 % 2 == 1 用来判断什么？", "options": ["是否整除", "奇偶", "大小", "正负"], "answer": 1, "explain": "n%2 得 1 是奇数、0 是偶数，判奇偶的标准写法。"}, {"type": "code", "q": "把 0.1234 格式化成 12.3%（百分号一位小数）", "code": "print(f\"{0.1234:.1%}\")", "expect": "12.3%", "hint": ":.1% 自动乘 100 加 %。"}, {"type": "choice", "q": "(5 > 3) 的 print 结果是？", "options": ["True", "False", "1", "5"], "answer": 0, "explain": "比较运算返回布尔 True/False。"}], "exam": [{"type": "choice", "q": "17 % 5 的结果是？", "options": ["3", "2", "12", "3.4"], "answer": 1, "explain": "17 = 5*3 + 2，余 2。"}, {"type": "choice", "q": "f\"{name}!\" name=\"Hi\" 输出？", "options": ["Hi!", "{name}!", "Hi !", "报错"], "answer": 0, "explain": "花括号内 name 的值替换。"}, {"type": "code", "q": "输出 2 的 10 次方", "code": "print(2 ** 10)", "expect": "1024", "hint": "** 是幂运算。"}, {"type": "choice", "q": "下列哪个是浮点数？", "options": ["5", "\"5\"", "5.0", "5 + 0"], "answer": 2, "explain": "5.0 带小数点才是 float。"}, {"type": "code", "q": "a=5,b=2，输出 a 除以 b 的精确商（非整除）", "code": "a, b = 5, 2\nprint(a / b)", "expect": "2.5", "hint": "/ 是真除法。"}, {"type": "choice", "q": "f\"{12345:,}\" 输出？", "options": ["12345", "12,345", "12345,", "报错"], "answer": 1, "explain": ", 是千位分隔符。"}, {"type": "code", "q": "（思考★）一杯奶茶 12.5 元，买 3 杯打 9 折，用 f-string 输出总价（两位小数）", "code": "price = 12.5 * 3 * 0.9\nprint(f\"{price:.2f}\")", "expect": "33.75", "hint": "12.5*3=37.5，*0.9=33.75。"}, {"type": "choice", "q": "(2 + 3) * 4 ** 2 等于？", "options": ["80", "800", "44", "96"], "answer": 0, "explain": "先幂 4**2=16，再括号 5*16=80。"}, {"type": "code", "q": "a = 8, b = 3：输出 a 整除 b 的商和余数，格式 商X余Y", "code": "a, b = 8, 3\nprint(f\"商{a // b}余{a % b}\")", "expect": "商2余2", "hint": "8//3=2，8%3=2。"}, {"type": "choice", "q": "f\"{3 ** 2 + 1}\" 输出？", "options": ["10", "9 1", "91", "报错"], "answer": 0, "explain": "先算 3**2=9，+1=10。"}]}, {"id": 5, "no": "Ⅴ", "title": "列表基础", "weeks": "第 3 周", "diff": "★★☆", "full": true, "story": {"tutor": "范内瓦·布什（Vannevar Bush）", "era": "美国 · 信息组织先驱", "fact": "布什在 1945 年设想「记忆扩展机」Memex：把所有资料按关联组织起来，人能快速检索自己的知识。列表就是程序里最朴素的「资料柜」——按序存放、逐条处理。组织数据的方式，决定了你能多快找到它。", "quote": "「人类的经验，正在被压缩成可检索的形态。」—— Vannevar Bush"}, "map": ["列表是什么", "增删改查", "排序与长度", "遍历"], "sections": [{"t": "列表：有序的抽屉", "p": "列表用方括号，元素逗号分隔，可存任意类型混着存。索引从 0 开始：lst[0] 第一个，lst[-1] 最后一个。len() 数长度。", "code": "fruits = [\"苹果\", \"香蕉\", \"橙子\"]\nprint(fruits[0])\nprint(fruits[-1])\nprint(len(fruits))"}, {"t": "增删：append/insert/remove/pop", "p": "append 尾部加、insert(i,x) 插到 i、remove(x) 按值删第一个、pop() 尾部弹出并返回、del lst[i] 按下标删。改元素直接 lst[i]=新值。", "code": "t = [\"a\", \"b\"]\nt.append(\"c\")\nt.insert(1, \"x\")\nt.remove(\"a\")\nlast = t.pop()\nprint(t, last)"}, {"t": "排序与统计：sort/sorted/min/max/sum", "p": "lst.sort() 原地排序；sorted(lst) 返回新列表。min/max/sum 对数字列表很好用。reverse=True 倒序。字符串列表按字母排。", "code": "nums = [3, 1, 4, 1, 5]\nnums.sort()\nprint(nums)\nprint(max(nums), min(nums), sum(nums))"}, {"t": "遍历：for 的用法", "p": "for x in lst 逐个拿元素。配合 enumerate 能同时拿下标和值。遍历时别改列表长度（会漏项），要删先复制。", "code": "names = [\"Ada\", \"Grace\", \"Katherine\"]\nfor i, n in enumerate(names):\n    print(i, n)"}], "quiz": [{"type": "choice", "q": "lst = [10, 20, 30]，lst[-1] 是？", "options": ["10", "20", "30", "报错"], "answer": 2, "explain": "-1 是最后一个元素 30。"}, {"type": "choice", "q": "lst = [1,2,3]; lst.append(4) 后长度？", "options": ["3", "4", "5", "报错"], "answer": 1, "explain": "append 加一个元素，长度 3→4。"}, {"type": "code", "q": "建立列表 [5, 8, 2]，输出最大值与最小值（空格隔开）", "code": "lst = [5, 8, 2]\nprint(max(lst), min(lst))", "expect": "8 2", "hint": "max/min。"}, {"type": "choice", "q": "lst = [1,2,3]; lst.insert(0, 9) 后 lst[0]？", "options": ["1", "2", "9", "报错"], "answer": 2, "explain": "insert(0,9) 插到开头，9 成为第一个。"}, {"type": "code", "q": "lst = [3,1,2]，原地排序后打印", "code": "lst = [3, 1, 2]\nlst.sort()\nprint(lst)", "expect": "[1, 2, 3]", "hint": "sort() 原地排。"}, {"type": "choice", "q": "lst = [1,2,3,4]; lst.pop() 返回？", "options": ["4", "1", "3", "报错"], "answer": 0, "explain": "pop() 弹最后一个并返回 4。"}, {"type": "code", "q": "把 \"a\",\"b\",\"c\" 三个字符串放进列表并打印列表", "code": "lst = [\"a\", \"b\", \"c\"]\nprint(lst)", "expect": "['a', 'b', 'c']", "hint": "直接打印列表。"}, {"type": "choice", "q": "lst = [1,2,3]; print(sum(lst)) 输出？", "options": ["123", "6", "报错", "3"], "answer": 1, "explain": "sum 求和 1+2+3=6。"}, {"type": "code", "q": "（改错★）想删掉列表里第一个 \"x\"：lst = [\"x\",\"y\",\"x\"]，删除后打印", "code": "lst = [\"x\", \"y\", \"x\"]\nlst.remove(\"x\")\nprint(lst)", "expect": "['y', 'x']", "hint": "remove 只删第一个匹配。"}, {"type": "choice", "q": "lst = [2,4,6]; lst[1] = 10 后 lst 是？", "options": ["[2,10,6]", "[10,4,6]", "[2,4,10]", "报错"], "answer": 0, "explain": "下标 1 是第二个元素 4，改为 10。"}], "exam": [{"type": "choice", "q": "列表用什么符号？", "options": ["()", "[]", "{}", "<>"], "answer": 1, "explain": "列表是方括号。"}, {"type": "code", "q": "建立空列表，append 3 个数 7、8、9 后打印", "code": "lst = []\nlst.append(7)\nlst.append(8)\nlst.append(9)\nprint(lst)", "expect": "[7, 8, 9]", "hint": "逐个 append。"}, {"type": "choice", "q": "len([\"a\",\"b\",\"c\"]) 返回？", "options": ["2", "3", "4", "报错"], "answer": 1, "explain": "3 个元素长度 3。"}, {"type": "code", "q": "lst=[4,9,2]，输出 2 在不在列表（True/False）", "code": "lst = [4, 9, 2]\nprint(2 in lst)", "expect": "True", "hint": "in 判断成员。"}, {"type": "choice", "q": "lst=[1,2]; lst2=lst; lst2.append(3); lst 现在是？", "options": ["[1,2]", "[1,2,3]", "报错", "[2,1]"], "answer": 1, "explain": "lst2=lst 是同一个列表的别名，改 lst2 就是改 lst。"}, {"type": "code", "q": "lst=[10,20,30,40]，删除下标 2 的元素后打印", "code": "lst = [10, 20, 30, 40]\ndel lst[2]\nprint(lst)", "expect": "[10, 20, 40]", "hint": "del 按下标删。"}, {"type": "choice", "q": "lst=[1,3,2]; sorted(lst) 后 lst 是？", "options": ["[1,2,3]", "[1,3,2]", "报错", "[3,2,1]"], "answer": 1, "explain": "sorted 返回新列表，原列表不变。"}, {"type": "code", "q": "（思考★）有一组分数 [88,92,76,99]，输出 平均分（sum/len，保留整数）", "code": "scores = [88, 92, 76, 99]\nprint(sum(scores) // len(scores))", "expect": "88", "hint": "sum=355，//4=88。"}, {"type": "choice", "q": "lst=[]; for i in range(3): lst.append(i*i); lst 是？", "options": ["[0,1,2]", "[0,1,4]", "[1,4,9]", "[0,0,0]"], "answer": 1, "explain": "i=0,1,2 的平方 0,1,4。"}, {"type": "code", "q": "把列表 [\"b\",\"a\",\"c\"] 倒序（原地）后打印", "code": "lst = [\"b\", \"a\", \"c\"]\nlst.sort(reverse=True)\nprint(lst)", "expect": "['c', 'b', 'a']", "hint": "sort(reverse=True)。"}]}, {"id": 6, "no": "Ⅵ", "title": "列表进阶", "weeks": "第 3 周", "diff": "★★★", "full": true, "story": {"tutor": "芭芭拉·利斯科夫（Barbara Liskov）", "era": "美国 · 数据抽象", "fact": "利斯科夫是编程语言与数据抽象的奠基人之一。她教会行业一件事：数据怎么组织、操作怎么封装，决定代码能不能长大。切片、复制、推导式——这些列表进阶技巧，就是她那一代人为「处理成批数据」打磨的语法。", "quote": "「如果你想让系统可靠，就要让它的每个部分都简单。」—— Barbara Liskov"}, "map": ["切片", "复制陷阱", "列表推导式", "嵌套与拆分"], "sections": [{"t": "切片：截取一段", "p": "lst[a:b] 取下标 a 到 b-1（左闭右开）；[:3] 前三个、[2:] 从 2 到尾、[::2] 步长取、[::-1] 反转。切片返回新列表。", "code": "nums = list(range(10))\nprint(nums[2:5])\nprint(nums[:3])\nprint(nums[::2])\nprint(nums[::-1][:3])"}, {"t": "复制陷阱：浅拷贝 vs 深拷贝", "p": "b = a 只是别名；b = a[:] 或 list(a) 才是新列表。但列表里的列表（嵌套）切片只是浅拷贝，内层仍共享——改内层会传染。", "code": "a = [1, 2, 3]\nb = a[:]\nb.append(4)\nprint(a)   # [1,2,3] 不受影响\nc = [[1], [2]]\nd = c[:]\nd[0].append(9)\nprint(c)  # [[1,9],[2]] 内层被改了！"}, {"t": "列表推导式：一行造列表", "p": "[表达式 for x in 列表 if 条件] 把「循环+判断+收集」压成一行。nums 平方、只留偶数——推导式是 Python 招牌。", "code": "nums = [1, 2, 3, 4, 5]\nsq = [x * x for x in nums]\neven = [x for x in nums if x % 2 == 0]\nprint(sq, even)"}, {"t": "拆分与拼接：* 星号解包", "p": "first, *rest = lst 取首尾；* 能把列表摊开传参或合并：[*a, *b]。两列 zip 配对。", "code": "lst = [1, 2, 3, 4, 5]\nfirst, *rest = lst\nprint(first, rest)\nprint([0, *lst, 99])\npairs = list(zip([\"a\",\"b\"], [1,2]))\nprint(pairs)"}], "quiz": [{"type": "choice", "q": "nums=[0,1,2,3,4,5]; nums[1:4] 是？", "options": ["[0,1,2,3]", "[1,2,3]", "[1,2,3,4]", "[0,1,2]"], "answer": 1, "explain": "左闭右开：1,2,3。"}, {"type": "choice", "q": "b = a[:] 与 b = a 的区别？", "options": ["没区别", "前者新列表，后者别名", "前者报错", "后者报错"], "answer": 1, "explain": "切片复制出新列表，直接赋值是别名。"}, {"type": "code", "q": "nums=[1,2,3,4,5,6]，取所有偶数（步长）打印", "code": "nums = [1, 2, 3, 4, 5, 6]\nprint(nums[1::2])", "expect": "[2, 4, 6]", "hint": "从下标 1 开始步长 2。"}, {"type": "choice", "q": "[x*2 for x in range(4)] 结果是？", "options": ["[0,2,4,6]", "[2,4,6,8]", "[1,2,3,4]", "[0,1,2,3]"], "answer": 0, "explain": "0..3 各乘 2：0,2,4,6。"}, {"type": "code", "q": "用列表推导式生成 1 到 10 的平方列表并打印", "code": "print([x * x for x in range(1, 11)])", "expect": "[1, 4, 9, 16, 25, 36, 49, 64, 81, 100]", "hint": "range(1,11)。"}, {"type": "choice", "q": "lst=[1,2,3,4,5]; lst[::-1] 是？", "options": ["[1,2,3,4,5]", "[5,4,3,2,1]", "[1,3,5]", "报错"], "answer": 1, "explain": "负步长反转。"}, {"type": "code", "q": "first, *rest = [10,20,30,40]，打印 first 和 rest", "code": "first, *rest = [10, 20, 30, 40]\nprint(first)\nprint(rest)", "expect": "10\n[20, 30, 40]", "hint": "*rest 收剩余。"}, {"type": "choice", "q": "（思考★）a=[[1],[2]]; b=a[:]; b[0].append(9); a[0] 是？", "options": ["[1]", "[1,9]", "[9]", "报错"], "answer": 1, "explain": "切片浅拷贝，内层列表仍共享，a[0] 也被改成 [1,9]。"}, {"type": "code", "q": "用推导式：从 [1..10] 里挑出 3 的倍数打印", "code": "print([x for x in range(1, 11) if x % 3 == 0])", "expect": "[3, 6, 9]", "hint": "if 过滤。"}, {"type": "choice", "q": "list(zip([\"a\",\"b\"], [1,2])) 结果是？", "options": ["[(\"a\",1),(\"b\",2)]", "[[\"a\",\"b\"],[1,2]]", "[\"a1\",\"b2\"]", "报错"], "answer": 0, "explain": "zip 逐对打包成元组。"}], "exam": [{"type": "choice", "q": "nums[:5] 表示？", "options": ["前 5 个", "第 5 个起", "后 5 个", "5 到末尾"], "answer": 0, "explain": "[:5] 取前 5 个（下标 0-4）。"}, {"type": "code", "q": "s = \"python\"，用切片取后三个字母", "code": "s = \"python\"\nprint(s[-3:])", "expect": "hon", "hint": "负索引切片。"}, {"type": "choice", "q": "[x for x in range(10) if x % 2 == 1] 长度？", "options": ["4", "5", "6", "10"], "answer": 1, "explain": "1,3,5,7,9 五个奇数。"}, {"type": "code", "q": "把 [1,2] 和 [3,4] 合并成 [1,2,3,4]（用 * 解包）", "code": "a = [1, 2]\nb = [3, 4]\nprint([*a, *b])", "expect": "[1, 2, 3, 4]", "hint": "[*a, *b]。"}, {"type": "choice", "q": "lst=[1,2,3]; a,b,c=lst; b 是？", "options": ["1", "2", "3", "报错"], "answer": 1, "explain": "解包按顺序赋给 a,b,c。"}, {"type": "code", "q": "words=[\"a\",\"b\",\"c\"]，用 join 拼成 \"a-b-c\"", "code": "words = [\"a\", \"b\", \"c\"]\nprint(\"-\".join(words))", "expect": "a-b-c", "hint": "join 用分隔符连接。"}, {"type": "choice", "q": "（思考★）复制列表防止意外改原列表，最安全做法？", "options": ["b = a", "b = a.copy() 或 a[:]", "b = a.reverse()", "b = a.sort()"], "answer": 1, "explain": "copy()/切片创建独立副本；直接赋值是别名。"}, {"type": "code", "q": "用推导式生成 [10,20,...,50]（10 的倍数到 50）", "code": "print([x * 10 for x in range(1, 6)])", "expect": "[10, 20, 30, 40, 50]", "hint": "1..5 乘 10。"}, {"type": "choice", "q": "matrix=[[1,2],[3,4]]; matrix[0][1] 是？", "options": ["1", "2", "3", "4"], "answer": 1, "explain": "第 0 行第 1 列 = 2。"}, {"type": "code", "q": "把嵌套 [[1,2],[3,4]] 用双循环展平成一维并打印", "code": "m = [[1, 2], [3, 4]]\nflat = [x for row in m for x in row]\nprint(flat)", "expect": "[1, 2, 3, 4]", "hint": "嵌套推导式先 row 后 x。"}]}, {"id": 7, "no": "Ⅶ", "title": "if 与条件", "weeks": "第 4 周", "diff": "★★☆", "full": true, "story": {"tutor": "阿达·洛芙莱斯（Ada Lovelace）", "era": "英国 · 第一位程序员", "fact": "1843 年阿达给分析机写下的「程序」里，第一次描述了条件跳转：机器该在什么情况下走哪条路。她是「程序不只是算数，而是做决策」这个想法的第一人。if 就是现代程序每分钟做的决策。", "quote": "「机器的力量在于，它能按规则做出自己选择的动作。」—— Ada Lovelace"}, "map": ["if-else", "elif 链条", "比较与逻辑", "真值与陷阱"], "sections": [{"t": "if / else：程序会做选择了", "p": "if 条件为 True 执行缩进块；else 兜底。冒号和缩进是 Python 的语法，不是装饰。条件就是比较或布尔表达式。", "code": "score = 85\nif score >= 60:\n    print(\"及格\")\nelse:\n    print(\"不及格\")"}, {"t": "elif：多分支的排队", "p": "elif 从上往下查，命中一个就跳过剩下（短路）。顺序重要：先写窄条件、后写宽条件。", "code": "age = 15\nif age < 4:\n    price = 0\nelif age < 18:\n    price = 20\nelse:\n    price = 40\nprint(\"票价\", price)"}, {"t": "比较与逻辑：and/or/not", "p": "== != > < >= <=；and 全真才真、or 一真即真、not 取反。判断区间：18 <= age < 65 链式比较。", "code": "t = 25\nwarm = t > 20 and t < 30\ncold = not warm\nprint(warm, cold)"}, {"t": "真值：什么算 False", "p": "if x: 里 x 为 0、\"\"、[]、None 时都是 False，其他为 True。用 if not x: 判空很 Pythonic。别写 if x == True。", "code": "name = \"\"\nif not name:\n    print(\"名字是空的\")\nelse:\n    print(\"你好\", name)"}], "quiz": [{"type": "choice", "q": "x=5; if x>3: print(\"a\") else: print(\"b\") 输出？", "options": ["a", "b", "ab", "报错"], "answer": 0, "explain": "x>3 为真走 if。"}, {"type": "choice", "q": "elif 和多个独立 if 的区别？", "options": ["没区别", "elif 命中后跳过剩余，独立 if 都检查", "elif 更快", "elif 只能一次"], "answer": 1, "explain": "elif 链短路，独立 if 每个都判断。"}, {"type": "code", "q": "n = 7，偶数输出 偶数 否则输出 奇数", "code": "n = 7\nif n % 2 == 0:\n    print(\"偶数\")\nelse:\n    print(\"奇数\")", "expect": "奇数", "hint": "n%2==1 是奇数。"}, {"type": "choice", "q": "0 在布尔里是？", "options": ["True", "False", "报错", "None"], "answer": 1, "explain": "0 是 falsy。"}, {"type": "code", "q": "t = 25，若 20<t<30 输出 舒适，否则输出 不适", "code": "t = 25\nif 20 < t < 30:\n    print(\"舒适\")\nelse:\n    print(\"不适\")", "expect": "舒适", "hint": "链式比较。"}, {"type": "choice", "q": "not (3 > 2) 是？", "options": ["True", "False", "报错", "None"], "answer": 1, "explain": "3>2 为 True，not True=False。"}, {"type": "code", "q": "s = \"hi\"，若 s 为空输出 空，否则输出 s 内容", "code": "s = \"hi\"\nif not s:\n    print(\"空\")\nelse:\n    print(s)", "expect": "hi", "hint": "if not s 判空。"}, {"type": "choice", "q": "age=18; if age<4 先判断，再 elif age<18，再 else。age=18 走哪？", "options": ["if", "elif", "else", "都不走"], "answer": 2, "explain": "18 不小于 4 也不小于 18，落 else。"}, {"type": "code", "q": "（改错★）想判断 x 是否 5<x<10，写成 if x>5 or x<10 对吗？修正后对 x=7 输出 在区间", "code": "x = 7\nif 5 < x < 10:\n    print(\"在区间\")\nelse:\n    print(\"不在\")", "expect": "在区间", "hint": "or 会恒真，用链式比较。"}, {"type": "choice", "q": "if x: 与 if x == True: 的关系？", "options": ["等价", "if x: 看真值更通用", "后者更快", "后者报错"], "answer": 1, "explain": "if x: 接受任何真值（数字/容器），if x==True 只认 True。"}], "exam": [{"type": "choice", "q": "score=59; if score>=60 输出？", "options": ["及格", "不及格", "都不", "报错"], "answer": 1, "explain": "59<60 走 else。"}, {"type": "code", "q": "a=10,b=20 输出较大的数", "code": "a, b = 10, 20\nif a > b:\n    print(a)\nelse:\n    print(b)", "expect": "20", "hint": "比较输出。"}, {"type": "choice", "q": "x=3,y=3; x==y 是？", "options": ["True", "False", "报错", "3"], "answer": 0, "explain": "== 比较相等。"}, {"type": "code", "q": "grade = \"B\"，若是 A 输出 优秀，是 B 输出 良好，否则 加油", "code": "grade = \"B\"\nif grade == \"A\":\n    print(\"优秀\")\nelif grade == \"B\":\n    print(\"良好\")\nelse:\n    print(\"加油\")", "expect": "良好", "hint": "elif 链条。"}, {"type": "choice", "q": "[] 在 if 里的真值是？", "options": ["True", "False", "报错", "None"], "answer": 1, "explain": "空容器是 falsy。"}, {"type": "code", "q": "light = True；若为真输出 开灯，否则 关灯", "code": "light = True\nif light:\n    print(\"开灯\")\nelse:\n    print(\"关灯\")", "expect": "开灯", "hint": "布尔直接判断。"}, {"type": "choice", "q": "age=17; can = age >= 18; print(can) 输出？", "options": ["True", "False", "报错", "17"], "answer": 1, "explain": "17>=18 为 False。"}, {"type": "code", "q": "（思考★）判断闰年：能被 4 整除且不被 100 整除，或能被 400 整除。y=2024 输出", "code": "y = 2024\nif (y % 4 == 0 and y % 100 != 0) or y % 400 == 0:\n    print(\"闰年\")\nelse:\n    print(\"平年\")", "expect": "闰年", "hint": "复合条件。"}, {"type": "choice", "q": "“if not done:” 中 done=False 会？", "options": ["执行", "不执行", "报错", "None"], "answer": 0, "explain": "not False=True 执行。"}, {"type": "code", "q": "n=0；if n 输出 非零，else 输出 零", "code": "n = 0\nif n:\n    print(\"非零\")\nelse:\n    print(\"零\")", "expect": "零", "hint": "0 为假走 else。"}]}, {"id": 8, "no": "Ⅷ", "title": "字典与嵌套", "weeks": "第 4 周", "diff": "★★★", "full": true, "story": {"tutor": "林纳斯·托瓦兹（Linus Torvalds）", "era": "芬兰 · Linux 与 Git 作者", "fact": "托瓦兹说「坏程序员担心代码，好程序员担心数据结构和它们的关系」。字典就是「键→值」的映射——查名字出电话、查国家出首都。程序一半的优雅，来自选对了数据结构。", "quote": "「我真的是个优雅主义者：如果代码不够优雅，我就睡不着。」—— Linus Torvalds"}, "map": ["字典是什么", "增删改查", "遍历", "get 与嵌套"], "sections": [{"t": "字典：按键取值", "p": "dict = {键: 值}。用 d[\"key\"] 取值，d[\"new\"]=v 新增或改。键要不可变类型（字符串/数字），值随意。", "code": "user = {\"name\": \"Ada\", \"age\": 36}\nprint(user[\"name\"])\nuser[\"city\"] = \"London\"\nuser[\"age\"] = 37\nprint(user)"}, {"t": "增删：del 与 in", "p": "del d[\"k\"] 删键；\"k\" in d 判断键在不在。删不存在的键会 KeyError，先 in 判断或 pop。", "code": "d = {\"a\": 1, \"b\": 2}\ndel d[\"a\"]\nprint(d)\nprint(\"b\" in d, \"a\" in d)"}, {"t": "遍历：items/keys/values", "p": "d.items() 给 (键,值) 对、d.keys()、d.values()。for k, v in d.items() 是遍历标配。", "code": "d = {\"math\": 90, \"py\": 95}\nfor k, v in d.items():\n    print(k, v)\nprint(list(d.values()))"}, {"t": "get 与嵌套：安全取值", "p": "d.get(\"k\", 默认) 找不到给默认不报错。值可以是字典（嵌套），取深层 d[\"a\"][\"b\"] 前先确认外层在。", "code": "d = {\"math\": 90}\nprint(d.get(\"eng\", 0))\nusers = {\"ada\": {\"age\": 36, \"city\": \"London\"}}\nprint(users[\"ada\"][\"city\"])"}], "quiz": [{"type": "choice", "q": "d={\"a\":1,\"b\":2}; d[\"a\"] 是？", "options": ["1", "2", "\"a\"", "报错"], "answer": 0, "explain": "按键取 1。"}, {"type": "choice", "q": "d[\"c\"] 当键不存在会？", "options": ["返回 None", "报 KeyError", "自动创建", "返回 0"], "answer": 1, "explain": "直接访问不存在键抛 KeyError。"}, {"type": "code", "q": "建字典 score={\"math\":90}，把 math 改成 95 并打印 score", "code": "score = {\"math\": 90}\nscore[\"math\"] = 95\nprint(score)", "expect": "{'math': 95}", "hint": "赋值覆盖。"}, {"type": "choice", "q": "d.items() 遍历给什么？", "options": ["只有键", "只有值", "(键,值) 对", "索引"], "answer": 2, "explain": "items 给键值对。"}, {"type": "code", "q": "d = {\"x\": 1}，安全取 \"y\"，没有给默认 99 并打印", "code": "d = {\"x\": 1}\nprint(d.get(\"y\", 99))", "expect": "99", "hint": "get 带默认。"}, {"type": "choice", "q": "\"math\" in {\"math\":90,\"py\":95} 是？", "options": ["True", "False", "报错", "看值"], "answer": 0, "explain": "in 判断键是否存在。"}, {"type": "code", "q": "遍历 d={\"a\":10,\"b\":20} 逐行输出 键=值", "code": "d = {\"a\": 10, \"b\": 20}\nfor k, v in d.items():\n    print(f\"{k}={v}\")", "expect": "a=10\nb=20", "hint": "f-string 内嵌。"}, {"type": "choice", "q": "del d[\"k\"] 对不存在键会？", "options": ["静默", "KeyError", "创建", "返回 None"], "answer": 1, "explain": "删不存在键抛 KeyError。"}, {"type": "code", "q": "（思考★）字典嵌套取国家首都：world={\"中国\":{\"首都\":\"北京\"}}，输出 北京", "code": "world = {\"中国\": {\"首都\": \"北京\"}}\nprint(world[\"中国\"][\"首都\"])", "expect": "北京", "hint": "逐层取。"}, {"type": "choice", "q": "下面哪个不能当字典键？", "options": ["\"name\"", "123", "(1,2)", "[1,2]"], "answer": 3, "explain": "列表可变不可哈希，不能当键。"}], "exam": [{"type": "choice", "q": "d={}; d[\"a\"]=1; d 现在是？", "options": ["{\"a\":1}", "{\"a\"}", "报错", "[]"], "answer": 0, "explain": "给不存在键赋值即新增。"}, {"type": "code", "q": "建字典 person={\"name\":\"Ada\",\"age\":36}，打印 name", "code": "person = {\"name\": \"Ada\", \"age\": 36}\nprint(person[\"name\"])", "expect": "Ada", "hint": "按键取。"}, {"type": "choice", "q": "len({\"a\":1,\"b\":2,\"c\":3}) 是？", "options": ["3", "6", "报错", "1"], "answer": 0, "explain": "len 数键的个数。"}, {"type": "code", "q": "d={\"x\":1,\"y\":2}；用 pop 删 \"x\" 并打印删除的值和剩余 d", "code": "d = {\"x\": 1, \"y\": 2}\nv = d.pop(\"x\")\nprint(v)\nprint(d)", "expect": "1\n{'y': 2}", "hint": "pop 返回被删值。"}, {"type": "choice", "q": "for k in d: 遍历的是？", "options": ["键", "值", "键值对", "索引"], "answer": 0, "explain": "默认遍历键。"}, {"type": "code", "q": "把列表 [\"a\",\"b\"] 的每项计出现次数用字典：{\"a\":1,\"b\":1} 手写并打印", "code": "cnt = {}\nfor ch in [\"a\", \"b\"]:\n    cnt[ch] = cnt.get(ch, 0) + 1\nprint(cnt)", "expect": "{'a': 1, 'b': 1}", "hint": "get 计数模式。"}, {"type": "choice", "q": "d.get(\"z\") 无 \"z\" 返回？", "options": ["报错", "None", "0", "\"\""], "answer": 1, "explain": "get 无默认返回 None。"}, {"type": "code", "q": "d={\"tall\":180}；在 \"tall\" 存在且 >170 时输出 高个", "code": "d = {\"tall\": 180}\nif \"tall\" in d and d[\"tall\"] > 170:\n    print(\"高个\")", "expect": "高个", "hint": "先 in 再取。"}, {"type": "choice", "q": "dict(a=1,b=2) 创建的是？", "options": ["{\"a\":1,\"b\":2}", "{\"a,b\":1}", "报错", "[1,2]"], "answer": 0, "explain": "dict() 关键字建字典。"}, {"type": "code", "q": "（思考★）三科成绩 {\"m\":90,\"e\":85,\"p\":95} 求平均并输出整数", "code": "s = {\"m\": 90, \"e\": 85, \"p\": 95}\nprint(sum(s.values()) // len(s))", "expect": "90", "hint": "values 求和平均。"}]}, {"id": 9, "no": "Ⅸ", "title": "while 与输入", "weeks": "第 5 周", "diff": "★★★", "full": true, "story": {"tutor": "丹尼斯·里奇（Dennis Ritchie）", "era": "美国 · C 语言之父", "fact": "里奇和汤普森写 Unix 时，把「循环等待输入」变成操作系统的日常：一遍遍问用户想要什么，处理完再问。while 是这种「服务循环」的骨架——程序不是跑一次就死，而是活着等你下一个指令。", "quote": "「Unix 很朴素：每个程序做好一件事。」—— Dennis Ritchie"}, "map": ["while 循环", "input 输入", "累加器", "菜单循环"], "sections": [{"t": "while：条件为真就循环", "p": "while 条件: 循环体。每轮先查条件。必须让条件最终变 False（改循环变量），否则死循环。", "code": "n = 1\nwhile n <= 3:\n    print(n)\n    n += 1"}, {"t": "input：等用户说话", "p": "input(\"提示\") 显示提示并等回车，返回<strong>字符串</strong>。要数字先 int()。输入空白也回车会得到 \"\"。", "code": "name = input(\"你的名字？\")\nprint(\"你好\", name)"}, {"t": "累加器：边循环边攒", "p": "total 存和、count 计数：每轮 total += x、count += 1。循环结束算平均 total/count。", "code": "nums = [5, 8, 3]\ntotal = 0\nfor x in nums:\n    total += x\nprint(total)"}, {"t": "菜单循环：服务模式", "p": "while True 里给选项 → 处理 → 用户说退出就 break。这是 CLI 工具的标准骨架。", "code": "while True:\n    cmd = input(\"输入 quit 退出：\").strip()\n    if cmd == \"quit\":\n        print(\"再见\")\n        break"}], "quiz": [{"type": "choice", "q": "n=1; while n<4: print(n); n+=1 打印几次？", "options": ["3", "4", "2", "无限"], "answer": 0, "explain": "n=1,2,3 三次。"}, {"type": "choice", "q": "while 循环忘记让条件变化会？", "options": ["报错", "死循环", "跳过", "运行一次"], "answer": 1, "explain": "条件恒真则死循环。"}, {"type": "code", "q": "用 while 打印 1 到 5（每行一个）", "code": "n = 1\nwhile n <= 5:\n    print(n)\n    n += 1", "expect": "1\n2\n3\n4\n5", "hint": "n+=1 是刹车。"}, {"type": "choice", "q": "input() 返回的类型是？", "options": ["int", "str", "float", "list"], "answer": 1, "explain": "input 恒返回字符串。"}, {"type": "code", "q": "累加器：nums=[2,4,6] 求和并打印", "code": "nums = [2, 4, 6]\ntotal = 0\nfor x in nums:\n    total += x\nprint(total)", "expect": "12", "hint": "for 累加。"}, {"type": "choice", "q": "while True: 里放什么能退出？", "options": ["continue", "break", "pass", "return 无"], "answer": 1, "explain": "break 跳出循环。"}, {"type": "code", "q": "（模拟输入判题）把模拟用户输入当列表处理：inp=[\"5\",\"quit\"]，逐项读，遇到 quit 停止并输出 停止", "code": "inp = [\"5\", \"quit\"]\nfor cmd in inp:\n    if cmd == \"quit\":\n        print(\"停止\")\n        break", "expect": "停止", "hint": "模拟菜单循环（真实 input 版见讲义）。"}, {"type": "choice", "q": "int(input(\"年龄：\")) 输入 18 返回？", "options": ["\"18\"", "18", "报错", "18.0"], "answer": 1, "explain": "int() 转换后是整数。"}, {"type": "code", "q": "n=10；while n>0 时每次减 2，循环里 print(n)，输出序列", "code": "n = 10\nwhile n > 0:\n    print(n)\n    n -= 2", "expect": "10\n8\n6\n4\n2", "hint": "10,8,...,2。"}, {"type": "choice", "q": "死循环里想立即跳出的写法？", "options": ["if x: continue", "break 在某条件", "pass", "exit"], "answer": 1, "explain": "条件满足时 break 跳出。"}], "exam": [{"type": "choice", "q": "for 与 while 场景：不确定循环几次（等用户退出）用？", "options": ["for", "while", "都行但 while 更合适", "都行但 for 更合适"], "answer": 2, "explain": "次数未知用 while。"}, {"type": "code", "q": "用 while 求 1+2+...+10 并打印", "code": "n = 1\ntotal = 0\nwhile n <= 10:\n    total += n\n    n += 1\nprint(total)", "expect": "55", "hint": "累加 55。"}, {"type": "choice", "q": "x=3; while x: print(x); x-=1 打印？", "options": ["3 2 1", "3 2 1 0", "无限", "3 2 1 0 -1"], "answer": 0, "explain": "x=3,2,1 后 x=0 为假停。"}, {"type": "code", "q": "nums=[4,4,4]；用 while（下标）求和输出", "code": "nums = [4, 4, 4]\ni = 0\ntotal = 0\nwhile i < len(nums):\n    total += nums[i]\n    i += 1\nprint(total)", "expect": "12", "hint": "下标 while。"}, {"type": "choice", "q": "用户输入带空格的 \" 5 \"，int(\" 5 \") 会？", "options": ["报错", "5", "\" 5 \"", "0"], "answer": 1, "explain": "int() 容忍首尾空白。"}, {"type": "code", "q": "（模拟猜数字）target=7，把模拟输入列表 [\"3\",\"9\",\"7\"] 逐个比较，小了/大了/中了（中了就停）", "code": "target = 7\ninp = [\"3\", \"9\", \"7\"]\nfor v in inp:\n    n = int(v)\n    if n < target:\n        print(\"小了\")\n    elif n > target:\n        print(\"大了\")\n    else:\n        print(\"中了\")\n        break", "expect": "小了\n大了\n中了", "hint": "模拟 input 流的菜单循环。"}, {"type": "choice", "q": "total=0; for i in range(1,5): total+=i; 最后 total？", "options": ["10", "15", "9", "报错"], "answer": 0, "explain": "1+2+3+4=10。"}, {"type": "code", "q": "用 while 从 5 倒数打印到 1（每行一个）", "code": "n = 5\nwhile n >= 1:\n    print(n)\n    n -= 1", "expect": "5\n4\n3\n2\n1", "hint": "n>=1 递减。"}, {"type": "choice", "q": "输入 \"25\"，int(input())/5 的结果？", "options": ["5.0", "5", "25", "报错"], "answer": 0, "explain": "25/5=5.0（真除法返回浮点）。"}, {"type": "code", "q": "（模拟）命令流 [\"skip\",\"quit\"]：skip 打印 跳过，quit 打印 再见并停", "code": "inp = [\"skip\", \"quit\"]\nfor cmd in inp:\n    if cmd == \"skip\":\n        print(\"跳过\")\n        continue\n    if cmd == \"quit\":\n        print(\"再见\")\n        break", "expect": "跳过\n再见", "hint": "continue 跳本轮，break 出循环。"}]}, {"id": 10, "no": "Ⅹ", "title": "循环控制", "weeks": "第 5 周", "diff": "★★★", "full": true, "story": {"tutor": "约翰·麦卡锡（John McCarthy）", "era": "美国 · 人工智能之父", "fact": "麦卡锡 1958 年就提出「通过程序操作程序的程序」。控制流是程序的骨架：break 及时止损、continue 跳过噪音、嵌套循环处理二维数据。会控制循环的程序员，写的代码像指挥家。", "quote": "「程序会按照你写的方式运行，而不是你想的方式。」"}, "map": ["break 与 continue", "range 步长", "嵌套循环", "else 与陷阱"], "sections": [{"t": "break：及时止损", "p": "break 立刻跳出当前循环。找第一个满足的、读到退出指令——break 是「够了就停」。", "code": "nums = [3, 8, 1, 9]\nfor x in nums:\n    if x > 5:\n        print(\"找到\", x)\n        break"}, {"t": "continue：跳过这一轮", "p": "continue 结束本轮直接进下一轮。打印非 3 的倍数、跳过空行——continue 是「这个不算，下一个」。", "code": "for i in range(1, 7):\n    if i % 3 == 0:\n        continue\n    print(i)   # 1 2 4 5"}, {"t": "range 步长：精确控制", "p": "range(a, b, s) 从 a 到 b-1 每步 s。range(5) 0..4；range(2,10,2) 2,4,6,8；倒着 range(5,0,-1)。", "code": "print(list(range(1, 10, 2)))\nprint(list(range(5, 0, -1)))"}, {"t": "嵌套循环：二维处理", "p": "外循环行、内循环列。乘法表就是经典：每行内层打整行，外层换行。", "code": "for i in range(1, 4):\n    for j in range(1, 4):\n        print(i * j, end=\" \")\n    print()"}], "quiz": [{"type": "choice", "q": "for x in range(10): if x==3: break; print(x) 打印到几？", "options": ["3", "0 1 2", "0 1 2 3", "4"], "answer": 1, "explain": "x=3 时 break，只打印 0 1 2。"}, {"type": "choice", "q": "continue 的作用？", "options": ["退出循环", "跳到下一轮", "报错", "什么都不做"], "answer": 1, "explain": "跳过本轮剩余进下一轮。"}, {"type": "code", "q": "打印 1 到 10 中不是 5 的倍数的数（一行一个）", "code": "for i in range(1, 11):\n    if i % 5 == 0:\n        continue\n    print(i)", "expect": "1\n2\n3\n4\n6\n7\n8\n9", "hint": "跳过 5、10。"}, {"type": "choice", "q": "list(range(1, 8, 2)) 是？", "options": ["[1,2,3,4,5,6,7]", "[1,3,5,7]", "[2,4,6,8]", "[1,3,5]"], "answer": 1, "explain": "步长 2：1,3,5,7。"}, {"type": "code", "q": "用嵌套循环打印 2 行 3 列，每格打 #，换行分割", "code": "for r in range(2):\n    line = \"\"\n    for c in range(3):\n        line += \"#\"\n    print(line)", "expect": "###\n###", "hint": "行内拼接。"}, {"type": "choice", "q": "在 while True 菜单里退出用什么？", "options": ["continue", "break", "pass", "exit()"], "answer": 1, "explain": "break 跳出循环结束菜单。"}, {"type": "code", "q": "找第一个能被 7 整除的数（从 8 开始试）并打印", "code": "x = 8\nwhile True:\n    if x % 7 == 0:\n        print(x)\n        break\n    x += 1", "expect": "14", "hint": "8..13 不行，14 是。"}, {"type": "choice", "q": "list(range(5, 0, -1)) 是？", "options": ["[1,2,3,4,5]", "[5,4,3,2,1]", "[]", "报错"], "answer": 1, "explain": "负步长倒着来。"}, {"type": "code", "q": "（思考★）nums=[1,2,3] 找 2：找到输出 在位置1 并用 break；没找到输出 没有", "code": "nums = [1, 2, 3]\nfound = False\nfor i, v in enumerate(nums):\n    if v == 2:\n        print(f\"在位置{i}\")\n        found = True\n        break\nif not found:\n    print(\"没有\")", "expect": "在位置1", "hint": "enumerate 带下标。"}, {"type": "choice", "q": "for-else 的 else 何时执行？", "options": ["循环正常结束（无 break）", "循环任何结束", "break 后", "从不"], "answer": 0, "explain": "for/while 的 else 在没被 break 打断时执行。"}], "exam": [{"type": "choice", "q": "range(4) 生成？", "options": ["[1,2,3,4]", "[0,1,2,3]", "[4]", "报错"], "answer": 1, "explain": "range(n) 0..n-1。"}, {"type": "code", "q": "打印 10 以内奇数（1,3,5,7,9）用 range 步长", "code": "for i in range(1, 10, 2):\n    print(i)", "expect": "1\n3\n5\n7\n9", "hint": "range(1,10,2)。"}, {"type": "choice", "q": "循环里 pass 的作用？", "options": ["跳出", "占位不做", "跳到下轮", "报错"], "answer": 1, "explain": "pass 空语句占位，常配 TODO。"}, {"type": "code", "q": "打印九九乘法表第 3 行（3x1..3x3，格式 3x1=3 空格隔开）", "code": "for j in range(1, 4):\n    print(f\"3x{j}={3*j}\", end=\" \")\nprint()", "expect": "3x1=3 3x2=6 3x3=9 ", "hint": "end=\" \" 不换行。"}, {"type": "choice", "q": "for i in range(3): for j in range(2): … 内层共执行几次？", "options": ["5", "6", "9", "2"], "answer": 1, "explain": "3×2=6 次。"}, {"type": "code", "q": "从 100 向下找第一个能被 9 整除的数", "code": "x = 100\nwhile x >= 0:\n    if x % 9 == 0:\n        print(x)\n        break\n    x -= 1", "expect": "99", "hint": "99 是最大被 9 整除的。"}, {"type": "choice", "q": "输出 0..10 偶数时用 continue 跳过奇数，等价于？", "options": ["range(0,11,2)", "range(1,11,2)", "range(11)", "for 里 if 不跳"], "answer": 0, "explain": "continue 版与 range 步长版等价。"}, {"type": "code", "q": "（思考★）打印 1..6 但每个数后面接它的平方，如 1:1，每行一个", "code": "for i in range(1, 7):\n    print(f\"{i}:{i*i}\")", "expect": "1:1\n2:4\n3:9\n4:16\n5:25\n6:36", "hint": "f-string。"}, {"type": "choice", "q": "nums=[1,3,7]; for x in nums: if x==5: break else 会执行吗？", "options": ["会", "不会", "报错", "不一定"], "answer": 0, "explain": "没遇到 break（5 不存在），else 执行。"}, {"type": "code", "q": "嵌套循环输出 3 行递减：第 i 行打 (3-i) 个 * ", "code": "for i in range(3):\n    print(\"*\" * (3 - i))", "expect": "***\n**\n*", "hint": "字符串乘次数。"}]}, {"id": 11, "no": "Ⅺ", "title": "函数定义", "weeks": "第 6 周", "diff": "★★☆", "full": true, "story": {"tutor": "格蕾丝·赫柏（Grace Hopper）", "era": "美国 · 编译器之母", "fact": "赫柏说「请求原谅比请求许可更容易」，但她更著名的遗产是把「子程序」变成工程：一段逻辑写一次，处处调用。函数就是程序里的「子程序」——把重复劳动收进一个名字里。", "quote": "「人类对变化的恐惧，是进步的最大敌人。」"}, "map": ["def 与调用", "参数与实参", "return 返回", "函数是黑盒"], "sections": [{"t": "def：把逻辑装进名字", "p": "def 定义函数，调用时执行函数体。函数先定义后调用。函数是「收件箱」：你给它输入，它处理完给你结果。", "code": "def greet():\n    print(\"你好\")\ndef main():\n    greet()\nmain()"}, {"t": "参数：函数的输入口", "p": "定义时写形参，调用时传实参。位置参数按顺序对应。参数让同一个函数处理不同数据，函数从「固定剧本」变成「可点菜」。", "code": "def greet(name):\n    print(\"你好，\" + name)\ngreet(\"鼠哥\")\ngreet(\"同学\")"}, {"t": "return：把结果交出来", "p": "return 结束函数并返回值。没有 return 的函数返回 None。计算逻辑放函数里 return，主流程拿结果继续。", "code": "def square(x):\n    return x * x\ny = square(5)\nprint(y)"}, {"t": "函数是黑盒", "p": "调用者只需知道「输入什么、得到什么」，不必关心内部。好函数短小、单一职责、名字说明意图。", "code": "def area(w, h):\n    return w * h\nprint(area(3, 4))"}], "quiz": [{"type": "choice", "q": "def 定义函数后，调用它的方式是？", "options": ["greet", "greet()", "def greet()", "call greet"], "answer": 1, "explain": "函数名加圆括号调用，传参写在括号里。"}, {"type": "choice", "q": "def greet(name) 里的 name 叫？", "options": ["实参", "形参", "返回值", "局部变量"], "answer": 1, "explain": "定义时写的是形参（占位），调用时传的是实参（实际值）。"}, {"type": "code", "q": "定义函数 double(x) 返回 x 的两倍，调用 double(21) 并打印结果", "code": "def double(x):\n    return x * 2\nprint(double(21))", "expect": "42", "hint": "return x*2"}, {"type": "choice", "q": "def f(): print(\"a\") 调用 f() 后返回值是？", "options": ["\"a\"", "None", "0", "报错"], "answer": 1, "explain": "没有 return 的函数返回 None。"}, {"type": "code", "q": "定义函数 add(a, b) 返回两数之和，打印 add(3, 4) 的结果", "code": "def add(a, b):\n    return a + b\nprint(add(3, 4))", "expect": "7", "hint": "return a+b"}, {"type": "choice", "q": "return 语句的作用是？", "options": ["打印结果", "结束函数并返回一个值", "跳过函数", "循环一次"], "answer": 1, "explain": "return 结束函数并把值交还给调用处。"}, {"type": "code", "q": "定义函数 is_even(n) 返回 n 是否为偶数（布尔），打印 is_even(8)", "code": "def is_even(n):\n    return n % 2 == 0\nprint(is_even(8))", "expect": "True", "hint": "n%2==0"}, {"type": "choice", "q": "函数体缩进错了会导致？", "options": ["没影响", "IndentationError", "函数更快", "自动修复"], "answer": 1, "explain": "Python 靠缩进分块，缩进错直接语法错误。"}, {"type": "code", "q": "定义函数 max2(a, b) 返回较大者，打印 max2(5, 9)", "code": "def max2(a, b):\n    if a > b:\n        return a\n    return b\nprint(max2(5, 9))", "expect": "9", "hint": "比较后 return 大的"}, {"type": "choice", "q": "把重复代码收进函数的好处不包括？", "options": ["改一处处处生效", "代码更短", "运行更快（必然）", "逻辑命名后更好读"], "answer": 2, "explain": "函数让代码可维护，但不保证运行更快——它可能更慢一点。"}], "exam": [{"type": "choice", "q": "def f(x): return x+1，f(5) 结果是？", "options": ["5", "6", "x+1", "报错"], "answer": 1, "explain": "实参 5 代入形参 x，返回 6。"}, {"type": "code", "q": "定义函数 triple(x) 返回 x 的三倍，打印 triple(7)", "code": "def triple(x):\n    return x * 3\nprint(triple(7))", "expect": "21", "hint": "return x*3"}, {"type": "choice", "q": "函数定义和调用的顺序要求？", "options": ["先调用后定义也行（同文件）", "必须先定义后调用", "顺序无所谓", "必须在别的文件"], "answer": 1, "explain": "调用发生在定义之前会 NameError。"}, {"type": "code", "q": "定义函数 shout(s) 返回 s 加三个感叹号，打印 shout(\"好\")", "code": "def shout(s):\n    return s + \"!!!\"\nprint(shout(\"好\"))", "expect": "好!!!", "hint": "字符串拼接"}, {"type": "choice", "q": "print() 和 return 的区别是？", "options": ["没区别", "print 显示到屏幕，return 把值交给调用处", "return 显示到屏幕", "print 只能用于函数外"], "answer": 1, "explain": "print 是输出副作用，return 是函数产出值。"}, {"type": "code", "q": "定义函数 abs2(x) 返回 x 的绝对值，打印 abs2(-3)", "code": "def abs2(x):\n    if x < 0:\n        return -x\n    return x\nprint(abs2(-3))", "expect": "3", "hint": "负数取反"}, {"type": "choice", "q": "函数名用什么风格命名最好？", "options": ["MyFunc", "my_func（小写下划线）", "myfunc1", "随便起"], "answer": 1, "explain": "Python 惯例：函数名小写，单词下划线分隔。"}, {"type": "code", "q": "定义函数 hello(name) 返回 \"你好，name！\"，打印 hello(\"小美\")", "code": "def hello(name):\n    return \"你好，\" + name + \"！\"\nprint(hello(\"小美\"))", "expect": "你好，小美！", "hint": "拼接字符串"}, {"type": "choice", "q": "一个函数里可以有多个 return 吗？", "options": ["只能一个", "可以，执行到哪个算哪个", "多个会报错", "return 只能在最后"], "answer": 1, "explain": "可多个 return，执行到第一个就返回（如 if/else 分支各一个）。"}, {"type": "code", "q": "定义函数 mul(a,b,c) 返回三数之积，打印 mul(2,3,4)", "code": "def mul(a, b, c):\n    return a * b * c\nprint(mul(2, 3, 4))", "expect": "24", "hint": "连乘"}]}, {"id": 12, "no": "Ⅻ", "title": "参数进阶", "weeks": "第 6 周", "diff": "★★☆", "full": true, "story": {"tutor": "芭芭拉·利斯科夫（Barbara Liskov）", "era": "美国 · 编程抽象先驱", "fact": "利斯科夫 1974 年提出「里氏替换」思想：设计接口时想清楚每种输入，让调用方放心。默认参数、关键字参数、*args 都是「接口设计」——让函数对不同用法都从容。", "quote": "「程序不是写给自己看的，是写给维护它的人看的。」"}, "map": ["默认参数", "关键字参数", "任意参数 *args", "参数顺序"], "sections": [{"t": "默认参数：给参数兜底", "p": "定义时给形参默认值，调用可不传该参数。默认参数要放后面。默认值是「出厂的预设」，调用方能覆盖。", "code": "def greet(name, msg=\"你好\"):\n    print(msg + \"，\" + name)\ngreet(\"鼠哥\")\ngreet(\"鼠哥\", \"加油\")"}, {"t": "关键字参数：点名传参", "p": "调用时用 形参=值 传参，顺序可乱，意图更清楚。", "code": "def info(name, age, city):\n    print(name, age, city)\ninfo(city=\"西安\", name=\"鼠哥\", age=18)"}, {"t": "*args：收不定个数", "p": "*args 把多余位置参数收进元组。写「不知道会传几个」的函数时用。", "code": "def total(*nums):\n    s = 0\n    for n in nums:\n        s += n\n    return s\nprint(total(1, 2, 3, 4))"}, {"t": "参数排列规则", "p": "顺序：必选参数 → 默认参数 → *args。规则是为了让 Python 知道谁是谁。", "code": "def f(a, b=2, *rest):\n    print(a, b, rest)\nf(1, 5, 7, 8)"}], "quiz": [{"type": "choice", "q": "def f(a, b=10): 调用 f(5) 时 b 的值是？", "options": ["报错", "10", "0", "None"], "answer": 1, "explain": "b 有默认值，不传就用 10。"}, {"type": "code", "q": "定义函数 power(base, exp=2) 返回 base 的 exp 次方，分别打印 power(3) 和 power(2, 3)", "code": "def power(base, exp=2):\n    return base ** exp\nprint(power(3))\nprint(power(2, 3))", "expect": "9\n8", "hint": "默认 exp=2"}, {"type": "choice", "q": "关键字参数调用 info(age=18, name=\"鼠哥\") 的要求？", "options": ["必须按定义顺序", "参数名要对应形参", "不能用关键字", "只能有一个"], "answer": 1, "explain": "关键字参数用形参名传值，顺序无关。"}, {"type": "code", "q": "定义函数 describe(name, age, city=\"西安\") 返回一行简介，打印 describe(\"鼠哥\", 18)", "code": "def describe(name, age, city=\"西安\"):\n    return name + \"，\" + str(age) + \"岁，来自\" + city\nprint(describe(\"鼠哥\", 18))", "expect": "鼠哥，18岁，来自西安", "hint": "默认 city"}, {"type": "choice", "q": "def f(a, b=1, c=2): f(1, c=9) 中 a、b、c 分别是？", "options": ["1,1,9", "1,9,2", "1,1,2", "报错"], "answer": 0, "explain": "位置参数给 a=1，默认 b=1，关键字 c=9。"}, {"type": "code", "q": "定义函数 avg(*nums) 返回平均数，打印 avg(2, 4, 6)", "code": "def avg(*nums):\n    return sum(nums) / len(nums)\nprint(avg(2, 4, 6))", "expect": "4.0", "hint": "sum/len"}, {"type": "choice", "q": "默认参数的正确写法？", "options": ["def f(a=1, b)", "def f(b, a=1)", "def f(*a, b)", "def f(a, b=1, c=2)"], "answer": 3, "explain": "默认参数在必选参数之后。a=1 在 b 前面会语法错。"}, {"type": "code", "q": "定义函数 concat(*words) 用逗号连接所有词返回，打印 concat(\"a\",\"b\",\"c\")", "code": "def concat(*words):\n    return \",\".join(words)\nprint(concat(\"a\", \"b\", \"c\"))", "expect": "a,b,c", "hint": "\",\".join"}, {"type": "choice", "q": "调用 f(*[1,2,3]) 的含义？", "options": ["报错", "把列表解包成 3 个位置参数", "传入一个列表", "取列表长度"], "answer": 1, "explain": "星号解包：列表元素逐个作为位置参数。"}, {"type": "code", "q": "定义函数 price(price, tax=0.08) 返回含税价（保留两位小数输出），打印 price(100)", "code": "def price(p, tax=0.08):\n    return round(p * (1 + tax), 2)\nprint(price(100))", "expect": "108.0", "hint": "round 两位"}], "exam": [{"type": "choice", "q": "def f(x=1): return x*2，f() 结果是？", "options": ["报错", "2", "1", "None"], "answer": 1, "explain": "x 用默认值 1，1*2=2。"}, {"type": "code", "q": "定义函数 repeat(s, n=2) 返回 s 重复 n 次，打印 repeat(\"ha\")", "code": "def repeat(s, n=2):\n    return s * n\nprint(repeat(\"ha\"))", "expect": "haha", "hint": "s*n"}, {"type": "choice", "q": "关键字参数的好处是？", "options": ["更快", "调用处清楚每个值给谁", "必须乱序", "省内存"], "answer": 1, "explain": "f(name=\"a\", age=1) 一眼看懂意图。"}, {"type": "code", "q": "定义函数 greet(first, last, sign=\"!\") 返回 名字+sign，打印 greet(\"Li\", \"Ming\")", "code": "def greet(first, last, sign=\"!\"):\n    return first + \" \" + last + sign\nprint(greet(\"Li\", \"Ming\"))", "expect": "Li Ming!", "hint": "默认 sign"}, {"type": "choice", "q": "*args 收集到的是？", "options": ["列表", "元组", "字典", "集合"], "answer": 1, "explain": "多余位置参数收成元组。"}, {"type": "code", "q": "定义函数 area2(w, h=2) 返回 w*h，打印 area2(5)", "code": "def area2(w, h=2):\n    return w * h\nprint(area2(5))", "expect": "10", "hint": "默认高 2"}, {"type": "choice", "q": "def f(a, b=2, c=3): f(1, 2, 3) 用的是什么传参？", "options": ["关键字", "位置", "默认", "混合报错"], "answer": 1, "explain": "全按位置传，a=1,b=2,c=3。"}, {"type": "code", "q": "定义函数 first_last(*items) 返回第一个和最后一个组成的元组，打印 first_last(3,7,9)", "code": "def first_last(*items):\n    return (items[0], items[-1])\nprint(first_last(3, 7, 9))", "expect": "(3, 9)", "hint": "索引 0 和 -1"}, {"type": "choice", "q": "混合传参顺序规则？", "options": ["关键字在前也行", "位置参数在前，关键字在后", "随便", "关键字不能和位置混"], "answer": 1, "explain": "先位置后关键字，否则歧义报错。"}, {"type": "code", "q": "定义函数 tip(bill, rate=0.15) 返回小费（保留两位），打印 tip(200)", "code": "def tip(bill, rate=0.15):\n    return round(bill * rate, 2)\nprint(tip(200))", "expect": "30.0", "hint": "bill*rate"}]}, {"id": 13, "no": "ⅩⅢ", "title": "模块与导入", "weeks": "第 7 周", "diff": "★★☆", "full": true, "story": {"tutor": "林纳斯·托瓦兹（Linus Torvalds）", "era": "芬兰 · Linux 之父", "fact": "Linux 内核不是一个人写完的——几千人各写各的模块，拼成整个系统。模块化是「分工的代码化」：import 别人的轮子，export 自己的成果，谁也不看谁的完整源码也能协作。", "quote": "「软件像性一样，免费时更好。」"}, "map": ["import 用法", "from 导入", "标准库", "random/math 实战"], "sections": [{"t": "import：借轮子", "p": "import 模块后，用 模块名.函数 调用。import math 后写 math.sqrt(16)。", "code": "import math\nprint(math.sqrt(16))\nprint(math.pi)"}, {"t": "from 导入：指名道姓", "p": "from 模块 import 名字，直接用名字不用前缀。少打字，但可能命名冲突。", "code": "from math import sqrt, pi\nprint(sqrt(25))\nprint(round(pi, 2))"}, {"t": "标准库：Python 自带百宝箱", "p": "random（随机）、math（数学）、datetime（时间）、os（系统）等，安装 Python 就带，import 即用。", "code": "import random\nprint(random.randint(1, 6))"}, {"t": "用模块名.还是 from？", "p": "常用、短名用 from；防冲突、想清楚来源用 import。团队项目偏爱 import 模块名。", "code": "import random\nfor _ in range(3):\n    print(random.choice([\"石头\", \"剪刀\", \"布\"]))"}], "quiz": [{"type": "choice", "q": "import math 后调用平方根的正确写法？", "options": ["sqrt(16)", "math.sqrt(16)", "import.sqrt(16)", "sqrt.math(16)"], "answer": 1, "explain": "模块名.函数，math.sqrt(16)。"}, {"type": "code", "q": "用 math.sqrt 打印 81 的平方根", "code": "import math\nprint(math.sqrt(81))", "expect": "9.0", "hint": "math.sqrt"}, {"type": "choice", "q": "from random import randint 后如何调用 1-6 随机整数？", "options": ["random.randint(1,6)", "randint(1,6)", "random.rand(1,6)", "randint.random(1,6)"], "answer": 1, "explain": "from 导入后直接函数名调用。"}, {"type": "code", "q": "打印圆周率 pi 保留 2 位小数", "code": "import math\nprint(round(math.pi, 2))", "expect": "3.14", "hint": "round(pi,2)"}, {"type": "choice", "q": "标准库是什么？", "options": ["别人付费买的库", "Python 安装自带的一批模块", "网上下载的框架", "只有 math 一个"], "answer": 1, "explain": "标准库随 Python 安装，import 即用不联网。"}, {"type": "code", "q": "用 random.randint 打印一个 1 到 100 的随机整数（判题只看是否数字，用 if 保证格式）", "code": "import random\nprint(random.randint(1, 100))", "expect": "", "hint": "随机题 expect 空=跑通即过"}, {"type": "choice", "q": "import random 和 from random import randint 的区别？", "options": ["没区别", "前者调用要 random.xxx，后者直接 xxx", "前者更快", "后者不能用于随机"], "answer": 1, "explain": "import 保留命名空间，from 直接引入名字。"}, {"type": "choice", "q": "写自己的模块 my_mod.py，别的文件怎么用？", "options": ["import my_mod", "from my_mod import *", "都行（同目录下）", "只能复制粘贴"], "answer": 2, "explain": "同目录下 import 自己的 .py 文件即可。"}, {"type": "choice", "q": "import datetime 常用来干什么？", "options": ["画图", "取当前日期时间", "网络请求", "加密"], "answer": 1, "explain": "datetime 模块处理日期时间。"}, {"type": "code", "q": "用 math.floor 打印 3.7 向下取整", "code": "import math\nprint(math.floor(3.7))", "expect": "3", "hint": "floor 向下"}], "exam": [{"type": "choice", "q": "import 语句通常放在？", "options": ["函数中间", "文件开头", "循环里", "return 后"], "answer": 1, "explain": "惯例：import 集中放文件顶部。"}, {"type": "code", "q": "from math import ceil 打印 3.2 向上取整", "code": "from math import ceil\nprint(ceil(3.2))", "expect": "4", "hint": "ceil 向上"}, {"type": "choice", "q": "想用随机选一个元素，用 random 的哪个函数？", "options": ["random.randint", "random.choice", "random.pi", "random.max"], "answer": 1, "explain": "choice 从序列随机选一个。"}, {"type": "code", "q": "import random 打印 random.choice 从 [\"猫\",\"狗\",\"鸟\"] 选一个", "code": "import random\nprint(random.choice([\"猫\", \"狗\", \"鸟\"]))", "expect": "", "hint": "随机题跑通即过"}, {"type": "choice", "q": "from math import * 的含义？", "options": ["导入全部名字", "导入 math 模块", "报错", "导入空"], "answer": 0, "explain": "* 导入模块所有公开名字，慎用（污染命名空间）。"}, {"type": "code", "q": "用 math.pow(2, 10) 打印 2 的 10 次方", "code": "import math\nprint(int(math.pow(2, 10)))", "expect": "1024", "hint": "2**10"}, {"type": "choice", "q": "两个模块都有 f 函数，from a import f; from b import f 后 f 是？", "options": ["a 的", "b 的（后导入覆盖）", "两个都在", "报错"], "answer": 1, "explain": "同名后者覆盖前者，这是 from 导入的冲突风险。"}, {"type": "code", "q": "import random 用 seed(1) 固定随机后打印 randint(1, 10)", "code": "import random\nrandom.seed(1)\nprint(random.randint(1, 10))", "expect": "2", "hint": "seed 固定后结果确定（Pyodide 同 seed 同值）"}, {"type": "choice", "q": "模块文件与主程序分离的好处？", "options": ["更慢", "可复用、可测试", "必须分离", "文件更少"], "answer": 1, "explain": "模块化让代码可复用可测试。"}, {"type": "code", "q": "from math import sqrt, log 打印 log(100, 10)", "code": "from math import sqrt, log\nprint(log(100, 10))", "expect": "2.0", "hint": "log(x, base)"}]}, {"id": 14, "no": "ⅩⅣ", "title": "函数与作用域", "weeks": "第 7 周", "diff": "★★☆", "full": true, "story": {"tutor": "艾伦·凯（Alan Kay）", "era": "美国 · 面向对象之父", "fact": "艾伦·凯说「预测未来最好的方式是发明它」。作用域是 Python 的「势力范围」：函数里的变量外面看不见，外面改了函数里未必知道。理解作用域，就理解了一半的「变量去哪了」bug。", "quote": "「简单的事情应该简单，复杂的事情应该可能。」"}, "map": ["局部 vs 全局", "global 声明", "不可变陷阱", "闭包初探"], "sections": [{"t": "局部变量：函数里的私人空间", "p": "函数内赋值的变量是局部变量，函数结束即消失。外面访问会 NameError。", "code": "def f():\n    x = 10\n    print(x)\nf()\n# print(x)  # NameError"}, {"t": "全局变量：模块级共享", "p": "模块顶层赋值的变量全局可见。函数里读全局可以，改全局要 global。", "code": "x = 5\ndef f():\n    print(x)   # 读全局 OK\nf()"}, {"t": "global：明确声明要改全局", "p": "函数里想修改全局变量，先 global x。不声明就赋值 = 创建局部变量（遮蔽）。", "code": "x = 5\ndef add():\n    global x\n    x += 1\nadd()\nprint(x)"}, {"t": "闭包初探", "p": "内层函数引用外层函数的变量，外层返回内层——这个「记住环境」的函数叫闭包。先认识现象，细节后补。", "code": "def make(x):\n    def inner(y):\n        return x + y\n    return inner\nadd5 = make(5)\nprint(add5(3))"}], "quiz": [{"type": "choice", "q": "函数内 x=10，函数外 print(x) 会？", "options": ["打印 10", "NameError", "打印 None", "打印 0"], "answer": 1, "explain": "函数内是局部变量，外部访问不到。"}, {"type": "code", "q": "函数内定义局部变量 secret=42 并打印它，再在外面打印全局 x=1", "code": "x = 1\ndef show():\n    secret = 42\n    print(secret)\nshow()\nprint(x)", "expect": "42\n1", "hint": "局部只函数内"}, {"type": "choice", "q": "函数内要修改全局变量必须？", "options": ["直接赋值", "先声明 global", "用 return 覆盖", "无法修改"], "answer": 1, "explain": "global 声明后才允许改写全局。"}, {"type": "code", "q": "全局 count=0，定义函数 bump() 用 global 让 count 加 1，调用两次后打印 count", "code": "count = 0\ndef bump():\n    global count\n    count += 1\nbump()\nbump()\nprint(count)", "expect": "2", "hint": "global count"}, {"type": "choice", "q": "def f(): print(x)，x 是模块级全局，调用 f() 会？", "options": ["NameError", "正常打印全局 x", "打印 None", "报 SyntaxError"], "answer": 1, "explain": "函数可读全局变量。"}, {"type": "code", "q": "全局 name=\"全局\"，函数里赋 name=\"局部\" 并打印，之后打印全局 name", "code": "name = \"全局\"\ndef f():\n    name = \"局部\"\n    print(name)\nf()\nprint(name)", "expect": "局部\n全局", "hint": "函数内赋值是新局部"}, {"type": "choice", "q": "「遮蔽」指？", "options": ["变量被加密", "局部变量和全局同名，局部优先", "变量消失", "报错"], "answer": 1, "explain": "同名时函数内局部变量遮蔽全局。"}, {"type": "choice", "q": "闭包的特点？", "options": ["不能嵌套函数", "内层记住外层变量环境", "必须用 global", "只能用于类"], "answer": 1, "explain": "闭包让内层函数记住外层环境。"}, {"type": "code", "q": "定义 outer(x) 返回 inner(y) 返回 x+y 的闭包，用 add7=outer(7) 后打印 add7(5)", "code": "def outer(x):\n    def inner(y):\n        return x + y\n    return inner\nadd7 = outer(7)\nprint(add7(5))", "expect": "12", "hint": "闭包记住 x=7"}, {"type": "choice", "q": "函数里 global x 后 x+=1，外面 print(x)？", "options": ["报错", "打印加 1 后的全局值", "打印 None", "打印原值"], "answer": 1, "explain": "global 让函数内修改作用于全局。"}], "exam": [{"type": "choice", "q": "局部变量存在哪里？", "options": ["全局区", "函数自己的作用域", "文件里", "库里"], "answer": 1, "explain": "局部变量在函数作用域内有效。"}, {"type": "code", "q": "全局 g=100，函数内读 g 并打印，再打印全局 g", "code": "g = 100\ndef f():\n    print(g)\nf()", "expect": "100", "hint": "函数可读全局"}, {"type": "choice", "q": "函数内 global 声明放哪？", "options": ["函数末尾", "使用前（函数开头）", "哪都行", "函数外"], "answer": 1, "explain": "global 声明在函数内、使用该变量之前。"}, {"type": "code", "q": "全局 total=0，定义 addto(n) 用 global 累加，调用 addto(5) addto(3) 后打印 total", "code": "total = 0\ndef addto(n):\n    global total\n    total += n\naddto(5)\naddto(3)\nprint(total)", "expect": "8", "hint": "global total"}, {"type": "choice", "q": "函数参数是全局变量的值时，函数内改参数影响全局吗？", "options": ["影响", "不影响（形参是副本）", "报错", "看运气"], "answer": 1, "explain": "形参接收的是值（不可变对象），改形参不动全局。"}, {"type": "code", "q": "x=1，函数 f 内 global x 后 x=99，打印全局 x", "code": "x = 1\ndef f():\n    global x\n    x = 99\nf()\nprint(x)", "expect": "99", "hint": "global 改写"}, {"type": "choice", "q": "Python 里作用域查找顺序是？", "options": ["全局→局部", "局部→全局→内置", "内置→全局", "随机"], "answer": 1, "explain": "先局部，再全局，再 Python 内置。"}, {"type": "code", "q": "定义 make_adder(n) 返回把参数加 n 的函数，用 add10 后打印 add10(4)", "code": "def make_adder(n):\n    def adder(x):\n        return x + n\n    return adder\nadd10 = make_adder(10)\nprint(add10(4))", "expect": "14", "hint": "闭包"}, {"type": "choice", "q": "写代码时「魔法数字」（如 3.14 直接写）的问题？", "options": ["运行慢", "含义不明难维护", "一定报错", "没有"], "answer": 1, "explain": "魔法数字应命名常量或参数化，否则改一处漏一处。"}, {"type": "code", "q": "全局 PI=3.14，定义 area(r) 返回圆面积（读全局 PI），打印 area(2) 保留 2 位", "code": "PI = 3.14\ndef area(r):\n    return round(PI * r * r, 2)\nprint(area(2))", "expect": "12.56", "hint": "PI*r*r"}]}, {"id": 15, "no": "ⅩⅤ", "title": "类与实例", "weeks": "第 8 周", "diff": "★★☆", "full": true, "story": {"tutor": "阿黛尔·戈德堡（Adele Goldberg）", "era": "美国 · Smalltalk 先驱", "fact": "戈德堡参与设计了 Smalltalk——第一个把「对象」变成日常工具的编程环境。对象 = 数据 + 行为的打包。类是一张蓝图，实例是按蓝图造出来的具体物件。", "quote": "「设计系统时，你要想着使用者会怎么把它玩出花样。」"}, "map": ["类与对象", "__init__", "self", "创建实例"], "sections": [{"t": "类：造物的蓝图", "p": "class 定义类，名字大写开头。类描述「这类东西有什么数据、能做什么」。", "code": "class Dog:\n    pass\nd = Dog()\nprint(type(d))"}, {"t": "__init__：初始化构造器", "p": "创建实例时自动调用 __init__，常用来给实例设初始属性。", "code": "class Dog:\n    def __init__(self, name):\n        self.name = name\nd = Dog(\"旺财\")\nprint(d.name)"}, {"t": "self：实例自己", "p": "方法第一个参数永远是 self（实例本身）。self.属性 = 这个实例的属性。", "code": "class Dog:\n    def __init__(self, name, age):\n        self.name = name\n        self.age = age\nd = Dog(\"旺财\", 3)\nprint(d.name, d.age)"}, {"t": "实例：蓝图造出的物件", "p": "同一类可造多个实例，各自属性独立，互不干扰。", "code": "class Dog:\n    def __init__(self, name):\n        self.name = name\na = Dog(\"A\")\nb = Dog(\"B\")\na.name = \"改名\"\nprint(a.name, b.name)"}], "quiz": [{"type": "choice", "q": "定义类用什么关键字？", "options": ["def", "class", "struct", "object"], "answer": 1, "explain": "class 关键字定义类。"}, {"type": "code", "q": "定义类 Cat（空实现 pass），创建实例 c 并打印 type(c).__name__", "code": "class Cat:\n    pass\nc = Cat()\nprint(type(c).__name__)", "expect": "Cat", "hint": "class + 实例化"}, {"type": "choice", "q": "__init__ 方法什么时候执行？", "options": ["类定义时", "创建实例时", "调用方法时", "删除对象时"], "answer": 1, "explain": "实例化时自动调用 __init__。"}, {"type": "code", "q": "class Person 有 __init__(self, name)，创建 p=Person(\"小明\") 打印 p.name", "code": "class Person:\n    def __init__(self, name):\n        self.name = name\np = Person(\"小明\")\nprint(p.name)", "expect": "小明", "hint": "self.name 存属性"}, {"type": "choice", "q": "方法里 self 指什么？", "options": ["类本身", "当前实例", "父类", "模块"], "answer": 1, "explain": "self 是正在操作的实例对象。"}, {"type": "code", "q": "class Bank 有 __init__(self, money=0) 存 self.money，创建 b=Bank(100) 打印 b.money", "code": "class Bank:\n    def __init__(self, money=0):\n        self.money = money\nb = Bank(100)\nprint(b.money)", "expect": "100", "hint": "默认参数 0"}, {"type": "choice", "q": "同一类造的两个实例的属性？", "options": ["共享同一份", "各自独立", "自动同步", "只读"], "answer": 1, "explain": "实例属性各自独立，互不影响。"}, {"type": "code", "q": "class Point 有 __init__(x, y) 存坐标，创建 p=Point(3, 4) 打印 p.x 和 p.y", "code": "class Point:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\np = Point(3, 4)\nprint(p.x, p.y)", "expect": "3 4", "hint": "print 两个值空格分隔"}, {"type": "choice", "q": "类名命名的 Python 惯例？", "options": ["全小写", "大写开头驼峰", "全大写", "下划线分隔"], "answer": 1, "explain": "类名用 PascalCase（首字母大写）。"}, {"type": "code", "q": "class Student 有 __init__(name, score) 存属性，创建 s 打印 name 和 score", "code": "class Student:\n    def __init__(self, name, score):\n        self.name = name\n        self.score = score\ns = Student(\"张三\", 95)\nprint(s.name, s.score)", "expect": "张三 95", "hint": "两个属性"}], "exam": [{"type": "choice", "q": "实例化类 Dog 的写法？", "options": ["Dog", "Dog()", "new Dog()", "create Dog"], "answer": 1, "explain": "类名加括号即实例化。"}, {"type": "code", "q": "class Phone 有 __init__(brand)，创建 p=Phone(\"华为\") 打印 p.brand", "code": "class Phone:\n    def __init__(self, brand):\n        self.brand = brand\np = Phone(\"华为\")\nprint(p.brand)", "expect": "华为", "hint": "实例属性"}, {"type": "choice", "q": "不写 __init__ 的类能实例化吗？", "options": ["不能", "能，无自定义属性", "报错", "只能继承"], "answer": 1, "explain": "不写 __init__ 也可实例化，只是无初始属性逻辑。"}, {"type": "code", "q": "class Circle 存半径 r，创建 c=Circle(5) 打印 c.r", "code": "class Circle:\n    def __init__(self, r):\n        self.r = r\nc = Circle(5)\nprint(c.r)", "expect": "5", "hint": "存 r"}, {"type": "choice", "q": "self.name = name 这一步在做什么？", "options": ["定义全局变量", "把实参存成实例属性", "调用方法", "删除属性"], "answer": 1, "explain": "把传入的 name 存到实例自己的属性上。"}, {"type": "code", "q": "class User 有 __init__(self, name, level=1)，创建 u=User(\"鼠哥\") 打印 name 和 level", "code": "class User:\n    def __init__(self, name, level=1):\n        self.name = name\n        self.level = level\nu = User(\"鼠哥\")\nprint(u.name, u.level)", "expect": "鼠哥 1", "hint": "默认 level=1"}, {"type": "choice", "q": "对象的属性在类外能改吗？", "options": ["不能", "能（直接 对象.属性=值）", "只能读", "需声明"], "answer": 1, "explain": "Python 属性默认公开，外部可直接赋值修改。"}, {"type": "code", "q": "class Lamp 有 __init__(self, on=False)，创建开灯 l=Lamp(True) 打印 l.on", "code": "class Lamp:\n    def __init__(self, on=False):\n        self.on = on\nl = Lamp(True)\nprint(l.on)", "expect": "True", "hint": "布尔属性"}, {"type": "choice", "q": "一辆车的品牌/颜色/速度是它的？", "options": ["方法", "属性", "类", "模块"], "answer": 1, "explain": "描述对象状态的数据是属性。"}, {"type": "code", "q": "class Book 有 __init__(title, author, pages)，创建 b 打印三个属性", "code": "class Book:\n    def __init__(self, title, author, pages):\n        self.title = title\n        self.author = author\n        self.pages = pages\nb = Book(\"Python入门\", \"张三\", 300)\nprint(b.title, b.author, b.pages)", "expect": "Python入门 张三 300", "hint": "三个属性顺序打"}]}, {"id": 16, "no": "ⅩⅥ", "title": "方法设计", "weeks": "第 8 周", "diff": "★★★", "full": true, "story": {"tutor": "沃德·坎宁安（Ward Cunningham）", "era": "美国 · Wiki 之父", "fact": "坎宁安发明 Wiki 时坚持「简单规则、自由演化」。设计类方法也一样：每个方法做一件清楚的事，起清楚的名字，对象之间靠方法对话而非乱摸属性。", "quote": "「能跑就行」和「能改就行」是两码事，后者才是软件的价值。\""}, "map": ["实例方法", "方法封装", "方法返回值", "设计练习"], "sections": [{"t": "实例方法：让对象会做事", "p": "类里 def 的方法是实例方法，第一个参数 self，调用时 对象.方法()。", "code": "class Dog:\n    def bark(self):\n        print(\"汪汪\")\nd = Dog()\nd.bark()"}, {"t": "方法操作属性", "p": "方法里用 self.属性 读写，方法可以改对象状态。", "code": "class Counter:\n    def __init__(self):\n        self.n = 0\n    def add(self):\n        self.n += 1\nc = Counter()\nc.add()\nc.add()\nprint(c.n)"}, {"t": "方法返回值", "p": "方法可以 return 计算结果，不一定要 print。", "code": "class Rect:\n    def __init__(self, w, h):\n        self.w = w\n        self.h = h\n    def area(self):\n        return self.w * self.h\nr = Rect(3, 4)\nprint(r.area())"}, {"t": "设计：一个方法一件事", "p": "好方法名是动词（deposit 存款、withdraw 取款、balance 查余额），内部逻辑短小。", "code": "class Bank:\n    def __init__(self):\n        self.money = 0\n    def deposit(self, n):\n        self.money += n\n    def balance(self):\n        return self.money\nb = Bank()\nb.deposit(100)\nprint(b.balance())"}], "quiz": [{"type": "choice", "q": "定义实例方法时第一个参数必须是？", "options": ["cls", "self", "this", "无"], "answer": 1, "explain": "实例方法第一个参数惯例叫 self。"}, {"type": "code", "q": "class Bird 有方法 fly(self) 打印 \"飞了\"，创建 b 调用", "code": "class Bird:\n    def fly(self):\n        print(\"飞了\")\nb = Bird()\nb.fly()", "expect": "飞了", "hint": "对象.方法()"}, {"type": "choice", "q": "方法想返回计算结果用什么？", "options": ["print", "return", "yield", "pass"], "answer": 1, "explain": "return 把值交还给调用处。"}, {"type": "code", "q": "class Square 存边长 side，方法 area() 返回面积，创建 s=Square(5) 打印 s.area()", "code": "class Square:\n    def __init__(self, side):\n        self.side = side\n    def area(self):\n        return self.side * self.side\ns = Square(5)\nprint(s.area())", "expect": "25", "hint": "side*side"}, {"type": "choice", "q": "class Bank: def deposit(self, n): self.money += n 的语义？", "options": ["查余额", "存款，改状态", "取款", "删除"], "answer": 1, "explain": "deposit 方法修改余额状态。"}, {"type": "code", "q": "class Counter 初始 0，方法 add(n) 累加，创建后 add(3) add(4) 打印 get() 值", "code": "class Counter:\n    def __init__(self):\n        self.n = 0\n    def add(self, n):\n        self.n += n\n    def get(self):\n        return self.n\nc = Counter()\nc.add(3)\nc.add(4)\nprint(c.get())", "expect": "7", "hint": "累加两次"}, {"type": "choice", "q": "为什么不让外部直接改 self.money 而用方法？", "options": ["更慢", "方法可加校验逻辑", "外部改不了", "没区别"], "answer": 1, "explain": "方法封装了规则（如不允许负数），比裸属性安全。"}, {"type": "code", "q": "class Person 有 name 和方法 greet() 返回 \"你好，我是\"+name，创建并打印调用结果", "code": "class Person:\n    def __init__(self, name):\n        self.name = name\n    def greet(self):\n        return \"你好，我是\" + self.name\np = Person(\"鼠哥\")\nprint(p.greet())", "expect": "你好，我是鼠哥", "hint": "方法 return"}, {"type": "choice", "q": "方法里能调用同类的另一个方法吗？", "options": ["不能", "能，用 self.方法()", "只能类外调", "报错"], "answer": 1, "explain": "self.方法名() 在方法内调用同类方法。"}, {"type": "code", "q": "class Wallet 初始 0，方法 earn(n)、spend(n)、money() 返回余额，earn 100 spend 30 后打印余额", "code": "class Wallet:\n    def __init__(self):\n        self.b = 0\n    def earn(self, n):\n        self.b += n\n    def spend(self, n):\n        self.b -= n\n    def money(self):\n        return self.b\nw = Wallet()\nw.earn(100)\nw.spend(30)\nprint(w.money())", "expect": "70", "hint": "100-30"}], "exam": [{"type": "choice", "q": "class A: def m(self): ... 调用方式是？", "options": ["A.m()", "a.m()（a 是实例）", "m()", "A.m(self)"], "answer": 1, "explain": "实例.方法()。"}, {"type": "code", "q": "class Fish 有方法 swim() 打印 \"游了\"，创建 f 调用 swim 两次", "code": "class Fish:\n    def swim(self):\n        print(\"游了\")\nf = Fish()\nf.swim()\nf.swim()", "expect": "游了\n游了", "hint": "调两次两行"}, {"type": "choice", "q": "方法直接改 self 属性 vs return 新值，区别？", "options": ["没区别", "前者改状态后者交结果", "前者更快", "后者必错"], "answer": 1, "explain": "改状态适合「动作」，return 适合「查询」。"}, {"type": "code", "q": "class Temp 存 c 摄氏度，方法 f() 返回华氏（c*9/5+32），Temp(100).f() 打印", "code": "class Temp:\n    def __init__(self, c):\n        self.c = c\n    def f(self):\n        return self.c * 9 / 5 + 32\nt = Temp(100)\nprint(t.f())", "expect": "212.0", "hint": "c*9/5+32"}, {"type": "choice", "q": "方法命名「存款」用哪个好？", "options": ["do_money", "deposit", "money_do", "change"], "answer": 1, "explain": "动词开头明确动作：deposit。"}, {"type": "code", "q": "class Timer 初始 0，方法 tick() 加 1、read() 返回，tick 3 次打印 read", "code": "class Timer:\n    def __init__(self):\n        self.t = 0\n    def tick(self):\n        self.t += 1\n    def read(self):\n        return self.t\nt = Timer()\nt.tick()\nt.tick()\nt.tick()\nprint(t.read())", "expect": "3", "hint": "三次加一"}, {"type": "choice", "q": "「封装」指？", "options": ["把代码藏起来加密", "把数据和操作它的方法绑在一起并隐藏细节", "多写注释", "把类放文件里"], "answer": 1, "explain": "封装 = 数据 + 操作绑定，外部只通过方法交互。"}, {"type": "code", "q": "class Grade 存 score，方法 level() 返回 A(>=90)/B(>=80)/C(其他)，测试 85 分", "code": "class Grade:\n    def __init__(self, score):\n        self.score = score\n    def level(self):\n        if self.score >= 90:\n            return \"A\"\n        if self.score >= 80:\n            return \"B\"\n        return \"C\"\ng = Grade(85)\nprint(g.level())", "expect": "B", "hint": "分支返回"}, {"type": "choice", "q": "一个对象有很多小方法 vs 一个大方法？", "options": ["大方法好", "小方法更清晰可复用", "无所谓", "小方法一定慢"], "answer": 1, "explain": "方法单一职责，易读易测。"}, {"type": "code", "q": "class Account 有 name 和 balance，方法 show() 返回 \"name: balance\"，创建后打印", "code": "class Account:\n    def __init__(self, name, balance):\n        self.name = name\n        self.balance = balance\n    def show(self):\n        return self.name + \": \" + str(self.balance)\na = Account(\"鼠哥\", 500)\nprint(a.show())", "expect": "鼠哥: 500", "hint": "拼接字符串"}]}, {"id": 17, "no": "ⅩⅦ", "title": "继承与重写", "weeks": "第 9 周", "diff": "★★★", "full": true, "story": {"tutor": "克里斯托弗·斯特雷奇（Christopher Strachey）", "era": "英国 · 编程语言理论家", "fact": "斯特雷奇 1967 年提出「多态」概念：同一接口，不同实现。继承让子类「是」父类的一种（Dog is an Animal），重写让子类用自己的版本替换父类行为。", "quote": "「抽象不是省掉细节，而是把不相关的细节放到背后。」"}, "map": ["继承", "super()", "方法重写", "多态"], "sections": [{"t": "继承：子类拥有父类", "p": "class 子类(父类): 子类自动拥有父类的属性和方法，可加自己的。", "code": "class Animal:\n    def __init__(self, name):\n        self.name = name\n    def speak(self):\n        print(\"...\")\nclass Dog(Animal):\n    pass\nd = Dog(\"旺财\")\nprint(d.name)"}, {"t": "super()：调父类的初始化", "p": "子类 __init__ 里 super().__init__(...) 先初始化父类部分。", "code": "class Animal:\n    def __init__(self, name):\n        self.name = name\nclass Dog(Animal):\n    def __init__(self, name, age):\n        super().__init__(name)\n        self.age = age\nd = Dog(\"旺财\", 3)\nprint(d.name, d.age)"}, {"t": "重写：子类换掉父类行为", "p": "子类定义同名方法即覆盖父类版本。", "code": "class Animal:\n    def speak(self):\n        return \"...\"\nclass Dog(Animal):\n    def speak(self):\n        return \"汪汪\"\nd = Dog()\nprint(d.speak())"}, {"t": "多态：同一调用不同表现", "p": "不同子类对同一方法各自实现，调用方不用关心具体类型。", "code": "class Cat(Animal):\n    def speak(self):\n        return \"喵\"\ndef say(a):\n    print(a.speak())\nsay(Dog())\nsay(Cat())"}], "quiz": [{"type": "choice", "q": "class Dog(Animal): 表示？", "options": ["Dog 包含 Animal", "Dog 继承 Animal", "并列关系", "Animal 继承 Dog"], "answer": 1, "explain": "括号里是父类，Dog 继承 Animal。"}, {"type": "code", "q": "class Animal 有 __init__ 存 name，class Dog(Animal) 空实现，创建 d=Dog(\"旺财\") 打印 d.name", "code": "class Animal:\n    def __init__(self, name):\n        self.name = name\nclass Dog(Animal):\n    pass\nd = Dog(\"旺财\")\nprint(d.name)", "expect": "旺财", "hint": "继承父类 __init__"}, {"type": "choice", "q": "子类 __init__ 里调父类初始化用？", "options": ["Animal()", "super().__init__(...)", "parent.init()", "self.parent()"], "answer": 1, "explain": "super() 拿到父类引用，调其 __init__。"}, {"type": "code", "q": "class Animal 有 __init__ 存 name；class Cat(Animal) 的 __init__ 接收 name, color，super 初始化 name 再存 color。打印结果", "code": "class Animal:\n    def __init__(self, name):\n        self.name = name\nclass Cat(Animal):\n    def __init__(self, name, color):\n        super().__init__(name)\n        self.color = color\nc = Cat(\"咪咪\", \"白\")\nprint(c.name, c.color)", "expect": "咪咪 白", "hint": "super 初始化 name"}, {"type": "choice", "q": "子类里定义和父类同名方法会发生？", "options": ["报错", "覆盖（重写）父类版本", "两个都执行", "只执行父类"], "answer": 1, "explain": "同名方法子类版本覆盖父类，称重写。"}, {"type": "code", "q": "class Animal speak() 返回 \"...\"；class Dog(Animal) 重写 speak 返回 \"汪汪\"。打印 Dog() 的 speak", "code": "class Animal:\n    def speak(self):\n        return \"...\"\nclass Dog(Animal):\n    def speak(self):\n        return \"汪汪\"\nd = Dog()\nprint(d.speak())", "expect": "汪汪", "hint": "重写生效"}, {"type": "choice", "q": "「猫是一种动物」在代码里对应？", "options": ["class Animal(Cat)", "class Cat(Animal)", "Cat = Animal", "import Animal"], "answer": 1, "explain": "子类在括号里继承父类：Cat is a Animal。"}, {"type": "code", "q": "class Shape area() 返回 0；class Rect(Shape) 存 w,h 重写 area 返回 w*h。Rect(3,4).area() 打印", "code": "class Shape:\n    def area(self):\n        return 0\nclass Rect(Shape):\n    def __init__(self, w, h):\n        self.w = w\n        self.h = h\n    def area(self):\n        return self.w * self.h\nr = Rect(3, 4)\nprint(r.area())", "expect": "12", "hint": "子类重写"}, {"type": "choice", "q": "多态的好处？", "options": ["代码更快", "同一调用方式处理不同子类", "必须写很多类", "无法实现"], "answer": 1, "explain": "调用方统一接口，具体行为各子类自定。"}, {"type": "code", "q": "class Duck 有 fly() 返回 \"飞不高\"；class Eagle(Duck) 重写 fly 返回 \"飞得高\"。列表里各调一次", "code": "class Duck:\n    def fly(self):\n        return \"飞不高\"\nclass Eagle(Duck):\n    def fly(self):\n        return \"飞得高\"\nprint(Duck().fly())\nprint(Eagle().fly())", "expect": "飞不高\n飞得高", "hint": "多态"}], "exam": [{"type": "choice", "q": "继承的意义？", "options": ["代码变长", "复用父类代码并扩展", "类变复杂", "删除父类"], "answer": 1, "explain": "继承实现代码复用与扩展。"}, {"type": "code", "q": "class Vehicle 有 move() 返回 \"移动\"；class Car(Vehicle) 重写 move 返回 \"开走\"。打印 Car().move()", "code": "class Vehicle:\n    def move(self):\n        return \"移动\"\nclass Car(Vehicle):\n    def move(self):\n        return \"开走\"\nprint(Car().move())", "expect": "开走", "hint": "重写"}, {"type": "choice", "q": "不写 super().__init__ 直接 self.xxx = xxx？", "options": ["一定错", "父类部分不初始化，可能丢属性", "没影响", "更快"], "answer": 1, "explain": "父类定义的属性若不经 super 初始化可能缺失。"}, {"type": "code", "q": "class Animal 存 name；class Bird(Animal) __init__ 用 super 存 name 并加 can_fly=True。创建并打印", "code": "class Animal:\n    def __init__(self, name):\n        self.name = name\nclass Bird(Animal):\n    def __init__(self, name):\n        super().__init__(name)\n        self.can_fly = True\nb = Bird(\"小雀\")\nprint(b.name, b.can_fly)", "expect": "小雀 True", "hint": "继承+新属性"}, {"type": "choice", "q": "父子类同名方法，调用子类实例时执行？", "options": ["父类版", "子类版", "两个都", "报错"], "answer": 1, "explain": "动态绑定：子类版本优先。"}, {"type": "code", "q": "class Monster 有 hp；class Boss(Monster) super 初始化后加 power=100。创建 Boss 打印 hp 和 power", "code": "class Monster:\n    def __init__(self, hp):\n        self.hp = hp\nclass Boss(Monster):\n    def __init__(self, hp):\n        super().__init__(hp)\n        self.power = 100\nb = Boss(500)\nprint(b.hp, b.power)", "expect": "500 100", "hint": "super+新属性"}, {"type": "choice", "q": "「复用已有类的行为，再加自己的」用？", "options": ["继承", "循环", "import", "全局变量"], "answer": 1, "explain": "继承天然支持扩展复用。"}, {"type": "code", "q": "class Sound play() 返回 \"...\"；class Piano(Sound) 返回 \"叮咚\"；class Drum(Sound) 返回 \"咚咚\"。都打印", "code": "class Sound:\n    def play(self):\n        return \"...\"\nclass Piano(Sound):\n    def play(self):\n        return \"叮咚\"\nclass Drum(Sound):\n    def play(self):\n        return \"咚咚\"\nprint(Piano().play())\nprint(Drum().play())", "expect": "叮咚\n咚咚", "hint": "多态"}, {"type": "choice", "q": "多层继承 class C(B): class B(A): 中 C 有哪些？", "options": ["只有自己的", "A+B+C 的", "只有 A", "报错"], "answer": 1, "explain": "继承链上所有父类能力都传递。"}, {"type": "code", "q": "class Animal __init__ 存 name、speak() 返回 \"...\"；class Dog 重写 speak。列表 animals 两个对象分别调 speak", "code": "class Animal:\n    def __init__(self, name):\n        self.name = name\n    def speak(self):\n        return \"...\"\nclass Dog(Animal):\n    def speak(self):\n        return \"汪汪\"\nfor a in [Animal(\"x\"), Dog(\"旺财\")]:\n    print(a.speak())", "expect": "...\n汪汪", "hint": "for 遍历多态"}]}, {"id": 18, "no": "ⅩⅧ", "title": "类进阶", "weeks": "第 9 周", "diff": "★★★", "full": true, "story": {"tutor": "彼得·诺尔（Peter Naur）", "era": "丹麦 · 编程语言先驱", "fact": "诺尔说编程是「理论构建」——你在脑子里建一个关于数据如何流动的模型。类进阶的魔法方法（__str__/__eq__）就是让对象像内置类型一样自然：能打印、能比较、能运算。", "quote": "「程序不只是指令序列，它是你对问题形成的理解。」"}, "map": ["__str__", "__eq__ 比较", "类属性", "数据类思维"], "sections": [{"t": "__str__：让对象会说话", "p": "定义 __str__ 返回字符串，print(对象) 时自动调用，而不是打印内存地址。", "code": "class Point:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\n    def __str__(self):\n        return \"(\" + str(self.x) + \",\" + str(self.y) + \")\"\np = Point(1, 2)\nprint(p)"}, {"t": "__eq__：让对象可比", "p": "定义 __eq__ 说明「两个对象什么时候相等」，默认比较地址。", "code": "class Point:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\n    def __eq__(self, o):\n        return self.x == o.x and self.y == o.y\nprint(Point(1,2) == Point(1,2))"}, {"t": "类属性：所有实例共享", "p": "类体里直接赋值的是类属性，所有实例共享；实例属性 self.xxx 各自独立。", "code": "class Dog:\n    legs = 4\n    def __init__(self, name):\n        self.name = name\na = Dog(\"A\")\nprint(Dog.legs, a.legs)"}, {"t": "数据类思维", "p": "把「一组相关数据 + 操作」收进类，代码意图清晰。类是命名良好的数据容器 + 行为。", "code": "class Item:\n    def __init__(self, name, price):\n        self.name = name\n        self.price = price\n    def __str__(self):\n        return self.name + \":\" + str(self.price)\nprint(Item(\"书\", 39))"}], "quiz": [{"type": "choice", "q": "__str__ 方法的作用？", "options": ["把对象转字符串给人看", "删除对象", "加密对象", "复制对象"], "answer": 0, "explain": "print(对象) 显示 __str__ 返回的内容。"}, {"type": "code", "q": "class Point 有 x,y，定义 __str__ 返回 \"(x,y)\"，打印 Point(2,3)", "code": "class Point:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\n    def __str__(self):\n        return \"(\" + str(self.x) + \",\" + str(self.y) + \")\"\nprint(Point(2, 3))", "expect": "(2,3)", "hint": "__str__ 拼接"}, {"type": "choice", "q": "没定义 __str__ 时 print(对象) 显示？", "options": ["属性字典", "内存地址样式", "报错", "空"], "answer": 1, "explain": "默认打印对象类型和内存地址（<__main__.Point object at ...>）。"}, {"type": "code", "q": "class User 有 name，定义 __eq__ 比较 name 相同即相等，比较两个 User", "code": "class User:\n    def __init__(self, name):\n        self.name = name\n    def __eq__(self, o):\n        return self.name == o.name\nprint(User(\"a\") == User(\"a\"))\nprint(User(\"a\") == User(\"b\"))", "expect": "True\nFalse", "hint": "__eq__ 比 name"}, {"type": "choice", "q": "类属性（class 体内直接赋值）的特点？", "options": ["每实例一份", "所有实例共享", "只能读", "必须私有"], "answer": 1, "explain": "类属性被所有实例共享。"}, {"type": "code", "q": "class Dog 有类属性 legs=4；创建两个实例打印 a.legs 和 b.legs", "code": "class Dog:\n    legs = 4\na = Dog()\nb = Dog()\nprint(a.legs, b.legs)", "expect": "4 4", "hint": "共享类属性"}, {"type": "choice", "q": "self.name = name 是？", "options": ["类属性", "实例属性", "全局变量", "局部变量"], "answer": 1, "explain": "self.xxx 是实例属性，每实例一份。"}, {"type": "code", "q": "class Book 有 title/price 和 __str__ 返回 \"title:price\"，打印 Book(\"Python\", 59)", "code": "class Book:\n    def __init__(self, title, price):\n        self.title = title\n        self.price = price\n    def __str__(self):\n        return self.title + \":\" + str(self.price)\nprint(Book(\"Python\", 59))", "expect": "Python:59", "hint": "__str__ 实现"}, {"type": "choice", "q": "什么时候该把一组数据收进类？", "options": ["永远不该", "它们总一起出现且有共同行为", "数据多就行", "类只用于游戏"], "answer": 1, "explain": "相关性 + 共同操作 = 类的信号。"}, {"type": "code", "q": "class Money 存 amount，定义 __eq__ 金额相等即相等。比较 Money(5) 与 Money(5.0)", "code": "class Money:\n    def __init__(self, amount):\n        self.amount = amount\n    def __eq__(self, o):\n        return self.amount == o.amount\nprint(Money(5) == Money(5.0))", "expect": "True", "hint": "数值相等"}], "exam": [{"type": "choice", "q": "__str__ 由谁触发？", "options": ["只 print 对象时", "str(对象)/print 对象时", "类型转换时", "永不"], "answer": 1, "explain": "print 和 str() 都会触发 __str__。"}, {"type": "code", "q": "class Card 有 suit 和 rank，__str__ 返回 \"rank of suit\"，打印 Card(\"♠\",\"A\")", "code": "class Card:\n    def __init__(self, suit, rank):\n        self.suit = suit\n        self.rank = rank\n    def __str__(self):\n        return self.rank + \" of \" + self.suit\nprint(Card(\"♠\", \"A\"))", "expect": "A of ♠", "hint": "rank of suit"}, {"type": "choice", "q": "两个内容相同但没定义 __eq__ 的对象 ==？", "options": ["True", "False（默认比地址）", "报错", "None"], "answer": 1, "explain": "默认 == 比较内存地址，内容相同也 False。"}, {"type": "code", "q": "class Player 有 name/score，定义 __eq__ name 和 score 都相同才相等。比较", "code": "class Player:\n    def __init__(self, name, score):\n        self.name = name\n        self.score = score\n    def __eq__(self, o):\n        return self.name == o.name and self.score == o.score\nprint(Player(\"A\", 10) == Player(\"A\", 10))\nprint(Player(\"A\", 10) == Player(\"B\", 10))", "expect": "True\nFalse", "hint": "双条件"}, {"type": "choice", "q": "想统计「创建了几个实例」用？", "options": ["实例属性", "类属性计数器", "全局函数", "魔法方法"], "answer": 1, "explain": "类属性在 __init__ 累加即可全实例共享计数。"}, {"type": "code", "q": "class Count 有类属性 n=0，__init__ 里 Count.n+=1。创建三个后打印 Count.n", "code": "class Count:\n    n = 0\n    def __init__(self):\n        Count.n += 1\na = Count()\nb = Count()\nc = Count()\nprint(Count.n)", "expect": "3", "hint": "类属性计数"}, {"type": "choice", "q": "数据类思维的核心？", "options": ["类越少越好", "把相关数据+操作打包成类", "用字典代替一切", "函数式"], "answer": 1, "explain": "用类表达领域概念，代码自我说明。"}, {"type": "code", "q": "class Person 有 name/age 和 __str__ 返回 \"name(age岁)\"，打印 Person(\"鼠哥\",18)", "code": "class Person:\n    def __init__(self, name, age):\n        self.name = name\n        self.age = age\n    def __str__(self):\n        return self.name + \"(\" + str(self.age) + \"岁)\"\nprint(Person(\"鼠哥\", 18))", "expect": "鼠哥(18岁)", "hint": "__str__"}, {"type": "choice", "q": "实例属性和类属性同名时，实例访问？", "options": ["类属性", "实例属性优先", "报错", "随机"], "answer": 1, "explain": "实例属性遮蔽类属性。"}, {"type": "code", "q": "class Vec 有 x,y，定义 __eq__ 比较坐标相等，还定义 __str__。比较并打印", "code": "class Vec:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\n    def __eq__(self, o):\n        return self.x == o.x and self.y == o.y\n    def __str__(self):\n        return \"<\" + str(self.x) + \",\" + str(self.y) + \">\"\nv1 = Vec(1, 2)\nv2 = Vec(1, 2)\nprint(v1 == v2)\nprint(v1)", "expect": "True\n<1,2>", "hint": "eq+str"}]}, {"id": 19, "no": "ⅩⅨ", "title": "文件读写", "weeks": "第 10 周", "diff": "★★★", "full": true, "story": {"tutor": "约翰·巴科斯（John Backus）", "era": "美国 · FORTRAN 之父", "fact": "巴科斯造 FORTRAN 的初衷是「把公式直接写下来让机器算」。文件是程序与硬盘之间的桥：程序重启后数据还在，靠的就是读写文件。掌握文件，程序才有「记忆」。", "quote": "「我把大半辈子花在了让自己和别程序员少干活的工具上。」"}, "map": ["open 读文件", "写文件", "with 语句", "逐行处理"], "sections": [{"t": "读文件：把硬盘内容请进来", "p": "open(path) 打开文件，read() 全读 / readlines() 逐行列表。用完 close()。", "code": "f = open('data.txt', encoding='utf-8')\ncontent = f.read()\nf.close()\nprint(content[:50])"}, {"t": "写文件：把内容存下去", "p": "open(path, \"w\") 覆盖写、\"a\" 追加写。写字符串或 writelines 列表。", "code": "f = open('out.txt', 'w', encoding='utf-8')\nf.write('第一行\\n')\nf.write('第二行\\n')\nf.close()"}, {"t": "with：自动关门", "p": "with open(...) as f: 代码块结束自动关闭文件，忘 close 也不会漏。", "code": "with open('out.txt', encoding='utf-8') as f:\n    for line in f:\n        print(line.strip())"}, {"t": "逐行处理大数据", "p": "for line in f 一次一行，不把整个文件读进内存——处理日志、超大文件的正道。", "code": "with open('out.txt', encoding='utf-8') as f:\n    n = 0\n    for line in f:\n        if 'error' in line.lower():\n            n += 1\n    print('error 行数:', n)"}], "quiz": [{"type": "choice", "q": "open(\"a.txt\", \"r\") 的 \"r\" 表示？", "options": ["写入", "只读", "追加", "删除"], "answer": 1, "explain": "r = read 只读，默认模式。"}, {"type": "choice", "q": "文件用完不 close() 的后果？", "options": ["没事", "资源泄漏，可能写不全", "文件变快", "报错必须关"], "answer": 1, "explain": "不关文件可能数据没写盘或占用句柄。"}, {"type": "choice", "q": "with open(f) as x 的好处？", "options": ["代码更短", "自动关闭文件", "防止读取", "替代变量"], "answer": 1, "explain": "with 块结束自动 close，最稳妥。"}, {"type": "choice", "q": "open(\"f.txt\", \"w\") 若 f.txt 已存在会？", "options": ["报错", "清空重写", "追加", "只读"], "answer": 1, "explain": "w 模式覆盖原内容。"}, {"type": "choice", "q": "要保留原内容往后加，用什么模式？", "options": ["\"r\"", "\"a\"", "\"w\"", "\"x\""], "answer": 1, "explain": "a = append 追加到末尾。"}, {"type": "choice", "q": "f.read() 返回？", "options": ["行列表", "整个文件字符串", "文件对象", "行数"], "answer": 1, "explain": "read() 一次读全部为一个大字符串。"}, {"type": "choice", "q": "f.readlines() 返回？", "options": ["字符串", "每行一个元素的列表", "行数", "None"], "answer": 1, "explain": "readlines() 按行切分返回列表。"}, {"type": "choice", "q": "for line in f 适合？", "options": ["小文件", "逐行处理大文件", "任何", "不能遍历"], "answer": 1, "explain": "迭代文件对象逐行读，省内存。"}, {"type": "choice", "q": "写文件用什么方法？", "options": ["f.read()", "f.write(内容)", "f.append()", "f.add()"], "answer": 1, "explain": "write 写入字符串内容。"}, {"type": "code", "q": "用 StringIO 模拟写文件：写 \"甲\\n乙\\n\" 后打印内容（判题环境无磁盘，用 io.StringIO）", "code": "import io\nf = io.StringIO()\nf.write('甲\\n')\nf.write('乙\\n')\nprint(f.getvalue().strip())", "expect": "甲\n乙", "hint": "StringIO 内存文件"}], "exam": [{"type": "choice", "q": "open 的默认编码问题在中文文件？", "options": ["没影响", "可能乱码，指定 encoding=\"utf-8\"", "只能 ascii", "必报错"], "answer": 1, "explain": "中文文件应显式 encoding=\"utf-8\"。"}, {"type": "choice", "q": "读文件三种方式 read/readline/readlines 区别？", "options": ["没区别", "全读/读一行/读所有行成列表", "read 最快", "只读一次"], "answer": 1, "explain": "粒度不同：整串/单行/行列表。"}, {"type": "code", "q": "用 io.StringIO 模拟：写入三行数字 1 2 3，读回并打印每行平方", "code": "import io\nf = io.StringIO()\nf.write('1\\n2\\n3\\n')\nf.seek(0)\nfor line in f:\n    n = int(line.strip())\n    print(n * n)", "expect": "1\n4\n9", "hint": "逐行转 int"}, {"type": "choice", "q": "\"w\" 与 \"a\" 的核心差别？", "options": ["w 更快", "w 覆盖 a 追加", "a 更快", "没差别"], "answer": 1, "explain": "w 重建文件，a 续写。"}, {"type": "choice", "q": "写日志文件用追加还是覆盖？", "options": ["覆盖", "追加（保留历史）", "都行", "随机"], "answer": 1, "explain": "日志要留历史，用 a 追加。"}, {"type": "code", "q": "用 io.StringIO 存三行名单，读回统计行数", "code": "import io\nf = io.StringIO('甲\\n乙\\n丙\\n')\nf.seek(0)\nn = 0\nfor _ in f:\n    n += 1\nprint(n)", "expect": "3", "hint": "数行"}, {"type": "choice", "q": "with open 中发生异常文件会？", "options": ["不关", "正常关闭（with 保证）", "损坏", "变空"], "answer": 1, "explain": "with 保证无论异常与否都关闭。"}, {"type": "code", "q": "读 StringIO 内容 \"a,b,c\"（一行），split(\",\") 后打印每项", "code": "import io\nf = io.StringIO('a,b,c')\nf.seek(0)\nfor item in f.read().split(','):\n    print(item)", "expect": "a\nb\nc", "hint": "split 逗号"}, {"type": "choice", "q": "处理文件时最该养成的习惯？", "options": ["永远用绝对路径", "用 with 管理文件", "复制再改", "不读文件"], "answer": 1, "explain": "with 自动管理资源是 Python 惯例。"}, {"type": "code", "q": "统计 StringIO 文本 \"hello\\nworld\\nhello\" 里 hello 出现次数（整个文本 count）", "code": "import io\nf = io.StringIO('hello\\nworld\\nhello')\nf.seek(0)\nprint(f.read().count('hello'))", "expect": "2", "hint": "str.count"}]}, {"id": 20, "no": "ⅩⅩ", "title": "JSON 持久化", "weeks": "第 10 周", "diff": "★★★", "full": true, "story": {"tutor": "道格拉斯·克罗克福德（Douglas Crockford）", "era": "美国 · JSON 之父", "fact": "克罗克福德 2001 年从 JavaScript 里抽出 JSON——一个「连人带机器都读得懂」的数据格式。现在它是互联网数据交换的普通话。程序存 JSON = 让数据活过程序的一生。", "quote": "「好设计是你能对新手解释清楚、又能让老手挑不出毛病。」"}, "map": ["json.dumps", "json.loads", "存到文件", "读回字典"], "sections": [{"t": "dumps：对象 → 字符串", "p": "json.dumps(字典) 把 Python 对象转成 JSON 字符串，中文要 ensure_ascii=False。", "code": "import json\ndata = {\"name\": \"鼠哥\", \"age\": 18}\ns = json.dumps(data, ensure_ascii=False)\nprint(s)"}, {"t": "loads：字符串 → 对象", "p": "json.loads(字符串) 把 JSON 字符串解析回 Python 字典/列表。", "code": "import json\ns = '{\"name\": \"鼠哥\", \"age\": 18}'\nd = json.loads(s)\nprint(d[\"name\"])"}, {"t": "写文件持久化", "p": "json.dump(data, f) 直接写文件；load 时 json.load(f)。", "code": "import json\nwith open('save.json', 'w', encoding='utf-8') as f:\n    json.dump({\"score\": 99}, f, ensure_ascii=False)"}, {"t": "程序重启不丢数据", "p": "启动时 load（文件不在就默认值），结束时 dump。这就是最简单的存档系统。", "code": "import json, os\nif os.path.exists('save.json'):\n    with open('save.json', encoding='utf-8') as f:\n        data = json.load(f)\nelse:\n    data = {'score': 0}\nprint(data['score'])"}], "quiz": [{"type": "choice", "q": "json.dumps 的作用？", "options": ["解析 JSON", "Python 对象转 JSON 字符串", "读文件", "删数据"], "answer": 1, "explain": "dumps = dump string，序列化。"}, {"type": "code", "q": "把 {\"a\": 1} 用 json.dumps 转字符串并打印", "code": "import json\nprint(json.dumps({\"a\": 1}))", "expect": "{\"a\": 1}", "hint": "dumps 序列化"}, {"type": "choice", "q": "json.loads 的作用？", "options": ["转 JSON", "JSON 字符串解析回 Python 对象", "写文件", "压缩"], "answer": 1, "explain": "loads 反序列化。"}, {"type": "code", "q": "解析 JSON 字符串 [1,2,3] 成列表并打印第 2 个元素", "code": "import json\nlst = json.loads(\"[1, 2, 3]\")\nprint(lst[1])", "expect": "2", "hint": "loads 后是列表"}, {"type": "choice", "q": "dumps 中文出现 \\uXXXX 怎么办？", "options": ["无解", "ensure_ascii=False", "换编码", "删中文"], "answer": 1, "explain": "ensure_ascii=False 让中文原样显示。"}, {"type": "code", "q": "{\"name\":\"小明\",\"age\":9} dumps 且 ensure_ascii=False 后打印", "code": "import json\nprint(json.dumps({\"name\": \"小明\", \"age\": 9}, ensure_ascii=False))", "expect": "{\"name\": \"小明\", \"age\": 9}", "hint": "ensure_ascii=False"}, {"type": "choice", "q": "把对象存文件用 json.dump 还是 dumps？", "options": ["dumps", "dump（写文件流）", "都可", "load"], "answer": 1, "explain": "dump(obj, file) 直接写文件；dumps 返回字符串。"}, {"type": "code", "q": "json.loads 解析 {\"ok\": true} 后打印 ok 的值", "code": "import json\nd = json.loads('{\"ok\": true}')\nprint(d[\"ok\"])", "expect": "True", "hint": "布尔原样"}, {"type": "choice", "q": "JSON 适合存什么？", "options": ["任意二进制", "嵌套的字典/列表数据", "程序代码", "图片"], "answer": 1, "explain": "JSON 表达结构化数据；图片等二进制不适合。"}, {"type": "code", "q": "dumps 一个列表 [\"猫\",\"狗\"] ensure_ascii=False 打印", "code": "import json\nprint(json.dumps([\"猫\", \"狗\"], ensure_ascii=False))", "expect": "[\"猫\", \"狗\"]", "hint": "列表序列化"}], "exam": [{"type": "choice", "q": "「序列化」意思是？", "options": ["加密", "对象变可存可传的字符串/字节", "删除对象", "复制对象"], "answer": 1, "explain": "序列化让对象能存盘或传输。"}, {"type": "code", "q": "json.dumps 数字列表 [1,2] 打印", "code": "import json\nprint(json.dumps([1, 2]))", "expect": "[1, 2]", "hint": "列表"}, {"type": "choice", "q": "loads 失败（格式错）会？", "options": ["返回 None", "抛 JSONDecodeError", "静默跳过", "返回空"], "answer": 1, "explain": "非法 JSON 会抛异常，应 try 包裹。"}, {"type": "code", "q": "解析 '{\"x\": {\"y\": 5}}' 打印嵌套 y", "code": "import json\nd = json.loads('{\"x\": {\"y\": 5}}')\nprint(d[\"x\"][\"y\"])", "expect": "5", "hint": "嵌套取"}, {"type": "choice", "q": "游戏存档用 JSON 的好处？", "options": ["读不懂", "人可读可改可调试", "体积最大", "运行更快"], "answer": 1, "explain": "JSON 文本可读，方便排障。"}, {"type": "code", "q": "把 {\"n\": 1, \"s\": \"甲\"} dumps ensure_ascii=False 打印", "code": "import json\nprint(json.dumps({\"n\": 1, \"s\": \"甲\"}, ensure_ascii=False))", "expect": "{\"n\": 1, \"s\": \"甲\"}", "hint": "混合类型"}, {"type": "choice", "q": "读取不存在的 JSON 文件（未捕获）会？", "options": ["返回空字典", "FileNotFoundError", "静默", "自动创建"], "answer": 1, "explain": "需先判断文件存在或 try 捕获。"}, {"type": "code", "q": "json.dumps 元组会变什么？", "code": "import json\nprint(json.dumps((1, 2)))", "expect": "[1, 2]", "hint": "元组序列化为数组"}, {"type": "choice", "q": "JSON 键值里的键必须是？", "options": ["数字", "字符串", "任意", "None"], "answer": 1, "explain": "JSON 键是双引号字符串。"}, {"type": "code", "q": "dumps {\"ok\": false} 打印", "code": "import json\nprint(json.dumps({\"ok\": False}))", "expect": "{\"ok\": false}", "hint": "False→false"}]}, {"id": 21, "no": "ⅩⅪ", "title": "异常处理", "weeks": "第 11 周", "diff": "★★★", "full": true, "story": {"tutor": "詹姆斯·高斯林（James Gosling）", "era": "加拿大 · Java 之父", "fact": "高斯林说异常处理是「把错误当一等公民」。程序不是不犯错，而是犯了错知道怎么爬起来。try-except 就是给程序配的安全网：用户乱输入、文件找不到，都不该让程序崩掉。", "quote": "「出错不是程序的尽头，是你对它的考验。」"}, "map": ["try-except", "else 与 finally", "捕获特定异常", "异常是流程"], "sections": [{"t": "try-except：兜住错误", "p": "可能出错的代码放 try，出错时执行 except 分支，程序不崩。", "code": "try:\n    n = int('abc')\nexcept ValueError:\n    print('不是数字')"}, {"t": "捕获特定异常", "p": "精确捕获 ValueError/ZeroDivisionError/FileNotFoundError 等，别一把抓。", "code": "try:\n    print(1 / 0)\nexcept ZeroDivisionError:\n    print('不能除零')"}, {"t": "else 与 finally", "p": "else：没出错才执行。finally：无论对错都执行（如关文件）。", "code": "try:\n    n = int('42')\nexcept ValueError:\n    print('错')\nelse:\n    print('成功', n)\nfinally:\n    print('结束')"}, {"t": "异常是流程的一部分", "p": "用异常处理「预期外的输入」，比到处 if 判断更干净。", "code": "while True:\n    try:\n        n = int(input('输入数字: '))\n        break\n    except ValueError:\n        print('重来')"}], "quiz": [{"type": "choice", "q": "try 块里的代码出错后？", "options": ["程序崩溃", "跳到 except 分支", "继续执行", "重试"], "answer": 1, "explain": "异常被 except 捕获，流程跳转。"}, {"type": "code", "q": "try 里 int(\"x\")，except ValueError 打印 \"不是数字\"", "code": "try:\n    n = int('x')\nexcept ValueError:\n    print('不是数字')", "expect": "不是数字", "hint": "捕获 ValueError"}, {"type": "choice", "q": "1/0 抛什么异常？", "options": ["ValueError", "ZeroDivisionError", "TypeError", "IndexError"], "answer": 1, "explain": "除零是 ZeroDivisionError。"}, {"type": "code", "q": "try 1/0 except ZeroDivisionError 打印 \"不能除零\"", "code": "try:\n    print(1 / 0)\nexcept ZeroDivisionError:\n    print('不能除零')", "expect": "不能除零", "hint": "捕获除零"}, {"type": "choice", "q": "else 块什么时候执行？", "options": ["出错时", "try 没出错时", "finally 后", "永远"], "answer": 1, "explain": "else 仅在 try 无异常时执行。"}, {"type": "code", "q": "try int(\"5\") except 打印 \"错\" else 打印 \"成功\"", "code": "try:\n    n = int('5')\nexcept ValueError:\n    print('错')\nelse:\n    print('成功')", "expect": "成功", "hint": "没出错走 else"}, {"type": "choice", "q": "finally 块保证？", "options": ["只在出错时", "无论对错都执行", "从不执行", "跳过 except"], "answer": 1, "explain": "finally 收尾必执行。"}, {"type": "code", "q": "try 1/0 except 打印后 finally 打印 \"收尾\"", "code": "try:\n    print(1 / 0)\nexcept ZeroDivisionError:\n    print('出错啦')\nfinally:\n    print('收尾')", "expect": "出错啦\n收尾", "hint": "except+finally"}, {"type": "choice", "q": "list[99] 越界抛？", "options": ["ValueError", "IndexError", "KeyError", "TypeError"], "answer": 1, "explain": "下标越界 IndexError。"}, {"type": "code", "q": "捕获 IndexError：访问空列表 [0] 打印 \"越界\"", "code": "try:\n    x = [][0]\nexcept IndexError:\n    print('越界')", "expect": "越界", "hint": "空列表下标"}], "exam": [{"type": "choice", "q": "dict[\"no\"] 键不存在抛？", "options": ["IndexError", "KeyError", "ValueError", "SyntaxError"], "answer": 1, "explain": "字典缺键 KeyError。"}, {"type": "code", "q": "捕获 KeyError：d={} 取 d[\"a\"] 打印 \"无键\"", "code": "d = {}\ntry:\n    x = d['a']\nexcept KeyError:\n    print('无键')", "expect": "无键", "hint": "KeyError"}, {"type": "choice", "q": "用户可能乱输入，最稳的读数字代码？", "options": ["int(input())", "try+int 捕 ValueError", "float(input())", "input() 自动转"], "answer": 1, "explain": "用 try 包住转换，捕获 ValueError 提示重输。"}, {"type": "code", "q": "int(\"12.3\") 抛 ValueError，捕获打印 \"不是整数\"", "code": "try:\n    n = int('12.3')\nexcept ValueError:\n    print('不是整数')", "expect": "不是整数", "hint": "小数转 int 报错"}, {"type": "choice", "q": "except Exception: 与 except ValueError: 区别？", "options": ["没区别", "前者捕获所有异常，后者只捕获 ValueError", "前者更精确", "都非法"], "answer": 1, "explain": "Exception 是万能兜底，ValueError 是精确靶向。"}, {"type": "code", "q": "同时处理除零：用户给 0 当除数，捕获并提示", "code": "try:\n    print(10 / 0)\nexcept ZeroDivisionError:\n    print('除数不能为 0')", "expect": "除数不能为 0", "hint": "除零提示"}, {"type": "choice", "q": "finally 常用于？", "options": ["打印日志", "资源清理（关文件等）", "返回结果", "递归"], "answer": 1, "explain": "finally 放清理逻辑最稳。"}, {"type": "code", "q": "try-else：int(\"7\") 成功则 else 打印 \"好\"", "code": "try:\n    n = int('7')\nexcept ValueError:\n    print('坏')\nelse:\n    print('好')", "expect": "好", "hint": "else 成功分支"}, {"type": "choice", "q": "一段代码可能抛多种异常，处理方式？", "options": ["一个 except 全收", "多个 except 分别捕获", "只能 try 一次", "不处理"], "answer": 1, "explain": "可写多个 except 分支分别处理。"}, {"type": "code", "q": "多层 except：分别处理 ValueError 和其他（打印 \"其它错误\"）", "code": "try:\n    x = int('a') + 1 / 0\nexcept ValueError:\n    print('值错误')\nexcept ZeroDivisionError:\n    print('除零错误')\nexcept Exception:\n    print('其它错误')", "expect": "值错误", "hint": "int 先抛 ValueError"}]}, {"id": 22, "no": "ⅩⅫ", "title": "测试入门", "weeks": "第 11 周", "diff": "★★★", "full": true, "story": {"tutor": "肯特·贝克（Kent Beck）", "era": "美国 · 极限编程之父", "fact": "贝克把「先写测试再写代码」变成流派。测试不是写完代码后的安慰，而是代码的「安全带」：你改了一行，测试立刻告诉你有没有撞坏别处。", "quote": "「代码没有测试，就像没系安全带的驾驶。」"}, "map": ["assert", "写小测试", "边界用例", "测试驱动思维"], "sections": [{"t": "assert：一句话断言", "p": "assert 条件，条件为 False 就抛 AssertionError。测试的基本砖块。", "code": "def add(a, b):\n    return a + b\nassert add(1, 2) == 3\nprint('通过')"}, {"t": "为函数写测试", "p": "把输入输出的预期写进 assert，一组 assert 就是一个小测试套件。", "code": "def mul(a, b):\n    return a * b\nassert mul(3, 4) == 12\nassert mul(0, 5) == 0\nprint('全过')"}, {"t": "边界用例", "p": "测边界：空、零、负数、最大值、恰好相等。bug 常在边界。", "code": "def sign(x):\n    if x > 0: return '正'\n    if x < 0: return '负'\n    return '零'\nassert sign(0) == '零'\nassert sign(-1) == '负'\nprint('边界 OK')"}, {"t": "改代码有底气", "p": "有了测试，重构不怕：跑一遍测试就知道有没有破坏行为。", "code": "def double(x):\n    return x * 2\ndef test():\n    assert double(0) == 0\n    assert double(-3) == -6\ntest()\nprint('重构安全')"}], "quiz": [{"type": "choice", "q": "assert 条件为假时？", "options": ["继续运行", "抛 AssertionError", "返回 False", "打印警告"], "answer": 1, "explain": "assert 假即抛错，测试失败。"}, {"type": "code", "q": "断言 add(2,3)==5（先定义 add 返回 a+b）后打印 \"通过\"", "code": "def add(a, b):\n    return a + b\nassert add(2, 3) == 5\nprint('通过')", "expect": "通过", "hint": "assert 真则继续"}, {"type": "choice", "q": "为什么要测边界？", "options": ["边界经常出 bug", "好看", "跑得快", "必须"], "answer": 0, "explain": "0、空、负数等边界是 bug 高发区。"}, {"type": "code", "q": "写函数 is_odd(n) 返回奇数与否，assert 验证 3 是奇数后打印", "code": "def is_odd(n):\n    return n % 2 != 0\nassert is_odd(3) is True\nprint('odd ok')", "expect": "odd ok", "hint": "n%2!=0"}, {"type": "choice", "q": "测试的价值主要在？", "options": ["让代码更长", "改代码时能发现破坏", "替代注释", "运行更快"], "answer": 1, "explain": "回归保护：改动不破旧功能。"}, {"type": "code", "q": "定义 absv(x) 返回绝对值，assert 测 0 和 -5", "code": "def absv(x):\n    return x if x >= 0 else -x\nassert absv(0) == 0\nassert absv(-5) == 5\nprint('abs ok')", "expect": "abs ok", "hint": "双断言"}, {"type": "choice", "q": "测试「恰好相等」属于？", "options": ["边界", "随机", "主路径", "装饰"], "answer": 1, "explain": "等值边界（>=、恰好 n）要单测。"}, {"type": "code", "q": "字符串函数 shout(s) 返回 s+\"!\"，assert 测空串", "code": "def shout(s):\n    return s + '!'\nassert shout('') == '!'\nassert shout('哈') == '哈!'\nprint('shout ok')", "expect": "shout ok", "hint": "边界空串"}, {"type": "choice", "q": "改了函数签名（参数变了）最该？", "options": ["直接部署", "先跑测试看哪里破", "删代码", "加注释"], "answer": 1, "explain": "测试暴露所有调用点是否仍兼容。"}, {"type": "code", "q": "max3(a,b,c) 返回最大，assert 测三个样例", "code": "def max3(a, b, c):\n    return max(a, b, c)\nassert max3(1, 2, 3) == 3\nassert max3(5, 1, 2) == 5\nassert max3(0, 0, -1) == 0\nprint('max3 ok')", "expect": "max3 ok", "hint": "三样例"}], "exam": [{"type": "choice", "q": "测试失败时 assert 抛的异常？", "options": ["ValueError", "AssertionError", "TypeError", "KeyError"], "answer": 1, "explain": "断言失败抛 AssertionError。"}, {"type": "code", "q": "验证 mul(2,5)==10（函数返回 a*b）后打印", "code": "def mul(a, b):\n    return a * b\nassert mul(2, 5) == 10\nprint('ok')", "expect": "ok", "hint": "基本断言"}, {"type": "choice", "q": "除以相关函数测 0 属于？", "options": ["主路径", "边界", "无关", "装饰"], "answer": 1, "explain": "0 是除法核心边界。"}, {"type": "code", "q": "is_even(n) 断言 0 是偶数、7 不是", "code": "def is_even(n):\n    return n % 2 == 0\nassert is_even(0) is True\nassert is_even(7) is False\nprint('even ok')", "expect": "even ok", "hint": "0 边界"}, {"type": "choice", "q": "「回归测试」指？", "options": ["第一次测", "确保新改动没破坏旧功能", "删旧测试", "性能测试"], "answer": 1, "explain": "回归 = 旧功能不被新代码破坏。"}, {"type": "code", "q": "clamp(x, lo, hi) 限制范围，断言边界值", "code": "def clamp(x, lo, hi):\n    if x < lo: return lo\n    if x > hi: return hi\n    return x\nassert clamp(0, 1, 5) == 1\nassert clamp(9, 1, 5) == 5\nassert clamp(3, 1, 5) == 3\nprint('clamp ok')", "expect": "clamp ok", "hint": "上下界"}, {"type": "choice", "q": "测试里的「期望值」来自？", "options": ["猜测", "手算/规格确定的结果", "运行一次", "用户"], "answer": 1, "explain": "期望值由规格或已知正确逻辑确定。"}, {"type": "code", "q": "字符串 upper 断言 \"py\".upper()==\"PY\"", "code": "assert 'py'.upper() == 'PY'\nprint('up ok')", "expect": "up ok", "hint": "内置方法测试"}, {"type": "choice", "q": "发现 bug 后正确的做法？", "options": ["改完就走", "先写复现该 bug 的测试再改", "删掉功能", "忽略"], "answer": 1, "explain": "先写失败测试复现，再修复让测试通过，防复发。"}, {"type": "code", "q": "sum2 场景：函数 add_all(*ns) 返回和，断言空调用为 0", "code": "def add_all(*ns):\n    return sum(ns)\nassert add_all() == 0\nassert add_all(1, 2, 3) == 6\nprint('sum ok')", "expect": "sum ok", "hint": "空参数边界"}]}, {"id": 23, "no": "ⅩⅩⅢ", "title": "代码整洁", "weeks": "第 12 周", "diff": "★★☆", "full": true, "story": {"tutor": "罗伯特·马丁（Robert Martin）", "era": "美国 · 清洁代码作者", "fact": "马丁写了《Clean Code》：好代码不靠注释解释「怎么」，而靠命名说明「为什么」。变量名是程序里出现最多的文字——起好名是最划算的投资。", "quote": "「你写的代码首先是给人读的，只是顺便给机器执行。」"}, "map": ["命名之道", "函数短小", "注释写为什么", "可读性重构"], "sections": [{"t": "命名：读起来像话", "p": "变量名说清楚「是什么」：total_price 好过 tp、x。布尔用 is/has 开头。", "code": "# 好命名\ntotal_price = 3 * 5\nis_paid = True\nprint(total_price, is_paid)"}, {"t": "函数短小：一函数一事", "p": "函数超过十几行就该拆。每个函数名是它的承诺：def calc_total(order)。", "code": "def line_total(qty, price):\n    return qty * price\ndef order_total(items):\n    return sum(line_total(q, p) for q, p in items)\nprint(order_total([(2, 3), (1, 5)]))"}, {"t": "注释写「为什么」", "p": "代码写「怎么」，注释补「为什么这样」。别注释废话（x = 1  # 设 x 为 1）。", "code": "TAX = 0.08  # 本地税率，政策调整时只需改这里\ndef after_tax(p):\n    return round(p * (1 + TAX), 2)\nprint(after_tax(100))"}, {"t": "丑代码重构", "p": "魔法数字、长函数、重复代码是三大臭味。闻到就拆。", "code": "def tax_price(p):\n    return round(p * 1.08, 2)  # 1.08 = 含税 8%\nprint(tax_price(50))"}], "quiz": [{"type": "choice", "q": "变量名哪个最好？", "options": ["x", "total_price", "tp", "t1"], "answer": 1, "explain": "total_price 自解释；x/tp 是猜谜。"}, {"type": "code", "q": "把重复计算收进函数：定义 area(w,h) 两次调用打印两个面积", "code": "def area(w, h):\n    return w * h\nprint(area(3, 4))\nprint(area(5, 6))", "expect": "12\n30", "hint": "函数复用"}, {"type": "choice", "q": "布尔变量命名习惯？", "options": ["flag1", "is_ok / has_key", "do", "num"], "answer": 1, "explain": "is/has 开头让 if 读起来自然。"}, {"type": "code", "q": "注释「为什么」场景：定义 RATE=0.1 表示折扣并注释用途，计算 200 折后", "code": "RATE = 0.1  # 学生折扣 10%\nprint(round(200 * (1 - RATE)))", "expect": "180", "hint": "200*0.9"}, {"type": "choice", "q": "魔法数字（代码里直接写 0.08）的问题？", "options": ["运行慢", "含义不明、改一处漏一处", "一定报错", "省内存"], "answer": 1, "explain": "应为命名常量集中管理。"}, {"type": "code", "q": "函数 greet(name, city) 返回问候，调用时用关键字参数让意图清楚", "code": "def greet(name, city):\n    return name + ' 在 ' + city\nprint(greet(name='鼠哥', city='西安'))", "expect": "鼠哥 在 西安", "hint": "关键字参数"}, {"type": "choice", "q": "好的函数长度？", "options": ["越长越完整", "短小单一职责", "随便", "必须 100 行"], "answer": 1, "explain": "短函数易读易测。"}, {"type": "code", "q": "把三个数平均的逻辑收进 avg3 并调用", "code": "def avg3(a, b, c):\n    return (a + b + c) / 3\nprint(avg3(3, 6, 9))", "expect": "6.0", "hint": "收进函数"}, {"type": "choice", "q": "哪条注释有价值？", "options": ["x=1 # x 等于 1", "# 改用索引加速：数据量大时全扫太慢", "# 开始", "# 结束"], "answer": 1, "explain": "解释为什么的注释有价值，复述代码的是噪音。"}, {"type": "code", "q": "重构：阶乘函数用递归/循环实现清晰版，打印 5!", "code": "def fact(n):\n    r = 1\n    for i in range(1, n + 1):\n        r *= i\n    return r\nprint(fact(5))", "expect": "120", "hint": "循环阶乘"}], "exam": [{"type": "choice", "q": "阅读代码时间 vs 编写时间？", "options": ["写得多", "读得多（好几倍）", "一样", "没统计"], "answer": 1, "explain": "代码读的频次远高于写，可读性最优先。"}, {"type": "code", "q": "定义常量 PI=3.14 并计算圆面积函数 area_c(r)", "code": "PI = 3.14\ndef area_c(r):\n    return PI * r * r\nprint(area_c(1))", "expect": "3.14", "hint": "常量+函数"}, {"type": "choice", "q": "代码三臭味不包括？", "options": ["重复", "魔法数字", "短函数", "长函数"], "answer": 2, "explain": "短函数是解药不是臭味。"}, {"type": "code", "q": "把 if 判断抽成函数 is_adult(age) 返回 age>=18，测试", "code": "def is_adult(age):\n    return age >= 18\nassert is_adult(18) is True\nassert is_adult(17) is False\nprint('ok')", "expect": "ok", "hint": "抽函数"}, {"type": "choice", "q": "两个函数做同样的事，应该？", "options": ["留着", "合一个", "看心情", "加注释"], "answer": 1, "explain": "重复代码合而为一，改一处全生效。"}, {"type": "code", "q": "把折扣逻辑参数化：discount(p, d) 返回打折价", "code": "def discount(p, d):\n    return round(p * (1 - d), 2)\nprint(discount(100, 0.2))", "expect": "80.0", "hint": "参数化"}, {"type": "choice", "q": "命名空格 total_price 与 totalPrice？", "options": ["没区别", "Python 惯例下划线", "驼峰更好", "都禁用"], "answer": 1, "explain": "Python 变量惯例 snake_case。"}, {"type": "code", "q": "把「判断闰年」抽函数 is_leap(y)：4 整除且(非100整除或400整除)", "code": "def is_leap(y):\n    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)\nassert is_leap(2024) is True\nassert is_leap(1900) is False\nassert is_leap(2000) is True\nprint('leap ok')", "expect": "leap ok", "hint": "闰年规则"}, {"type": "choice", "q": "给函数起名 best 还是 find_best？", "options": ["best 够", "find_best 表动作+对象", "都行", "find 就够"], "answer": 1, "explain": "动词开头命名函数（find/calc/build）更清楚。"}, {"type": "code", "q": "把连续 if 改清晰函数 grade(score)：>=90 A >=75 B >=60 C 否则 D", "code": "def grade(s):\n    if s >= 90: return 'A'\n    if s >= 75: return 'B'\n    if s >= 60: return 'C'\n    return 'D'\nassert grade(95) == 'A'\nassert grade(76) == 'B'\nassert grade(59) == 'D'\nprint('grade ok')", "expect": "grade ok", "hint": "阶梯条件"}]}, {"id": 24, "no": "ⅩⅩⅣ", "title": "项目：猜数字·强化版", "weeks": "第 13 周", "diff": "★★★", "full": true, "story": {"tutor": "威廉·肖克利（William Shockley）", "era": "美国 · 晶体管共同发明人", "fact": "肖克利带队发明晶体管，一辈子痴迷「预测与验证」。猜数字就是最纯粹的预测游戏：你的判断依据是每次反馈，好的玩家会二分，差的玩家瞎蒙。程序也一样，根据反馈修正。", "quote": "「测量是科学的第一步，也是写程序的第一步。」"}, "map": ["游戏流程", "random 目标", "循环+提示", "计分与重玩"], "sections": [{"t": "定规则", "p": "程序随机想一个 1-100 的数，玩家猜，程序回「大了/小了/对了」，限定 7 次（二分上界）。", "code": "import random\nn = random.randint(1, 100)\nprint('我想到一个 1-100 的数')\nfor i in range(7):\n    g = int(input('猜: '))\n    if g == n:\n        print('对了!')\n        break\n    print('大了' if g > n else '小了')"}, {"t": "防乱输入", "p": "玩家输入非数字会崩，用 try 包裹输入。", "code": "try:\n    g = int(input('猜: '))\nexcept ValueError:\n    print('要输数字')\n    continue"}, {"t": "计分", "p": "按剩余次数计分：剩几次得几分，7 次没用完猜中得高分。", "code": "score = 7 - i\nprint('得分', score)"}, {"t": "重玩", "p": "外层 while True 包整局，输入 y/n 决定是否再来。"}], "quiz": [{"type": "choice", "q": "猜 1-100 的数，最优策略是？", "options": ["从 1 递增", "二分（每次猜中间）", "随机", "从 100 递减"], "answer": 1, "explain": "二分每次排除一半，最多 7 次。"}, {"type": "code", "q": "用 random.randint 生成 1-100 目标数并打印（随机题跑通即过）", "code": "import random\nprint(random.randint(1, 100))", "expect": "", "hint": "随机题"}, {"type": "choice", "q": "玩家输入非数字会抛？", "options": ["IndexError", "ValueError", "KeyError", "Zero"], "answer": 1, "explain": "int(\"abc\") 抛 ValueError。"}, {"type": "code", "q": "模拟判大小：n=50, g=80 打印 \"大了\"", "code": "n = 50\ng = 80\nprint(\"大了\" if g > n else \"小了\")", "expect": "大了", "hint": "三元比较"}, {"type": "choice", "q": "7 次够猜 1-100 是因为？", "options": ["运气好", "2^7=128>100", "7 很大", "蒙得快"], "answer": 1, "explain": "二分 7 次覆盖 128 个值，足够 100。"}, {"type": "code", "q": "for i in range(7) 循环打印 i（0 到 6）", "code": "for i in range(7):\n    print(i)", "expect": "0\n1\n2\n3\n4\n5\n6", "hint": "range(7)"}, {"type": "choice", "q": "猜中后要立刻结束循环用？", "options": ["pass", "break", "continue", "return"], "answer": 1, "explain": "break 跳出当前循环。"}, {"type": "code", "q": "模拟计分：7 次内第 3 次猜中，得分 = 7-3 打印", "code": "i = 2  # 第 3 次，下标 2\nscore = 7 - i\nprint(score)", "expect": "5", "hint": "7-2"}, {"type": "choice", "q": "重玩用哪种结构包整局？", "options": ["if", "while True + 退出条件", "for 固定", "try"], "answer": 1, "explain": "外层循环 + 内部 break 实现可重玩。"}, {"type": "code", "q": "读输入并比较：模拟 g=50,n=50 输出 \"对了!\"（不真调 input）", "code": "g = 50\nn = 50\nif g == n:\n    print(\"对了!\")", "expect": "对了!", "hint": "相等判断"}], "exam": [{"type": "choice", "q": "猜数字里「大了/小了」反馈属于？", "options": ["装饰", "给玩家的信息，指导下一猜", "错误", "随机"], "answer": 1, "explain": "反馈驱动策略调整。"}, {"type": "code", "q": "range(1, 4) 打印", "code": "for i in range(1, 4):\n    print(i)", "expect": "1\n2\n3", "hint": "1..3"}, {"type": "choice", "q": "把猜数整局包进 while True 的问题是？", "options": ["没退出会死循环", "更快", "更省代码", "没法 break"], "answer": 0, "explain": "必须提供退出路径否则无限循环。"}, {"type": "code", "q": "判断 64 与目标 50：打印 \"大了\"（64>50）", "code": "print(\"大了\" if 64 > 50 else \"小了\")", "expect": "大了", "hint": "64 大"}, {"type": "choice", "q": "score 想从 100 起步每错一次扣 10，猜错时？", "options": ["score += 10", "score -= 10", "score = 0", "score = 10"], "answer": 1, "explain": "扣分用减法。"}, {"type": "code", "q": "for 循环里 break：找到 5 的倍数就停，打印 1..9 中第一个 5 倍数", "code": "for i in range(1, 10):\n    if i % 5 == 0:\n        print(i)\n        break", "expect": "5", "hint": "break 后停"}, {"type": "choice", "q": "真实 input() 返回类型？", "options": ["int", "字符串", "float", "列表"], "answer": 1, "explain": "input 永远返回字符串，要转 int。"}, {"type": "code", "q": "把字符串 \"42\" 转 int 并打印类型名", "code": "n = int(\"42\")\nprint(type(n).__name__)", "expect": "int", "hint": "int() 转换"}, {"type": "choice", "q": "限 7 次没猜中应？", "options": ["继续无限", "提示失败并公布答案", "报错", "忽略"], "answer": 1, "explain": "次数用尽公布答案，结束本局。"}, {"type": "code", "q": "公布答案场景：n=66 打印 \"答案是 66\"", "code": "n = 66\nprint(\"答案是\", n)", "expect": "答案是 66", "hint": "拼接打印"}]}, {"id": 25, "no": "ⅩⅩⅤ", "title": "项目：词频统计器", "weeks": "第 13 周", "diff": "★★★", "full": true, "story": {"tutor": "汉斯·彼得·卢恩（Hans Peter Luhn）", "era": "德国 · 信息检索先驱", "fact": "卢恩 1958 年发明了「自动摘要」：统计词频，高频词构成文章主题。词频统计器是自然语言处理的入门钥匙——也是字典、字符串、排序三件套的综合练习。", "quote": "「信息不值钱，值得关注的信息才值钱。」"}, "map": ["清洗文本", "切词", "计数字典", "按频排序"], "sections": [{"t": "清洗文本", "p": "去掉标点、统一小写，才能准确统计。", "code": "text = 'Hello, hello! World.'\ntext = text.lower().replace(',', ' ').replace('!', ' ').replace('.', ' ')\nprint(text)"}, {"t": "切词", "p": "按空格 split 成单词列表。", "code": "words = text.split()\nprint(words)"}, {"t": "计数字典", "p": "遍历词，字典累加：词是键，次数是值。", "code": "count = {}\nfor w in words:\n    count[w] = count.get(w, 0) + 1\nprint(count)"}, {"t": "按频排序", "p": "items() 取键值对，按值排序取 Top。", "code": "top = sorted(count.items(), key=lambda x: x[1], reverse=True)\nprint(top[:3])"}], "quiz": [{"type": "choice", "q": "统计词频前为何要转小写？", "options": ["省空间", "Hello 与 hello 应算同一个词", "美观", "必须"], "answer": 1, "explain": "归一化大小写避免重复计。"}, {"type": "code", "q": "清洗 \"Hi, Bob!\"：lower 并替换逗号感叹号为空格后打印", "code": "text = 'Hi, Bob!'\ntext = text.lower().replace(',', ' ').replace('!', ' ')\nprint(text)", "expect": "hi  bob ", "hint": "替换标点"}, {"type": "choice", "q": "dict.get(w, 0) + 1 的含义？", "options": ["报错", "取当前次数，没有则 0，加 1 累计", "固定 1", "删除键"], "answer": 1, "explain": "get 带默认值防 KeyError，经典计数法。"}, {"type": "code", "q": "用 get 计数：统计列表 a b a 各出现次数打印", "code": "cnt = {}\nfor w in ['a', 'b', 'a']:\n    cnt[w] = cnt.get(w, 0) + 1\nprint(cnt)", "expect": "{'a': 2, 'b': 1}", "hint": "get 计数"}, {"type": "choice", "q": "按出现次数从高到低排序？", "options": ["sorted 按值 reverse=True", "按 key 排序", "随机", "不排"], "answer": 0, "explain": "lambda 取值，reverse 降序。"}, {"type": "code", "q": "items() 用法：d={\"a\":2} 打印键值对", "code": "d = {\"a\": 2}\nprint(list(d.items()))", "expect": "[('a', 2)]", "hint": "items 键值"}, {"type": "choice", "q": "文本清洗还要去掉什么？", "options": ["空格", "标点和数字等噪声", "换行", "所有"], "answer": 1, "explain": "按需去掉标点/数字/停用词提升统计质量。"}, {"type": "code", "q": "统计一句话中 \"的\" 出现次数（用 count 方法）", "code": "s = \"我们的你们的\"\nprint(s.count(\"的\"))", "expect": "2", "hint": "str.count"}, {"type": "choice", "q": "词频 Top N 用什么排序结果？", "options": ["降序取前 N", "升序", "全部", "随机"], "answer": 0, "explain": "高频在前取前 N 即 TopN。"}, {"type": "code", "q": "sorted 按值降序：{\"b\":1,\"a\":3} 打印第一个词的键", "code": "d = {\"b\": 1, \"a\": 3}\ntop = sorted(d.items(), key=lambda x: x[1], reverse=True)\nprint(top[0][0])", "expect": "a", "hint": "最高频词"}], "exam": [{"type": "choice", "q": "词频统计的三件套是？", "options": ["循环+字典+排序", "类+继承", "异常+文件", "绘图"], "answer": 0, "explain": "清洗、计数（字典）、排序构成统计器。"}, {"type": "code", "q": "str.lower() 对 \"PyThon\" 的结果", "code": "print(\"PyThon\".lower())", "expect": "python", "hint": "统一小写"}, {"type": "choice", "q": "text.split() 默认按什么切？", "options": ["逗号", "空白", "句号", "每字符"], "answer": 1, "explain": "split() 默认按任意空白切。"}, {"type": "code", "q": "\"one two two\".split() 后打印列表", "code": "print(\"one two two\".split())", "expect": "['one', 'two', 'two']", "hint": "按空白切词"}, {"type": "choice", "q": "Counter 计数器在哪个模块？", "options": ["math", "collections", "random", "json"], "answer": 1, "explain": "collections.Counter 专门计数。"}, {"type": "code", "q": "用 Counter 统计 [\"a\",\"b\",\"a\"] 打印 most_common(1)", "code": "from collections import Counter\nc = Counter([\"a\", \"b\", \"a\"])\nprint(c.most_common(1))", "expect": "[('a', 2)]", "hint": "Counter 一行计数"}, {"type": "choice", "q": "lambda x: x[1] 在排序中取？", "options": ["键", "值（第 2 个元素）", "长度", "索引"], "answer": 1, "explain": "x 是 (键,值) 对，x[1] 取值。"}, {"type": "code", "q": "sorted 按长度排：[\"aa\",\"b\",\"ccc\"] 默认排序打印", "code": "print(sorted([\"aa\", \"b\", \"ccc\"], key=len))", "expect": "['b', 'aa', 'ccc']", "hint": "key=len"}, {"type": "choice", "q": "「停用词」指？", "options": ["生僻词", "的/了/是 等高频无意义词", "错词", "长词"], "answer": 1, "explain": "停用词干扰主题提取，常被过滤。"}, {"type": "code", "q": "过滤停用词：[\"的\",\"猫\",\"了\"] 去掉 \"的\"\"了\" 打印剩余", "code": "stop = {\"的\", \"了\"}\nwords = [\"的\", \"猫\", \"了\"]\nout = [w for w in words if w not in stop]\nprint(out)", "expect": "['猫']", "hint": "列表推导过滤"}]}, {"id": 26, "no": "ⅩⅩⅥ", "title": "项目：JSON 记账本 CLI", "weeks": "第 14 周", "diff": "★★★", "full": true, "story": {"tutor": "亚当·斯密（Adam Smith）", "era": "苏格兰 · 经济学之父", "fact": "斯密在《国富论》里说记账是「商业的理性」。记账本程序 = 数据结构（记录列表）+ 持久化（JSON 文件）+ 交互循环（菜单）。做完它，你就有了一个能天天用的真程序。", "quote": "「每一笔糊涂账背后，都藏着一个清晰的决策。」"}, "map": ["数据模型", "菜单循环", "增删查", "JSON 存档"], "sections": [{"t": "记录结构", "p": "一条账 = 日期 + 金额 + 类别 + 备注，用字典表达。", "code": "record = {'date': '09-01', 'amount': 35, 'cat': '餐饮', 'note': '午饭'}\nprint(record)"}, {"t": "存储：列表装记录", "p": "账本是字典的列表，每加一笔 append。", "code": "books = []\nbooks.append({'date': '09-01', 'amount': 35})\nbooks.append({'date': '09-02', 'amount': 12})\nprint(len(books))"}, {"t": "汇总", "p": "遍历求和金额 = 总支出。", "code": "total = sum(b['amount'] for b in books)\nprint('总支出', total)"}, {"t": "持久化", "p": "load 时 json 读，改动后 dump 写，数据活过程序。", "code": "import json\nbooks = []\n# 简化：直接演示 dump 到字符串\ns = json.dumps(books)\nprint(s)"}], "quiz": [{"type": "choice", "q": "一条记账记录用什么表示最合适？", "options": ["字符串", "字典（字段名+值）", "数字", "元组"], "answer": 1, "explain": "字典带字段名，语义清晰。"}, {"type": "code", "q": "建一条记录 {\"date\":\"09-05\",\"amount\":20} 打印 amount", "code": "r = {\"date\": \"09-05\", \"amount\": 20}\nprint(r[\"amount\"])", "expect": "20", "hint": "取字段"}, {"type": "choice", "q": "总支出 = 所有记录的什么运算？", "options": ["平均", "求和", "最大", "计数"], "answer": 1, "explain": "sum 各 amount。"}, {"type": "code", "q": "列表 books 两条金额 10/20，求总支出打印", "code": "books = [{\"amount\": 10}, {\"amount\": 20}]\nprint(sum(b[\"amount\"] for b in books))", "expect": "30", "hint": "生成器求和"}, {"type": "choice", "q": "菜单式程序的核心循环结构？", "options": ["for 固定", "while True + 退出选项", "if 一次", "递归"], "answer": 1, "explain": "while True 循环显示菜单，选退出 break。"}, {"type": "code", "q": "模拟菜单：choice=3 退出（打印 \"退出\"），否则打印选项", "code": "choice = 3\nif choice == 3:\n    print(\"退出\")", "expect": "退出", "hint": "条件退出"}, {"type": "choice", "q": "退出菜单用 input 比较，用户输入 \"3\" 是？", "options": ["int", "字符串 \"3\"", "报错", "None"], "answer": 1, "explain": "input 返回字符串，比较前转 int 或比字符串。"}, {"type": "code", "q": "输入 \"3\" 转 int 后与 3 比较打印 \"相等\"", "code": "s = \"3\"\nif int(s) == 3:\n    print(\"相等\")", "expect": "相等", "hint": "int(s)"}, {"type": "choice", "q": "记账数据想程序重启还在，要？", "options": ["变量存", "存文件（JSON）", "打印出来", "复制"], "answer": 1, "explain": "持久化到文件才能跨运行。"}, {"type": "code", "q": "books 列表空时先判断再输出 \"暂无记录\"", "code": "books = []\nif not books:\n    print(\"暂无记录\")", "expect": "暂无记录", "hint": "空列表 falsy"}], "exam": [{"type": "choice", "q": "命令行菜单「添加/查看/汇总/退出」属于？", "options": ["GUI", "CLI（命令行交互）", "网页", "游戏"], "answer": 1, "explain": "文本菜单 = 命令行界面 CLI。"}, {"type": "code", "q": "一条账含 date/amount，遍历打印所有 amount", "code": "books = [{\"date\": \"a\", \"amount\": 5}, {\"date\": \"b\", \"amount\": 7}]\nfor b in books:\n    print(b[\"amount\"])", "expect": "5\n7", "hint": "遍历取值"}, {"type": "choice", "q": "按类别统计（餐饮/交通）用？", "options": ["计数 if", "字典按类别累加", "排序", "随机"], "answer": 1, "explain": "cat 做键，金额累加进字典。"}, {"type": "code", "q": "按 cat 汇总：两条餐饮/一条交通，打印餐饮总额", "code": "records = [{\"cat\": \"餐饮\", \"amount\": 10}, {\"cat\": \"交通\", \"amount\": 5}, {\"cat\": \"餐饮\", \"amount\": 8}]\ntotal = sum(r[\"amount\"] for r in records if r[\"cat\"] == \"餐饮\")\nprint(total)", "expect": "18", "hint": "条件求和"}, {"type": "choice", "q": "追加记录到列表用？", "options": ["books += ", "books.append(r)", "books.add(r)", "books.push(r)"], "answer": 1, "explain": "append 在尾部加元素。"}, {"type": "code", "q": "books.append 两条后打印数量 len", "code": "books = []\nbooks.append(1)\nbooks.append(2)\nprint(len(books))", "expect": "2", "hint": "append 后 len"}, {"type": "choice", "q": "命令行里防止用户乱选菜单项？", "options": ["不管", "校验输入范围并提示", "崩溃", "跳过"], "answer": 1, "explain": "校验 + 提示重输更友好。"}, {"type": "code", "q": "模拟校验：choice=9 超出 1-3 打印 \"无效选项\"", "code": "choice = 9\nif choice < 1 or choice > 3:\n    print(\"无效选项\")", "expect": "无效选项", "hint": "范围判断"}, {"type": "choice", "q": "JSON 存账本相比 csv 优势？", "options": ["更小", "嵌套结构自然、可直接对象", "更快", "必选"], "answer": 1, "explain": "账本结构嵌套，JSON 天然表达。"}, {"type": "code", "q": "把 [{\"a\":1}] dump 成 JSON 字符串打印", "code": "import json\nprint(json.dumps([{\"a\": 1}]))", "expect": "[{\"a\": 1}]", "hint": "列表序列化"}]}, {"id": 27, "no": "ⅩⅩⅦ", "title": "项目：学生信息管理系统", "weeks": "第 14 周", "diff": "★★★", "full": true, "story": {"tutor": "查尔斯·巴贝奇（Charles Babbage）", "era": "英国 · 计算机之父", "fact": "巴贝奇差分机想给「表格计算」自动化——人类最早想让机器管的表，就是这种结构化的行数据。学生管理系统是类 + 列表 + 文件 + 菜单循环的综合体，也是 CRUD 的入门。", "quote": "「错误的数据比没有数据更危险。」"}, "map": ["学生类", "增删查改", "显示表格", "持久化"], "sections": [{"t": "学生类", "p": "Student 类存 name/age/score，带 __str__ 方便显示。", "code": "class Student:\n    def __init__(self, name, age, score):\n        self.name = name\n        self.age = age\n        self.score = score\n    def __str__(self):\n        return self.name + ' ' + str(self.score)"}, {"t": "增：append 到列表", "p": "管理系统 = 学生对象列表 + 各种操作函数。", "code": "students = []\nstudents.append(Student('甲', 18, 90))\nstudents.append(Student('乙', 19, 85))"}, {"t": "查/改/删", "p": "按名字找到下标：遍历比对 name，然后打印/修改/删除。", "code": "for i, s in enumerate(students):\n    if s.name == '甲':\n        students[i].score = 95\nfor s in students:\n    print(s)"}, {"t": "统计", "p": "平均分、最高分、及格率都是遍历一次的事。", "code": "scores = [s.score for s in students]\nprint('平均', sum(scores)/len(scores))\nprint('最高', max(scores))"}], "quiz": [{"type": "choice", "q": "管理 N 个学生用什么容器？", "options": ["单个变量", "列表装对象", "字符串", "字典一个"], "answer": 1, "explain": "对象列表是核心数据模型。"}, {"type": "code", "q": "class Student 存 name，创建 s=Student(\"甲\") 打印 s.name", "code": "class Student:\n    def __init__(self, name):\n        self.name = name\ns = Student(\"甲\")\nprint(s.name)", "expect": "甲", "hint": "实例属性"}, {"type": "choice", "q": "CRUD 四个操作是？", "options": ["增删查改", "读写算打", "复制移动", "开存关"], "answer": 0, "explain": "Create/Read/Update/Delete。"}, {"type": "code", "q": "students 两个对象（score 90/80），打印平均分", "code": "students = [type(\"S\", (), {\"score\": 90})(), type(\"S\", (), {\"score\": 80})()]\nprint(sum(s.score for s in students) / 2)", "expect": "85.0", "hint": "求和平均"}, {"type": "choice", "q": "按名字查找要遍历比对什么？", "options": ["对象本身", "s.name == 目标", "索引", "分数"], "answer": 1, "explain": "遍历比较 name 属性。"}, {"type": "code", "q": "找名为 \"乙\" 的学生并打印其 score", "code": "class St:\n    def __init__(self, n, sc):\n        self.name = n; self.score = sc\nsts = [St(\"甲\", 90), St(\"乙\", 85)]\nfor s in sts:\n    if s.name == \"乙\":\n        print(s.score)", "expect": "85", "hint": "遍历查名"}, {"type": "choice", "q": "删除指定学生（知道下标）用？", "options": ["del students[i]", "remove 名", "pop by 名", "clear"], "answer": 0, "explain": "del 按下标删除。"}, {"type": "code", "q": "列表删除：students=[\"甲\",\"乙\"] 删下标 0 打印", "code": "students = [\"甲\", \"乙\"]\ndel students[0]\nprint(students)", "expect": "['乙']", "hint": "del 下标"}, {"type": "choice", "q": "显示整齐表格用什么？", "options": ["print 拼", "f-string 对齐/格式化", "类", "循环"], "answer": 1, "explain": "格式化字符串排成表格观感。"}, {"type": "code", "q": "f-string 打印 \"甲 90\"（name=甲 score=90）", "code": "name = \"甲\"\nscore = 90\nprint(f\"{name} {score}\")", "expect": "甲 90", "hint": "f-string 变量"}], "exam": [{"type": "choice", "q": "「封装学生数据+方法」用？", "options": ["字典就行", "类", "两个变量", "列表"], "answer": 1, "explain": "类把字段与方法绑定，系统好扩展。"}, {"type": "code", "q": "class Student __str__ 返回 name，print 对象打印名字", "code": "class Student:\n    def __init__(self, name):\n        self.name = name\n    def __str__(self):\n        return self.name\nprint(Student(\"小明\"))", "expect": "小明", "hint": "__str__"}, {"type": "choice", "q": "算及格率需要遍历做什么？", "options": ["数 >=60 的个数", "求和", "找最大", "排序"], "answer": 1, "explain": "统计达标人数 / 总数。"}, {"type": "code", "q": "学生分数 [90, 50, 70]，打印及格（>=60）人数", "code": "scores = [90, 50, 70]\nprint(sum(1 for x in scores if x >= 60))", "expect": "2", "hint": "条件计数"}, {"type": "choice", "q": "把学生列表存 JSON 需要？", "options": ["直接 dump 对象", "先转字典/可序列化结构", "不能存", "只能存名字"], "answer": 1, "explain": "json 需可序列化数据，对象先转字典。"}, {"type": "code", "q": "Student 对象转字典存 name/score 并 dumps", "code": "class St:\n    def __init__(self, n, sc):\n        self.name = n; self.score = sc\nimport json\ns = St(\"甲\", 90)\nprint(json.dumps({\"name\": s.name, \"score\": s.score}, ensure_ascii=False))", "expect": "{\"name\": \"甲\", \"score\": 90}", "hint": "手动转字典"}, {"type": "choice", "q": "修改某学生成绩的正确路径？", "options": ["改对象属性", "改列表长度", "重建列表", "改名"], "answer": 0, "explain": "定位对象后改属性（students[i].score=...）。"}, {"type": "code", "q": "把第一个学生分数改成 100 并打印", "code": "class St:\n    def __init__(self, n, sc):\n        self.name = n; self.score = sc\nsts = [St(\"甲\", 80)]\nsts[0].score = 100\nprint(sts[0].score)", "expect": "100", "hint": "对象属性改"}, {"type": "choice", "q": "菜单系统每次操作后最好？", "options": ["退出", "保存数据", "清屏", "删记录"], "answer": 1, "explain": "操作后落盘防丢失。"}, {"type": "code", "q": "保存前判断数据变了？简化：直接打印 \"已保存\" 当列表非空", "code": "students = [1]\nif students:\n    print(\"已保存\")", "expect": "已保存", "hint": "非空判断"}]}, {"id": 28, "no": "ⅩⅩⅧ", "title": "项目：搜索与排序工具箱", "weeks": "第 15 周", "diff": "★★★", "full": true, "story": {"tutor": "唐纳德·克努特（Donald Knuth）", "era": "美国 · 算法大师", "fact": "克努特写《计算机程序设计艺术》时说：排序和搜索是算法世界的「hello world」。排序让无序变有序，二分让查找从线性变对数——一万个名字，顺序找要一万步，二分只要 14 步。", "quote": "「过早优化是万恶之源，但用对算法是万福之源。」"}, "map": ["排序意义", "内置 sort", "二分搜索", "复杂度直觉"], "sections": [{"t": "为什么要排序", "p": "有序数据才有二分、才能方便地展示 Top。", "code": "nums = [5, 2, 8, 1]\nnums.sort()\nprint(nums)"}, {"t": "内置 sort 与 sorted", "p": "list.sort() 就地排；sorted(seq) 返回新列表。可 key= 定制规则。", "code": "words = ['banana', 'apple', 'cherry']\nprint(sorted(words))\nprint(sorted(words, key=len))"}, {"t": "二分搜索", "p": "有序列表里找目标：每次取中间比较，砍半。bisect 模块现成。", "code": "import bisect\nnums = [1, 3, 5, 7, 9]\nprint(bisect.bisect_left(nums, 5))"}, {"t": "复杂度直觉", "p": "线性 O(n) 随数据线性涨；二分 O(log n) 几乎不涨。数据大时算法差别天壤。", "code": "import math\nfor n in [10, 1000, 10**6]:\n    print(n, '线性', n, '二分步数', int(math.log2(n))+1)"}], "quiz": [{"type": "choice", "q": "list.sort() 与 sorted() 区别？", "options": ["没区别", "sort 就地改，sorted 返回新列表", "sorted 更快", "sort 只能数字"], "answer": 1, "explain": "一个改原列表，一个生成新列表。"}, {"type": "code", "q": "sorted([3,1,2]) 打印", "code": "print(sorted([3, 1, 2]))", "expect": "[1, 2, 3]", "hint": "升序新列表"}, {"type": "choice", "q": "降序排序加什么参数？", "options": ["desc=True", "reverse=True", "down=True", "order=1"], "answer": 1, "explain": "reverse=True 降序。"}, {"type": "code", "q": "按长度排序 [\"aa\",\"b\",\"ccc\"] 打印", "code": "print(sorted([\"aa\", \"b\", \"ccc\"], key=len))", "expect": "['b', 'aa', 'ccc']", "hint": "key=len"}, {"type": "choice", "q": "二分查找的前提？", "options": ["随机顺序", "数据已排序", "数据少", "数据多"], "answer": 1, "explain": "二分必须基于有序序列。"}, {"type": "code", "q": "bisect_left 在 [1,3,5] 找 3 的位置", "code": "import bisect\nprint(bisect.bisect_left([1, 3, 5], 3))", "expect": "1", "hint": "索引 1"}, {"type": "choice", "q": "1000 个元素线性 vs 二分？", "options": ["一样", "线性 1000 步，二分约 10 步", "二分 1000", "线性更快"], "answer": 1, "explain": "log2(1000)≈10，天壤之别。"}, {"type": "code", "q": "打印 log2(1024) 的整数（math.log2 后 int）", "code": "import math\nprint(int(math.log2(1024)))", "expect": "10", "hint": "2^10"}, {"type": "choice", "q": "Python 里找最大值内置函数？", "options": ["max()", "maximum()", "largest()", "big()"], "answer": 0, "explain": "max/min/sum 都是内置。"}, {"type": "code", "q": "max([4, 9, 2]) 打印", "code": "print(max([4, 9, 2]))", "expect": "9", "hint": "内置 max"}], "exam": [{"type": "choice", "q": "「有序」对哪些操作有决定性帮助？", "options": ["求和", "查找/二分", "打印", "赋值"], "answer": 1, "explain": "有序让查找可以用二分。"}, {"type": "code", "q": "[3,1,2].sort() 就地排序后打印列表", "code": "a = [3, 1, 2]\na.sort()\nprint(a)", "expect": "[1, 2, 3]", "hint": "就地 sort"}, {"type": "choice", "q": "sorted 默认升序，最大元素在？", "options": ["开头", "末尾", "中间", "随机"], "answer": 1, "explain": "升序末尾是最大。"}, {"type": "code", "q": "sorted([\"a\",\"B\",\"c\"]) 默认排序打印（大写在前）", "code": "print(sorted([\"a\", \"B\", \"c\"]))", "expect": "['B', 'a', 'c']", "hint": "ASCII 大写前"}, {"type": "choice", "q": "bisect 模块全名用途？", "options": ["排序", "有序列表插入与二分查找", "随机", "加密"], "answer": 1, "explain": "bisect 专做有序序列操作。"}, {"type": "code", "q": "bisect.insort 插入保持有序：往 [1,4] 插 3 打印", "code": "import bisect\na = [1, 4]\nbisect.insort(a, 3)\nprint(a)", "expect": "[1, 3, 4]", "hint": "insort 保持有序"}, {"type": "choice", "q": "「复杂度」关心的核心？", "options": ["代码行数", "数据量增大时步数怎么涨", "内存", "颜色"], "answer": 1, "explain": "复杂度描述规模与开销关系。"}, {"type": "code", "q": "求 [1,5,3] 的和 sum 打印", "code": "print(sum([1, 5, 3]))", "expect": "9", "hint": "sum"}, {"type": "choice", "q": "找出全班最高分成绩用什么？", "options": ["sort 后取末", "max", "循环数", "平均"], "answer": 1, "explain": "max 一行；或排序取末。"}, {"type": "code", "q": "分数 [88,92,75] 排序后打印最高两个", "code": "s = [88, 92, 75]\ns.sort()\nprint(s[-2:])", "expect": "[88, 92]", "hint": "升序后取后两个"}]}, {"id": 29, "no": "ⅩⅩⅨ", "title": "项目：文本冒险游戏", "weeks": "第 15 周", "diff": "★★★", "full": true, "story": {"tutor": "罗伯塔·威廉姆斯（Roberta Williams）", "era": "美国 · 图形冒险游戏先驱", "fact": "威廉姆斯夫妇做的《谜之屋》把文字冒险变成图形游戏，但她始终强调：冒险游戏的内核是「故事状态机」——每个房间有描述，每个选择改变状态。这正是编程里最迷人的设计练习。", "quote": "「让玩家以为自由，其实每步都通向你的故事。」"}, "map": ["状态机", "房间描述", "选择分支", "胜负条件"], "sections": [{"t": "状态 = 房间", "p": "冒险游戏本质是状态机：当前房间 + 玩家输入 → 下一房间。", "code": "rooms = {'hall': {'desc': '大厅，有门', 'to': {'north': 'kitchen'}},\n        'kitchen': {'desc': '厨房', 'to': {'south': 'hall'}}}\ncur = 'hall'\nprint(rooms[cur]['desc'])"}, {"t": "选择驱动转移", "p": "读方向指令，查表跳房间，未知方向提示。", "code": "d = input('去哪: ')\nif d in rooms[cur]['to']:\n    cur = rooms[cur]['to'][d]\nelse:\n    print('走不了')"}, {"t": "道具与条件", "p": "拿到钥匙才能开门：状态加 has_key 布尔。", "code": "has_key = False\nif cur == 'door' and has_key:\n    print('开门了')\nelif cur == 'door':\n    print('需要钥匙')"}, {"t": "胜负条件", "p": "到达终点房间触发胜利，血量归零失败。", "code": "if cur == 'treasure':\n    print('你赢了!')\n    break"}], "quiz": [{"type": "choice", "q": "冒险游戏「当前在哪」本质是？", "options": ["随机", "状态（当前房间）", "分数", "循环次数"], "answer": 1, "explain": "状态机核心：当前状态 + 输入 → 新状态。"}, {"type": "code", "q": "rooms 字典 hall 的 desc 是 \"大厅\"，打印它", "code": "rooms = {'hall': {'desc': '大厅'}}\nprint(rooms['hall']['desc'])", "expect": "大厅", "hint": "双层取"}, {"type": "choice", "q": "玩家输入北走后去哪，用什么查？", "options": ["if 一堆", "查表 rooms[cur][to]", "随机", "排序"], "answer": 1, "explain": "查表驱动转移，优雅可扩展。"}, {"type": "code", "q": "查表：cur=hall，输入 north → kitchen，打印新房间名", "code": "rooms = {'hall': {'to': {'north': 'kitchen'}}}\ncur = 'hall'\ncur = rooms[cur]['to']['north']\nprint(cur)", "expect": "kitchen", "hint": "转移"}, {"type": "choice", "q": "未知方向输入该？", "options": ["报错", "提示走不了并留在原地", "自动走", "清空"], "answer": 1, "explain": "友好提示，状态不变。"}, {"type": "code", "q": "模拟道具：has_key=False 在 door 打印 \"需要钥匙\"", "code": "has_key = False\ncur = \"door\"\nif cur == \"door\" and not has_key:\n    print(\"需要钥匙\")", "expect": "需要钥匙", "hint": "条件门"}, {"type": "choice", "q": "游戏主循环用？", "options": ["while True + break", "for 100 次", "递归无限", "if"], "answer": 0, "explain": "循环直到胜负条件 break。"}, {"type": "code", "q": "while 条件：hp>0 时继续，hp=0 打印 \"游戏结束\"", "code": "hp = 0\nwhile hp > 0:\n    print(\"继续\")\nprint(\"游戏结束\")", "expect": "游戏结束", "hint": "hp=0 不进循环"}, {"type": "choice", "q": "给房间加「第一次进入提示」要？", "options": ["visited 集合记录", "随机", "分数", "名字"], "answer": 1, "explain": "记录已访问状态。"}, {"type": "code", "q": "visited=set()，房间 hall 已去过后跳过 desc，打印 \"又来了\"", "code": "visited = set()\ncur = \"hall\"\nif cur in visited:\n    print(\"又来了\")\nelse:\n    visited.add(cur)\n    print(\"新房间\")", "expect": "新房间", "hint": "首次进入"}], "exam": [{"type": "choice", "q": "文字冒险无需？", "options": ["图形界面", "文本循环和状态", "输入解析", "规则"], "answer": 0, "explain": "纯文本游戏零图形依赖。"}, {"type": "code", "q": "模拟选择：act=\"open\"，打印 \"打开了门\"", "code": "act = \"open\"\nif act == \"open\":\n    print(\"打开了门\")", "expect": "打开了门", "hint": "动作分支"}, {"type": "choice", "q": "玩家输入规范化（去空格小写）的意义？", "options": ["无", "\"North\" 与 \"north\" 统一", "更快", "必须"], "answer": 1, "explain": "归一化输入减少分支判断。"}, {"type": "code", "q": "输入 \" North \" 去空格小写后打印", "code": "d = \" North \".strip().lower()\nprint(d)", "expect": "north", "hint": "strip+lower"}, {"type": "choice", "q": "宝藏在终点房间，判定胜利用？", "options": ["分数", "位置 == 终点", "步数", "时间"], "answer": 1, "explain": "到终点状态触发胜。"}, {"type": "code", "q": "cur == \"treasure\" 打印 \"你赢了\"", "code": "cur = \"treasure\"\nif cur == \"treasure\":\n    print(\"你赢了\")", "expect": "你赢了", "hint": "终局判断"}, {"type": "choice", "q": "给房间图新增房间只需？", "options": ["改大量 if", "在 rooms 字典加一项", "重写游戏", "加变量"], "answer": 1, "explain": "查表结构扩展 = 加数据。"}, {"type": "code", "q": "rooms 加 garden 房间（desc 花园）后打印", "code": "rooms = {'garden': {'desc': '花园'}}\nprint(rooms['garden']['desc'])", "expect": "花园", "hint": "加房间"}, {"type": "choice", "q": "状态机的好处？", "options": ["代码更乱", "逻辑清晰可测试", "更慢", "不能用"], "answer": 1, "explain": "明确的状态与转移可推理。"}, {"type": "code", "q": "打印当前状态摘要：cur=hall，hp=5", "code": "cur = \"hall\"\nhp = 5\nprint(f\"在 {cur}，生命 {hp}\")", "expect": "在 hall，生命 5", "hint": "f-string"}]}, {"id": 30, "no": "ⅩⅩⅩ", "title": "毕业项目与回顾", "weeks": "第 16 周", "diff": "★★★", "full": true, "story": {"tutor": "鼠哥与拉里·佩奇", "era": "你们的 Python 之旅 · 第十六周", "fact": "从 print 到类到项目，你已经走完一本入门书的主线。毕业项目给你一张「总装图」：把函数、类、文件、异常、菜单全用上，做一个迷你图书馆系统。做完它，你就从「会语法」毕业成「能造程序」。", "quote": "「学完不是终点，是你会自己造东西的起点。」"}, "map": ["需求拆解", "类设计", "主流程", "自测清单"], "sections": [{"t": "毕业题：迷你图书馆", "p": "需求：能添加/借出/归还/列出书籍；书有标题/作者/在馆状态；数据存 JSON。", "code": "# 分解：Book 类 + Library 类 + 菜单\nclass Book:\n    def __init__(self, title, author):\n        self.title = title\n        self.author = author\n        self.available = True"}, {"t": "类分工", "p": "Book 管单本书状态；Library 管书集合与操作；菜单循环调 Library 方法。", "code": "class Library:\n    def __init__(self):\n        self.books = []\n    def add(self, b):\n        self.books.append(b)\n    def borrow(self, title):\n        for b in self.books:\n            if b.title == title and b.available:\n                b.available = False\n                return True\n        return False"}, {"t": "持久化", "p": "__init__ 时 load，每次改动 save。", "code": "def save(self):\n    import json\n    data = [{'t': b.title, 'a': b.author, 'av': b.available} for b in self.books]\n    with open('lib.json', 'w') as f:\n        json.dump(data, f)"}, {"t": "回顾清单", "p": "30 章自查：能不看资料写出函数/类/文件读写/异常处理/小项目，就算毕业。", "code": "print('毕业自查：变量/流程/函数/类/文件/异常/项目 —— 全部能上手')"}], "quiz": [{"type": "choice", "q": "毕业项目拆解第一步？", "options": ["写代码", "明确需求与模块划分", "买电脑", "背语法"], "answer": 1, "explain": "先拆需求再动手，工程习惯。"}, {"type": "code", "q": "Book 类有 title/author/available=True，创建并打印 title", "code": "class Book:\n    def __init__(self, title, author):\n        self.title = title\n        self.author = author\n        self.available = True\nb = Book(\"Python\", \"Matthes\")\nprint(b.title)", "expect": "Python", "hint": "实例化"}, {"type": "choice", "q": "借书操作「找到书且可借」要检查？", "options": ["只看标题", "标题匹配且 available", "只看 available", "随机"], "answer": 1, "explain": "双条件：存在且未借出。"}, {"type": "code", "q": "borrow 模拟：书 available=False 后打印状态", "code": "b = {\"title\": \"A\", \"available\": True}\nb[\"available\"] = False\nprint(b[\"available\"])", "expect": "False", "hint": "借出改状态"}, {"type": "choice", "q": "Library 与 Book 的关系？", "options": ["没关系", "Library 包含多个 Book（组合）", "Book 包含 Library", "并列"], "answer": 1, "explain": "Library 持有一组 Book，组合关系。"}, {"type": "code", "q": "Library.add 一本书后 len 打印", "code": "class Library:\n    def __init__(self):\n        self.books = []\n    def add(self, b):\n        self.books.append(b)\nlib = Library()\nlib.add(1)\nprint(len(lib.books))", "expect": "1", "hint": "list 长度"}, {"type": "choice", "q": "菜单主循环里「借书失败」要？", "options": ["崩", "提示原因（不存在或已借出）", "静默", "重开"], "answer": 1, "explain": "borrow 返回 False 时给用户提示。"}, {"type": "code", "q": "列出所有可借书：books 有 title/available，打印可借标题", "code": "books = [{\"title\": \"A\", \"available\": True}, {\"title\": \"B\", \"available\": False}]\nfor b in books:\n    if b[\"available\"]:\n        print(b[\"title\"])", "expect": "A", "hint": "过滤可借"}, {"type": "choice", "q": "数据存取放 JSON 的时机？", "options": ["只在退出", "每次改动后", "启动一次", "不用"], "answer": 1, "explain": "频繁小写防止崩溃丢数据。"}, {"type": "code", "q": "30 章毕业自查打印 \"毕业!\"", "code": "print(\"毕业!\")", "expect": "毕业!", "hint": "结业"}], "exam": [{"type": "choice", "q": "「能用类就用类」正确理解？", "options": ["所有都建类", "有数据和行为时用类，简单时用函数", "不用类", "类最慢"], "answer": 1, "explain": "按需抽象，不过度设计。"}, {"type": "code", "q": "Book 对象列表存 JSON 前转 dict 列表，简化转一条", "code": "import json\nb = {\"title\": \"A\", \"available\": True}\nprint(json.dumps(b, ensure_ascii=False))", "expect": "{\"title\": \"A\", \"available\": true}", "hint": "可序列化"}, {"type": "choice", "q": "还书操作做什么？", "options": ["删书", "available=True", "复制", "换名"], "answer": 1, "explain": "还书 = 状态恢复可借。"}, {"type": "code", "q": "还书：available 从 False 改 True 打印", "code": "b = {\"available\": False}\nb[\"available\"] = True\nprint(b[\"available\"])", "expect": "True", "hint": "恢复"}, {"type": "choice", "q": "项目自查最该检查？", "options": ["代码最短", "核心路径都能跑通", "变量名短", "无注释"], "answer": 1, "explain": "功能正确性是第一验收标准。"}, {"type": "code", "q": "模拟主流程：打印 \"欢迎使用图书馆\"", "code": "print(\"欢迎使用图书馆\")", "expect": "欢迎使用图书馆", "hint": "入口"}, {"type": "choice", "q": "类设计时「图书馆」是类，「书」是？", "options": ["也是类/对象", "字符串", "函数", "模块"], "answer": 1, "explain": "两个都是对象，一集合一成员。"}, {"type": "code", "q": "list 推导：numbers 0-9 中偶数列表打印", "code": "print([n for n in range(10) if n % 2 == 0])", "expect": "[0, 2, 4, 6, 8]", "hint": "推导式"}, {"type": "choice", "q": "30 章下来最该收获的是？", "options": ["背住全部语法", "能独立把一个想法写成能跑的程序", "代码行数", "最快"], "answer": 1, "explain": "工程能力 = 把想法变程序。"}, {"type": "code", "q": "给这段旅程收尾：打印 \"30 章通关\"", "code": "print(\"30 章通关\")", "expect": "30 章通关", "hint": "恭喜"}]}];